QT_ISI(25,{"4265":["(Kepada-Nyalah dikembalikan pengetahuan tentang hari kiamat) bila akan terjadi, tiada seorang pun yang mengetahuinya selain Dia. (Dan tidak ada buah-buahan keluar) menurut suatu qiraat dibaca Tsamaraatin dalam bentuk jamak (dari kelopaknya) dari kelopak-kelopaknya melainkan dengan sepengetahuan-Nya; lafal Akmaam adalah bentuk jamak dari lafal Kimmun (dan tidak seorang perempuan pun mengandung dan tidak pula melahirkan, melainkan dengan sepengetahuan-Nya. Pada hari Tuhan memanggil mereka, \"Di manakah sekutu-sekutu-Ku itu?\" Mereka menjawab, \"Kami nyatakan kepada Engkau) artinya, sekarang Kami beritahukan kepada Engkau (bahwa tidak ada seorang pun di antara kami yang memberikan kesaksian bahwa Engkau punya sekutu.\"",[["۞ إِلَيْهِ","KepadaNya"],["يُرَدُّ","dirujuk"],["عِلْمُ","(yang) pengetahuan"],["ٱلسَّاعَةِ ۚ","(dari) hari kiamat"],["وَمَا","Dan tidak"],["تَخْرُجُ","keluar"],["مِن","sebarang"],["ثَمَرَٰتٍۢ","buah-buahan"],["مِّنْ","daripada"],["أَكْمَامِهَا","penutup mereka"],["وَمَا","dan bukan"],["تَحْمِلُ","beruang"],["مِنْ","sebarang"],["أُنثَىٰ","perempuan"],["وَلَا","dan bukan"],["تَضَعُ","melahirkan anak"],["إِلَّا","kecuali"],["بِعِلْمِهِۦ ۚ","dengan ilmuNya"],["وَيَوْمَ","Dan (hari) itu"],["يُنَادِيهِمْ","Dia akan memanggil mereka"],["أَيْنَ","Di mana (ada)"],["شُرَكَآءِى","rakan kongsi aku"],["قَالُوٓا۟","Mereka akan berkata"],["ءَاذَنَّـٰكَ","Kami mengumumkan (kepada) Kamu"],["مَا","tidak"],["مِنَّا","antara kita"],["مِن","sebarang"],["شَهِيدٍۢ","saksi"]]],"4266":["(Dan lenyaplah) hilanglah (dari mereka apa yang selalu mereka seru) yang selalu mereka sembah (dahulu) di dunia yaitu berhala-berhala (dan mereka yakin) merasa yakin (bahwa tidak ada bagi mereka sesuatu jalan keluar pun) jalan selamat dari azab. Huruf Nafi pada dua tempat tidak beramal, dan jumlah yang dinafikan menduduki tempatnya Maf'ul.",[["وَضَلَّ","Dan hilang"],["عَنْهُم","daripada mereka"],["مَّا","apa"],["كَانُوا۟","mereka adalah"],["يَدْعُونَ","menyeru"],["مِن","sebelum"],["قَبْلُ ۖ","sebelum"],["وَظَنُّوا۟","dan mereka (akan) pasti"],["مَا","(itu) tidak"],["لَهُم","bagi mereka"],["مِّن","sebarang"],["مَّحِيصٍۢ","tempat melarikan diri"]]],"4267":["(Manusia tidak jemu memohon kebaikan) artinya, masih tetap terus meminta kepada Rabbnya akan harta, kesehatan dan lain-lainnya (dan jika ia ditimpa malapetaka) berupa kemiskinan dan kesengsaraan (dia menjadi putus asa lagi putus harapan) dari rahmat Allah. Ayat ini merupakan gambaran bagi keadaan orang-orang kafir, demikian pula gambaran dalam ayat selanjutnya.",[["لَّا","(Tidak) tidak"],["يَسْـَٔمُ","penat"],["ٱلْإِنسَـٰنُ","lelaki"],["مِن","daripada"],["دُعَآءِ","berdoa"],["ٱلْخَيْرِ","(untuk) kebaikan"],["وَإِن","tetapi jika"],["مَّسَّهُ","menyentuhnya"],["ٱلشَّرُّ","yang jahat"],["فَيَـُٔوسٌۭ","maka dia berputus asa"],["قَنُوطٌۭ","(dan) putus asa"]]],"4268":["(Dan sungguh jika) huruf Lamnya menunjukkan makna Qasam (Kami rasakan kepadanya) Kami berikan kepadanya (rahmat) kecukupan dan kesehatan (dari Kami sesudah kesusahan) yakni kesengsaraan dan malapetaka (yang telah menimpanya, pastilah dia berkata, \"Ini adalah hakku) artinya, berkat karyaku sendiri (dan aku tidak yakin bahwa hari Kiamat itu akan datang. Dan sungguh jika) huruf Lamnya menunjukkan makna Qasam (aku dikembalikan kepada Rabbku maka sesungguhnya aku akan memperoleh kebaikan di sisi-Nya\") yakni surga. (Maka Kami benar-benar akan memberitakan kepada orang-orang kafir apa yang telah mereka kerjakan dan akan Kami rasakan kepada mereka azab yang keras) siksaan yang keras. Huruf Lam yang terdapat pada dua Fi'il bermakna Qasam.",[["وَلَئِنْ","Dan sesungguhnya, jika"],["أَذَقْنَـٰهُ","Kita biarkan dia rasa"],["رَحْمَةًۭ","belas kasihan"],["مِّنَّا","daripada Kami"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["ضَرَّآءَ","suatu kesusahan"],["مَسَّتْهُ","(telah) menyentuhnya"],["لَيَقُولَنَّ","dia pasti akan berkata"],["هَـٰذَا","ini (ialah)"],["لِى","(disebabkan) aku"],["وَمَآ","dan bukan"],["أَظُنُّ","aku rasa"],["ٱلسَّاعَةَ","Jam itu"],["قَآئِمَةًۭ","(akan) ditegakkan"],["وَلَئِن","dan jika"],["رُّجِعْتُ","aku dikembalikan"],["إِلَىٰ","kepada"],["رَبِّىٓ","Tuhanku"],["إِنَّ","sesungguhnya"],["لِى","untuk aku"],["عِندَهُۥ","dengan Dia"],["لَلْحُسْنَىٰ ۚ","(akan menjadi) yang terbaik"],["فَلَنُنَبِّئَنَّ","Tetapi Kami pasti akan memaklumkan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["بِمَا","tentang apa"],["عَمِلُوا۟","mereka lakukan"],["وَلَنُذِيقَنَّهُم","dan sesungguhnya Kami akan rasakan mereka"],["مِّنْ","daripada"],["عَذَابٍ","azab"],["غَلِيظٍۢ","teruk"]]],"4269":["(Dan apabila Kami berikan nikmat kepada manusia) yang dimaksud adalah jenis manusia (ia berpaling) tidak mau bersyukur (dan menjauhkan diri) yakni memutarkan badannya seraya menyombongkan diri; menurut suatu qiraat lafal Na-aa dibaca dengan didahulukan huruf Hamzahnya (tetapi apabila ia ditimpa malapetaka maka ia banyak berdoa) banyak permintaannya.",[["وَإِذَآ","Dan apabila"],["أَنْعَمْنَا","Kami melimpahkan nikmat"],["عَلَى","ke atas"],["ٱلْإِنسَـٰنِ","lelaki"],["أَعْرَضَ","dia berpaling"],["وَنَـَٔا","dan menjauhkan diri"],["بِجَانِبِهِۦ","dan menjauhkan diri"],["وَإِذَا","tapi apabila"],["مَسَّهُ","menyentuhnya"],["ٱلشَّرُّ","yang jahat"],["فَذُو","kemudian (dia) kenyang"],["دُعَآءٍ","(dari) doa"],["عَرِيضٍۢ","panjang lebar"]]],"4270":["(Katakanlah, \"Bagaimana pendapat kalian jika ia) yakni Alquran itu (datang dari sisi Allah) sebagaimana yang telah dikatakan oleh Nabi saw. (kemudian kalian mengingkarinya. Siapakah) yakni tiada seorang pun (yang lebih sesat daripada orang yang selalu berada dalam penyimpangan) yakni perselisihan (yang jauh?\") dari kebenaran. Lafal Ba'iidun ini menduduki tempatnya lafal Minkum sebagai penjelasan tentang keadaan mereka.",[["قُلْ","Katakanlah"],["أَرَءَيْتُمْ","Kamu nampak"],["إِن","jika"],["كَانَ","ia adalah"],["مِنْ","daripada"],["عِندِ","daripada"],["ٱللَّهِ","Allah"],["ثُمَّ","kemudian"],["كَفَرْتُم","kamu tidak beriman"],["بِهِۦ","di dalamnya"],["مَنْ","yang"],["أَضَلُّ","(adalah) lebih sesat"],["مِمَّنْ","daripada (seorang) yang"],["هُوَ","dia"],["فِى","(berada) dalam"],["شِقَاقٍۭ","pembangkang"],["بَعِيدٍۢ","jauh"]]],"4271":["(Kami akan memperlihatkan kepada mereka tanda-tanda kekuasaan Kami di segenap penjuru) di segenap penjuru langit dan bumi, yaitu berupa api, tumbuh-tumbuhan dan pohon-pohonan (dan pada diri mereka sendiri) yaitu berupa rapihnya ciptaan Allah dan indahnya hikmah yang terkandung di dalam penciptaan itu (sehingga jelaslah bagi mereka bahwa ia) yakni Alquran itu (adalah benar) diturunkan dari sisi Allah yang di dalamnya dijelaskan masalah hari berbangkit, hisab dan siksaan; maka mereka akan disiksa karena kekafiran mereka terhadap Alquran dan terhadap orang yang Alquran diturunkan kepadanya, yaitu Nabi saw. (Dan apakah Rabbmu tidak cukup bagi kamu) lafal Birabbika adalah Fa'il dari lafal Yakfi (bahwa sesungguhnya Dia menyaksikan segala sesuatu?) lafal ayat ini menjadi Mubdal Minhu yakni, apakah tidak cukup sebagai bukti tentang kebenaranmu bagi mereka, yaitu bahwasanya Rabbmu tiada sesuatu pun yang samar bagi-Nya.",[["سَنُرِيهِمْ","Tidak lama lagi Kami akan tunjukkan kepada mereka"],["ءَايَـٰتِنَا","Tanda-Tanda Kami"],["فِى","dalam"],["ٱلْـَٔافَاقِ","cakrawala"],["وَفِىٓ","dan dalam"],["أَنفُسِهِمْ","diri mereka"],["حَتَّىٰ","sehingga"],["يَتَبَيَّنَ","menjadi jelas"],["لَهُمْ","kepada mereka"],["أَنَّهُ","bahawa ia"],["ٱلْحَقُّ ۗ","(adalah) kebenaran"],["أَوَلَمْ","Adakah (ia) tidak"],["يَكْفِ","mencukupi"],["بِرَبِّكَ","tentang Tuhanmu"],["أَنَّهُۥ","bahawa Dia"],["عَلَىٰ","(sudah) tamat"],["كُلِّ","semua"],["شَىْءٍۢ","benda"],["شَهِيدٌ","seorang Saksi"]]],"4272":["(Ingatlah bahwa sesungguhnya mereka adalah dalam keraguan) yakni keragu-raguan (tentang pertemuan dengan Rabb mereka) karena mereka ingkar kepada adanya hari berbangkit. (Ingatlah, bahwa sesungguhnya Dia) yakni Allah swt. (Maha Meliputi segala sesuatu) yaitu ilmu dan kekuasaan-Nya meliputi segala sesuatu, maka dari itu Dia akan membalas mereka disebabkan kekafiran mereka.",[["أَلَآ","Tidak dinafikan"],["إِنَّهُمْ","mereka"],["فِى","(ada) dalam"],["مِرْيَةٍۢ","keraguan"],["مِّن","tentang"],["لِّقَآءِ","(the) mesyuarat"],["رَبِّهِمْ ۗ","(dengan) Tuhan mereka"],["أَلَآ","Tidak dinafikan"],["إِنَّهُۥ","sesungguhnya, Dia"],["بِكُلِّ","(adalah) daripada semua"],["شَىْءٍۢ","benda"],["مُّحِيطٌۢ","merangkumi"]]],"4273":["(Haa Miim)",[["حمٓ","Ha Mim"]]],"4274":["('Ain Siin Qaaf) kedua ayat ini hanya Allahlah yang mengetahui arti dan maksudnya.",[["عٓسٓقٓ","Ayn Seen Qaaf"]]],"4275":["(Demikianlah) artinya seperti penurunan wahyu ini (telah mewahyukannya kepadamu dan) telah mewahyukan pula (kepada orang-orang yang sebelum kamu, yaitu Allah) lafal Allah menjadi Fa'il dari lafal Yuuhii (Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya.",[["كَذَٰلِكَ","Demikianlah"],["يُوحِىٓ","mendedahkan"],["إِلَيْكَ","kepada kamu"],["وَإِلَى","dan kepada"],["ٱلَّذِينَ","mereka"],["مِن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["ٱللَّهُ","Allah"],["ٱلْعَزِيزُ","Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"4276":["(Kepunyaan-Nyalah apa yang ada di langit dan apa yang ada di bumi) sebagai milik-Nya semua makhluk dan hamba-hamba-Nya. (Dan Dialah Yang Maha Tinggi) di atas semua makhluk-Nya (lagi Maha Besar) atau Maha Agung.",[["لَهُۥ","KepadaNya"],["مَا","(kepunyaan) apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۖ","bumi"],["وَهُوَ","dan Dia"],["ٱلْعَلِىُّ","(adalah) Yang Maha Tinggi"],["ٱلْعَظِيمُ","yang Maha Agung"]]],"4277":["(Hampir saja) dapat dibaca Takaadu atau Yakaadu (langit itu pecah) dibaca Yatafath-tharna dengan huruf tha yang ditasydidkan menurut qiraat lain dibaca Yanfathirna dengan memakai huruf Nun (dari sebelah atasnya) hampir setiap langit itu pecah menimpa yang lainnya karena kebesaran Allah swt. (dan malaikat-malaikat bertasbih serta memuji Rabbnya) disertai dengan mengucapkan puji-pujian (dan memohonkan ampun bagi orang-orang yang ada di bumi) yakni bagi orang-orang yang beriman. (Ingatlah! Bahwa sesungguhnya Allah Dialah Yang Maha Pengampun) kepada kekasih-kekasih-Nya (lagi Maha Penyayang) kepada mereka.",[["تَكَادُ","hampir"],["ٱلسَّمَـٰوَٰتُ","langit"],["يَتَفَطَّرْنَ","putus cinta"],["مِن","daripada"],["فَوْقِهِنَّ ۚ","di atas mereka"],["وَٱلْمَلَـٰٓئِكَةُ","dan para Malaikat"],["يُسَبِّحُونَ","bertasbih"],["بِحَمْدِ","(yang) pujian"],["رَبِّهِمْ","(dari) Tuhan mereka"],["وَيَسْتَغْفِرُونَ","dan memohon ampun"],["لِمَن","untuk mereka"],["فِى","pada"],["ٱلْأَرْضِ ۗ","bumi"],["أَلَآ","Tidak dinafikan"],["إِنَّ","sesungguhnya"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلْغَفُورُ","(ialah) Yang Maha Pengampun"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"4278":["(Dan orang-orang yang mengambil selain Allah) mengambil berhala-berhala (sebagai pelindung-pelindung, Allah mengawasi) mencatat (perbuatan mereka) untuk membalas mereka kelak (dan kamu bukanlah orang yang diserahi mengawasi mereka) untuk memperoleh apa yang diminta dari mereka, tugasmu tiada lain hanya menyampaikan.",[["وَٱلَّذِينَ","Dan orang yang"],["ٱتَّخَذُوا۟","ambil"],["مِن","selain"],["دُونِهِۦٓ","selain"],["أَوْلِيَآءَ","pelindung"],["ٱللَّهُ","Allah"],["حَفِيظٌ","(adalah) seorang Penjaga"],["عَلَيْهِمْ","atas mereka"],["وَمَآ","dan bukan"],["أَنتَ","kamu"],["عَلَيْهِم","(berada) atas mereka"],["بِوَكِيلٍۢ","seorang pengurus"]]],"4279":["(Demikianlah) sebagaimana penurunan wahyu ini (Kami wahyukan kepadamu Alquran dalam bahasa Arab supaya kamu memberi peringatan) dengannya, (kepada Umulquraa dan penduduk negeri-negeri sekelilingnya) yaitu penduduk kota Mekah dan semua manusia (serta memberi peringatan pula) kepada manusia (tentang hari berkumpul) yakni hari kiamat, yang pada hari itu semua makhluk dikumpulkan (yang tidak ada keraguan) atau keragu-raguan (padanya. Segolongan) dari mereka (masuk surga dan segolongan yang lain masuk Sa'ir) yakni neraka.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["أَوْحَيْنَآ","Kami telah mendedahkan"],["إِلَيْكَ","kepada kamu"],["قُرْءَانًا","sebuah Al-Quran"],["عَرَبِيًّۭا","(dalam) bahasa Arab"],["لِّتُنذِرَ","supaya kamu memberi amaran"],["أُمَّ","(si) ibu"],["ٱلْقُرَىٰ","(dari) bandar-bandar"],["وَمَنْ","dan sesiapa"],["حَوْلَهَا","(ada) di sekelilingnya"],["وَتُنذِرَ","dan memberi amaran"],["يَوْمَ","hari"],["ٱلْجَمْعِ","(daripada) Perhimpunan"],["لَا","(ada) tidak"],["رَيْبَ","keraguan"],["فِيهِ ۚ","di dalamnya"],["فَرِيقٌۭ","Sebuah parti"],["فِى","(akan) masuk"],["ٱلْجَنَّةِ","Syurga"],["وَفَرِيقٌۭ","dan pesta"],["فِى","dalam"],["ٱلسَّعِيرِ","api yang menyala-nyala"]]],"4280":["(Dan kalau Allah menghendaki niscaya Allah menjadikan mereka satu umat) artinya memeluk satu agama, yaitu agama Islam (tetapi Dia memasukkan orang-orang yang dikehendaki-Nya ke dalam rahmat-Nya. Dan orang-orang yang lalim) yaitu orang-orang kafir (tidak ada bagi mereka seorang pelindung pun dan tidak pula seorang penolong) yang dapat menolak azab Allah dari diri mereka.",[["وَلَوْ","Dan jika"],["شَآءَ","Allah menghendaki"],["ٱللَّهُ","Allah menghendaki"],["لَجَعَلَهُمْ","Dia boleh membuat mereka"],["أُمَّةًۭ","sesebuah komuniti"],["وَٰحِدَةًۭ","satu"],["وَلَـٰكِن","tetapi"],["يُدْخِلُ","Dia mengaku"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["فِى","dalam (ke)"],["رَحْمَتِهِۦ ۚ","KerahimanNya"],["وَٱلظَّـٰلِمُونَ","Dan orang-orang yang zalim"],["مَا","tidak"],["لَهُم","bagi mereka"],["مِّن","sebarang"],["وَلِىٍّۢ","pelindung"],["وَلَا","dan bukan"],["نَصِيرٍ","mana-mana pembantu"]]],"4281":["(Atau patutkah mereka mengambil selain-Nya) mengambil berhala-berhala (sebagai pelindung-pelindung) lafal Am adalah Munqathi'ah yang maknanya sama dengan lafal Bal yang menunjukkan makna Intiqal; Hamzahnya atau makna Istifhamnya menunjukkan pengertian ingkar. Maksudnya yang diambil oleh mereka itu bukanlah pelindung-pelindung mereka. (Maka Allah, Dialah Pelindung) Penolong bagi orang-orang Mukmin, huruf Fa di sini hanya untuk Athaf saja (dan Dia menghidupkan orang-orang yang mati dan Dia adalah Maha Kuasa atas segala sesuatu.)",[["أَمِ","Atau"],["ٱتَّخَذُوا۟","adakah mereka telah mengambil"],["مِن","selain Dia"],["دُونِهِۦٓ","selain Dia"],["أَوْلِيَآءَ ۖ","pelindung"],["فَٱللَّهُ","Tetapi Allah"],["هُوَ","Dia"],["ٱلْوَلِىُّ","(ialah) Pelindung"],["وَهُوَ","dan Dia"],["يُحْىِ","memberi kehidupan"],["ٱلْمَوْتَىٰ","(kepada) orang mati"],["وَهُوَ","Dan Dia"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"]]],"4282":["(Dan apa yang kalian perselisihkan) dengan orang-orang kafir (tentang sesuatu perkara) yang menyangkut masalah agama dan masalah-masalah lainnya (maka putusannya) dikembalikan (kepada Allah) kelak di hari kiamat yaitu Dia akan memutuskan perkara itu di antara kalian. Katakanlah kepada mereka, (\"Itulah Allah, Rabbku, kepada-Nyalah aku bertawakal dan kepada-Nyalah aku kembali) yakni dikembalikan.",[["وَمَا","Dan apa sahaja"],["ٱخْتَلَفْتُمْ","kamu berbeza"],["فِيهِ","di dalamnya"],["مِن","daripada"],["شَىْءٍۢ","sesuatu perkara"],["فَحُكْمُهُۥٓ","maka ketetapannya"],["إِلَى","(adalah) kepada"],["ٱللَّهِ ۚ","Allah"],["ذَٰلِكُمُ","Itu"],["ٱللَّهُ","(ialah) Allah"],["رَبِّى","Tuhanku"],["عَلَيْهِ","atas Dia"],["تَوَكَّلْتُ","Aku meletakkan kepercayaan aku"],["وَإِلَيْهِ","dan kepada-Nya"],["أُنِيبُ","aku berpaling"]]],"4283":["(Pencipta langit dan bumi) Dialah Yang mengadakan langit dan bumi (Dia menjadikan bagi kalian dari jenis kalian sendiri pasangan-pasangan) sewaktu Dia menciptakan Hawa dari tulang rusuk Adam (dan dari jenis binatang ternak pasangan-pasangan) ada jenis jantan dan ada jenis betina (dijadikan-Nya kalian berkembang biak) maksudnya, mengembangbiakkan kalian (dengan jalan itu) yaitu melalui proses perjodohan. Dengan kata lain, Dia memperbanyak kalian melalui anak beranak. Dhamir yang ada kembali kepada manusia dan binatang ternak dengan ungkapan yang lebih memprioritaskan manusia. (Tidak ada sesuatu pun yang serupa dengan Dia) huruf Kaf adalah Zaidah, karena sesungguhnya Allah swt. tiada sesuatu pun yang semisal dengan-Nya (dan Dialah Yang Maha Mendengar) semua apa yang dikatakan (lagi Maha Melihat) semua apa yang dikerjakan.",[["فَاطِرُ","(The) Pencipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["جَعَلَ","Dia buat"],["لَكُم","bagi kamu"],["مِّنْ","daripada"],["أَنفُسِكُمْ","kamu sendiri"],["أَزْوَٰجًۭا","pasangan"],["وَمِنَ","dan antara"],["ٱلْأَنْعَـٰمِ","lembu itu"],["أَزْوَٰجًۭا ۖ","pasangan"],["يَذْرَؤُكُمْ","Dia melipatgandakan kamu"],["فِيهِ ۚ","dengan itu"],["لَيْسَ","(Ada) tidak"],["كَمِثْلِهِۦ","seperti Dia"],["شَىْءٌۭ ۖ","sesuatu"],["وَهُوَ","dan Dia"],["ٱلسَّمِيعُ","(ialah) Yang Maha Mendengar"],["ٱلْبَصِيرُ","yang Maha Melihat"]]],"4284":["(Kepunyaan-Nyalah khazanah langit dan bumi) yakni kunci-kunci khazanahnya, yaitu berupa hujan, tumbuh-tumbuhan dan lain sebagainya. (Dia melapangkan rezeki) meluaskannya (bagi siapa yang dikehendaki-Nya) sebagai ujian baginya (dan membatasinya) menyempitkannya bagi siapa yang dikehendaki-Nya sebagai cobaan baginya (Sesungguhnya Dia Maha Mengetahui segala sesuatu.)",[["لَهُۥ","KepunyaanNya (milik)"],["مَقَالِيدُ","(the) kunci"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["يَبْسُطُ","Dia memanjangkan"],["ٱلرِّزْقَ","peruntukan itu"],["لِمَن","untuk siapa"],["يَشَآءُ","Dia kehendaki"],["وَيَقْدِرُ ۚ","dan menyekat"],["إِنَّهُۥ","Sesungguhnya Dia"],["بِكُلِّ","daripada setiap"],["شَىْءٍ","perkara"],["عَلِيمٌۭ","Maha Mengetahui"]]],"4285":["(Dia telah mensyariatkan bagi kalian tentang agama apa yang telah diwasiatkan-Nya kepada Nuh) dia adalah nabi pertama yang membawa syariat (yang telah Kami wahyukan kepadamu dan apa yang telah Kami wasiatkan kepada Ibrahim, Musa dan Isa yaitu, \"Tegakkanlah agama dan janganlah kalian berpecah-belah tentangnya.\") inilah ajaran yang telah disyariatkan dan yang telah diwasiatkan serta yang telah diwahyukan kepada Nabi Muhammad saw. yaitu ajaran Tauhid. (Amat berat) amat besarlah (bagi orang-orang musyrik agama yang kamu seru mereka kepadanya) yakni ajaran tauhid (Allah menarik kepada agama itu) kepada ajaran tauhid (orang yang dikehendaki-Nya dan memberi petunjuk kepada agama-Nya orang yang kembali kepada-Nya) orang yang mau menerima untuk berbuat taat kepada-Nya.",[["۞ شَرَعَ","Dia telah menetapkan"],["لَكُم","bagi kamu"],["مِّنَ","daripada"],["ٱلدِّينِ","agama itu"],["مَا","apa"],["وَصَّىٰ","Dia menyuruh"],["بِهِۦ","ke atas"],["نُوحًۭا","Nuh"],["وَٱلَّذِىٓ","dan yang"],["أَوْحَيْنَآ","Kami telah mendedahkan"],["إِلَيْكَ","kepada kamu"],["وَمَا","dan apa"],["وَصَّيْنَا","Kami menyuruh"],["بِهِۦٓ","ke atas"],["إِبْرَٰهِيمَ","Ibrahim"],["وَمُوسَىٰ","dan Musa"],["وَعِيسَىٰٓ ۖ","dan Isa"],["أَنْ","Kepada"],["أَقِيمُوا۟","dirikanlah"],["ٱلدِّينَ","agama itu"],["وَلَا","dan bukan"],["تَتَفَرَّقُوا۟","berbelah bahagi"],["فِيهِ ۚ","di dalamnya"],["كَبُرَ","Sukar"],["عَلَى","pada"],["ٱلْمُشْرِكِينَ","orang musyrik"],["مَا","apa"],["تَدْعُوهُمْ","kamu memanggil mereka"],["إِلَيْهِ ۚ","kepadanya"],["ٱللَّهُ","Allah"],["يَجْتَبِىٓ","memilih"],["إِلَيْهِ","untuk diriNya sendiri"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["وَيَهْدِىٓ","dan panduan"],["إِلَيْهِ","kepada diriNya"],["مَن","sesiapa sahaja"],["يُنِيبُ","berpusing"]]],"4286":["(Dan mereka tidak berpecah-belah) yaitu para pemeluk agama-agama tentang agamanya, umpamanya sebagian dari mereka berpegang kepada ajaran tauhid dan sebagian lainnya kafir (melainkan sesudah datangnya pengetahuan kepada mereka) yakni pengetahuan tentang ajaran tauhid (karena kedengkian) yang dimaksud adalah orang-orang kafir (di antara mereka. Kalau tidaklah karena sesuatu ketetapan yang telah ada dari Rabbmu dahulunya) untuk menangguhkan pembalasan (sampai kepada waktu yang ditentukan) yakni hari kiamat (pastilah telah diputuskan di antara mereka) yaitu diazab-Nya orang-orang kafir di dunia. (Dan sesungguhnya orang-orang yang diwariskan kepada mereka Alkitab sesudah mereka) mereka adalah orang-orang Yahudi dan orang-orang Nasrani (benar-benar dalam keraguan terhadapnya) terhadap Nabi saw. (yang mengguncangkan) yang menyebabkan keragu-raguan.",[["وَمَا","Dan tidak"],["تَفَرَّقُوٓا۟","mereka menjadi berpecah belah"],["إِلَّا","sehingga"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["مَا","[apa]"],["جَآءَهُمُ","datang kepada mereka"],["ٱلْعِلْمُ","pengetahuan itu"],["بَغْيًۢا","(daripada) persaingan"],["بَيْنَهُمْ ۚ","antara mereka"],["وَلَوْلَا","Dan jika tidak"],["كَلِمَةٌۭ","(untuk) perkataan"],["سَبَقَتْ","(yang) mendahului"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["إِلَىٰٓ","bagi"],["أَجَلٍۢ","satu istilah"],["مُّسَمًّۭى","ditentukan"],["لَّقُضِىَ","nescaya ia (akan) diselesaikan"],["بَيْنَهُمْ ۚ","antara mereka"],["وَإِنَّ","Dan sesungguhnya"],["ٱلَّذِينَ","orang yang"],["أُورِثُوا۟","dijadikan untuk mewarisi"],["ٱلْكِتَـٰبَ","Kitab"],["مِنۢ","selepas mereka"],["بَعْدِهِمْ","selepas mereka"],["لَفِى","(ada) pasti dalam"],["شَكٍّۢ","keraguan"],["مِّنْهُ","berkenaan dengannya"],["مُرِيبٍۢ","meresahkan"]]],"4287":["(Maka karena itu) karena ajaran tauhid itu (serulah) manusia, hai Muhammad (dan tetaplah) berpegang teguh kepada ajaran tauhid (sebagaimana diperintahkan kepadamu dan janganlah mengikuti hawa nafsu mereka) yang membujukmu untuk meninggalkan ajaran tauhid (dan katakanlah, \"Aku beriman kepada semua Kitab yang diturunkan Allah dan aku diperintahkan supaya berlaku adil) bersikap adil (di antara kalian) dalam masalah memutuskan hukum (Allahlah Rabb kami dan Rabb kalian. Bagi kami amal-amal kami dan bagi kalian amal-amal kalian) masing-masing akan mendapatkan balasan amalnya sendiri-sendiri. (Tidak ada pertengkaran) persengketaan (antara kami dan kalian) ayat ini diturunkan sebelum nabi diperintahkan untuk berjihad melawan mereka (Allah mengumpulkan antara kita) pada hari semua manusia dikembalikan kepada-Nya untuk menjalani peradilan di hadapan-Nya (dan kepada-Nyalah kembali kita\") kita akan dikembalikan.",[["فَلِذَٰلِكَ","Jadi untuk itu"],["فَٱدْعُ ۖ","kemudian jemput"],["وَٱسْتَقِمْ","dan berdiri teguh"],["كَمَآ","seperti"],["أُمِرْتَ ۖ","kamu diperintahkan"],["وَلَا","dan jangan"],["تَتَّبِعْ","ikut"],["أَهْوَآءَهُمْ ۖ","keinginan mereka"],["وَقُلْ","tetapi katakan"],["ءَامَنتُ","aku beriman"],["بِمَآ","pada apa"],["أَنزَلَ","Allah telah menurunkan"],["ٱللَّهُ","Allah telah menurunkan"],["مِن","daripada"],["كِتَـٰبٍۢ ۖ","(the) Buku"],["وَأُمِرْتُ","dan aku diperintahkan"],["لِأَعْدِلَ","bahawa aku melakukan keadilan"],["بَيْنَكُمُ ۖ","antara kamu"],["ٱللَّهُ","Allah"],["رَبُّنَا","(ialah) Tuhan kami"],["وَرَبُّكُمْ ۖ","dan Tuhanmu"],["لَنَآ","Untuk kita"],["أَعْمَـٰلُنَا","perbuatan kita"],["وَلَكُمْ","dan untuk kamu"],["أَعْمَـٰلُكُمْ ۖ","perbuatan kamu"],["لَا","(Ada) tidak"],["حُجَّةَ","hujah"],["بَيْنَنَا","antara kita"],["وَبَيْنَكُمُ ۖ","dan antara kamu"],["ٱللَّهُ","Allah"],["يَجْمَعُ","akan berhimpun"],["بَيْنَنَا ۖ","[antara] kita"],["وَإِلَيْهِ","dan kepada-Nya"],["ٱلْمَصِيرُ","(ialah) pulangan terakhir"]]],"4288":["(Dan orang-orang yang membantah) agama (Allah) maksudnya, membantah Nabi-Nya (sesudah agama itu diterima) sesudah diimani dan nyatanya mukjizat yang dibawanya, yang dimaksud dengan mereka adalah orang-orang Yahudi (maka bantahan mereka itu sia-sia saja) atau batil (di sisi Rabb mereka. Mereka mendapat kemurkaan Allah dan bagi mereka azab yang sangat keras.)",[["وَٱلَّذِينَ","Dan orang yang"],["يُحَآجُّونَ","berhujah"],["فِى","tentang"],["ٱللَّهِ","Allah"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["مَا","[apa]"],["ٱسْتُجِيبَ","balasan telah dibuat kepada-Nya"],["لَهُۥ","balasan telah dibuat kepada-Nya"],["حُجَّتُهُمْ","hujah mereka"],["دَاحِضَةٌ","(adalah) tidak sah"],["عِندَ","dengan"],["رَبِّهِمْ","Tuhan mereka"],["وَعَلَيْهِمْ","dan atas mereka"],["غَضَبٌۭ","(adalah) kemurkaan"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌۭ","(ialah) azab"],["شَدِيدٌ","teruk"]]],"4289":["(Allahlah yang menurunkan Kitab) Alquran (dengan membawa kebenaran) lafal Bil Haqqi berta'alluq kepada lafal Anzala (dan neraca), keadilan. (Dan tahukah kamu) apakah kamu tahu (boleh jadi kiamat itu) yakni kedatangannya (sudah dekat?) lafal La'alla amalnya di-ta'alluq-kan kepada Fi'il dan lafal-lafal sesudahnya berkedudukan sebagai dua Maf'ul.",[["ٱللَّهُ","Allah"],["ٱلَّذِىٓ","(ialah) Yang"],["أَنزَلَ","(telah) diturunkan"],["ٱلْكِتَـٰبَ","Kitab"],["بِٱلْحَقِّ","dalam kebenaran"],["وَٱلْمِيزَانَ ۗ","dan Baki"],["وَمَا","Dan apa"],["يُدْرِيكَ","akan membuat kamu tahu"],["لَعَلَّ","barangkali"],["ٱلسَّاعَةَ","Jam itu"],["قَرِيبٌۭ","(ada) dekat"]]],"4290":["(Orang-orang yang tidak beriman kepada hari kiamat meminta supaya hari itu segera didatangkan) mereka mengatakan, \"Kapan hari kiamat itu akan datang,\" demikian itu karena mereka menduga bahwa hari kiamat tidak akan datang (dan orang-orang yang beriman, merasa takut) merasa khawatir (kepadanya dan mereka yakin bahwa kiamat itu adalah benar akan terjadi Ketahuilah bahwa sesungguhnya orang-orang yang membantah) mendebat (tentang terjadinya hari kiamat itu benar-benar dalam kesesatan yang jauh.)",[["يَسْتَعْجِلُ","Berusaha untuk menyegerakan"],["بِهَا","[daripada] itu"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["بِهَا ۖ","di dalamnya"],["وَٱلَّذِينَ","dan orang yang"],["ءَامَنُوا۟","beriman"],["مُشْفِقُونَ","(adalah) takut"],["مِنْهَا","daripadanya"],["وَيَعْلَمُونَ","dan tahu"],["أَنَّهَا","bahawa ia"],["ٱلْحَقُّ ۗ","(adalah) kebenaran"],["أَلَآ","Tidak dinafikan"],["إِنَّ","sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يُمَارُونَ","pertikaian"],["فِى","tentang"],["ٱلسَّاعَةِ","Jam itu"],["لَفِى","(ada) sudah pasti dalam"],["ضَلَـٰلٍۭ","ralat"],["بَعِيدٍ","jauh"]]],"4291":["(Allah Maha Lembut terhadap hamba-hamba-Nya) baik terhadap mereka yang berbakti maupun terhadap mereka yang durhaka, karena Dia tidak membinasakan mereka melalui kelaparan sebab kemaksiatan mereka (Dia memberi rezeki kepada siapa yang dikehendaki-Nya) artinya, Dia memberikan kepada masing-masingnya apa yang Dia kehendaki (dan Dialah Yang Maha Kuat) atas semua kehendak-Nya (lagi Maha Perkasa) Maha Menang atas semua perkara-Nya.",[["ٱللَّهُ","Allah"],["لَطِيفٌۢ","(adalah) Halus"],["بِعِبَادِهِۦ","dengan hamba-hamba-Nya"],["يَرْزُقُ","Dia memberi rezeki"],["مَن","(kepada) siapa"],["يَشَآءُ ۖ","Dia kehendaki"],["وَهُوَ","Dan Dia"],["ٱلْقَوِىُّ","(ialah) Yang Maha Kuat"],["ٱلْعَزِيزُ","Yang Maha Perkasa"]]],"4292":["(Barang siapa yang menghendaki) dengan amalnya (keuntungan akhirat) pahala akhirat (Kami tambahkan keuntungan itu baginya) dilipatgandakan pahalanya yaitu satu kebaikan dibalas dengan sepuluh kebaikan dan bahkan lebih dari itu (dan barang siapa yang menghendaki keuntungan di dunia, Kami berikan kepadanya sebagian dari keuntungan dunia) tanpa dilipatgandakan (dan tidak ada baginya suatu bagian pun di akhirat.)",[["مَن","Siapa pun"],["كَانَ","ialah"],["يُرِيدُ","berkeinginan"],["حَرْثَ","(the) tuaian"],["ٱلْـَٔاخِرَةِ","(dari) Akhirat"],["نَزِدْ","Kita bertambah"],["لَهُۥ","baginya"],["فِى","dalam"],["حَرْثِهِۦ ۖ","hasil tuaiannya"],["وَمَن","Dan sesiapa"],["كَانَ","ialah"],["يُرِيدُ","berkeinginan"],["حَرْثَ","(the) tuaian"],["ٱلدُّنْيَا","dunia"],["نُؤْتِهِۦ","Kita beri dia"],["مِنْهَا","daripadanya"],["وَمَا","tetapi tidak"],["لَهُۥ","baginya"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["مِن","sebarang"],["نَّصِيبٍ","kongsi"]]],"4293":["(Apakah) sebenarnya (mereka mempunyai) yang dimaksud adalah orang-orang kafir Mekah (sesembahan-sesembahan) yaitu setan-setan mereka (yang mensyariatkan) maksudnya, sesembahan-sesembahan mereka itu mensyariatkan (untuk mereka) untuk orang-orang kafir (agama) yang rusak (yang tidak diizinkan oleh Allah?) seperti ajaran menyekutukan Allah dan mengingkari adanya hari berbangkit. (Sekiranya tidak ada ketetapan yang menentukan dari Allah) ketentuan yang telah terdahulu yang menetapkan bahwa pembalasan itu pada hari kiamat (tentulah telah diputuskan di antara mereka) dan orang-orang yang beriman, yaitu orang-orang kafir akan langsung diazab di dunia. (Dan sesungguhnya orang-orang yang zalim itu) yakni orang-orang kafir (akan memperoleh azab yang amat pedih) yang amat menyakitkan.",[["أَمْ","Atau"],["لَهُمْ","bagi mereka"],["شُرَكَـٰٓؤُا۟","(adalah) rakan kongsi"],["شَرَعُوا۟","yang telah ditahbiskan"],["لَهُم","bagi mereka"],["مِّنَ","daripada"],["ٱلدِّينِ","agama itu"],["مَا","apa"],["لَمْ","tidak"],["يَأْذَنۢ","Allah telah mengizinkannya"],["بِهِ","Allah telah mengizinkannya"],["ٱللَّهُ ۚ","Allah telah mengizinkannya"],["وَلَوْلَا","Dan jika tidak"],["كَلِمَةُ","(untuk) perkataan"],["ٱلْفَصْلِ","penentu"],["لَقُضِىَ","nescaya ia (akan) dihakimi"],["بَيْنَهُمْ ۗ","antara mereka"],["وَإِنَّ","Dan sesungguhnya"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["لَهُمْ","bagi mereka"],["عَذَابٌ","(adalah) hukuman"],["أَلِيمٌۭ","yang pedih"]]],"4294":["(Kamu lihat orang-orang yang zalim) kelak di hari kiamat (sangat ketakutan) sangat ngeri (karena kejahatan-kejahatan yang telah mereka kerjakan) di dunia, mereka takut akan menerima pembalasannya (sedangkan pembalasan itu) yakni pembalasan perbuatan jahat mereka itu (menimpa mereka) pasti menimpa mereka kelak di hari kiamat. (Dan orang-orang yang beriman serta mengerjakan amal yang saleh berada di dalam taman-taman surga) berada di surga yang paling indah bila dibandingkan dengan orang-orang yang derajatnya di bawah mereka (mereka memperoleh apa yang mereka kehendaki di sisi Rabb mereka. Yang demikian itu adalah karunia yang besar.)",[["تَرَى","Kamu akan melihat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["مُشْفِقِينَ","takut"],["مِمَّا","tentang apa"],["كَسَبُوا۟","mereka perolehi"],["وَهُوَ","dan ia"],["وَاقِعٌۢ","(akan) menimpa"],["بِهِمْ ۗ","[pada] mereka"],["وَٱلَّذِينَ","Dan orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["فِى","(akan) masuk"],["رَوْضَاتِ","padang rumput berbunga"],["ٱلْجَنَّاتِ ۖ","(dari) Syurga"],["لَهُم","bagi mereka"],["مَّا","(adalah) apa sahaja"],["يَشَآءُونَ","mereka mahu"],["عِندَ","dengan"],["رَبِّهِمْ ۚ","Tuhan mereka"],["ذَٰلِكَ","Itu"],["هُوَ","ia"],["ٱلْفَضْلُ","(ialah) Kurnia"],["ٱلْكَبِيرُ","yang Agung"]]],"4295":["(Itulah karunia yang dengan itu Allah menggembirakan) berasal dari lafal Al-Bisyarah (hamba-hamba-Nya yang beriman dan mengerjakan amal yang saleh. Katakanlah, \"Aku tidak meminta kepada kalian atas seruanku ini) atas penyampaian risalah ini (sesuatu upah pun kecuali kasih sayang dalam kekeluargaan) Istitsna di sini bersifat Munqathi' maksudnya, tetapi aku meminta kepada kalian hendaknya kalian mencintai kekerabatan denganku yang memang pada kenyataannya telah ada hubungan kerabat antara kalian dan aku. Karena sesungguhnya bagi Nabi saw. mempunyai hubungan kekerabatan dengan setiap puak yang berakar dari kabilah Quraisy. (Dan siapa yang mengerjakan kebaikan) yakni ketaatan (akan Kami tambahkan baginya kebaikan pada kebaikannya itu) yaitu dengan melipatgandakan pahala kebaikannya. (Sesungguhnya Allah Maha Pengampun) terhadap dosa-dosa (lagi Maha Mensyukuri) bagi orang yang sedikit beramal kebaikan, karenanya Dia melipatgandakan pahalanya.",[["ذَٰلِكَ","Itu"],["ٱلَّذِى","(adalah) yang mana"],["يُبَشِّرُ","Allah memberi khabar gembira"],["ٱللَّهُ","Allah memberi khabar gembira"],["عِبَادَهُ","(kepada) hamba-hamba-Nya"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ ۗ","amal soleh"],["قُل","Katakanlah"],["لَّآ","Tidak"],["أَسْـَٔلُكُمْ","aku tanya kamu"],["عَلَيْهِ","baginya"],["أَجْرًا","sebarang bayaran"],["إِلَّا","kecuali"],["ٱلْمَوَدَّةَ","cinta itu"],["فِى","antara"],["ٱلْقُرْبَىٰ ۗ","kaum kerabat"],["وَمَن","Dan sesiapa"],["يَقْتَرِفْ","memperolehi"],["حَسَنَةًۭ","apa-apa kebaikan"],["نَّزِدْ","Kita bertambah"],["لَهُۥ","baginya"],["فِيهَا","di dalamnya"],["حُسْنًا ۚ","kebaikan"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["شَكُورٌ","Semua-Menghargai"]]],"4296":["(Bahkan) tetapi (mereka mengatakan, \"Dia telah mengada-adakan dusta terhadap Allah\") yaitu dengan menisbatkan Alquran, bahwasanya diturunkan dari sisi Allah. (Maka jika Allah menghendaki niscaya Dia mengunci mati) maksudnya, mengikat (hatimu) dengan kesabaran, sehingga kamu sabar di dalam menghadapi perlakuan mereka yang menyakitkan melalui perkataan dan perbuatan-perbuatan lainnya; memang Allah swt. telah melaksanakan apa yang dikehendaki-Nya itu (dan Allah menghapuskan yang batil) yakni perkara yang telah mereka katakan itu (dan membenarkan yang hak) menetapkannya (dengan kalimat-kalimat-Nya) yang diturunkan kepada Nabi-Nya. (Sesungguhnya Dia Maha Mengetahui segala isi hati) mengetahui apa yang terkandung di dalam kalbu.",[["أَمْ","Atau"],["يَقُولُونَ","(lakukan) mereka berkata"],["ٱفْتَرَىٰ","Dia telah mencipta"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["كَذِبًۭا ۖ","satu pembohongan"],["فَإِن","Tetapi jika"],["يَشَإِ","Allah menghendaki"],["ٱللَّهُ","Allah menghendaki"],["يَخْتِمْ","Dia akan mengelak"],["عَلَىٰ","[lebih]"],["قَلْبِكَ ۗ","hati kamu"],["وَيَمْحُ","Dan Allah menghapuskan"],["ٱللَّهُ","Dan Allah menghapuskan"],["ٱلْبَـٰطِلَ","kepalsuan itu"],["وَيُحِقُّ","dan menetapkan"],["ٱلْحَقَّ","kebenaran"],["بِكَلِمَـٰتِهِۦٓ ۚ","dengan Firman-Nya"],["إِنَّهُۥ","Sesungguhnya Dia"],["عَلِيمٌۢ","(adalah) Maha Mengetahui"],["بِذَاتِ","tentang apa"],["ٱلصُّدُورِ","(ada dalam) buah dada"]]],"4297":["(Dan Dialah yang menerima tobat dari hamba-hamba-Nya) dari sebagian di antara mereka (dan memaafkan kesalahan-kesalahan) yang para pelakunya telah bertobat daripadanya (dan mengetahui apa yang kalian kerjakan) dapat dibaca Taf'aluuna atau Yaf'aluuna; kalau dibaca Yaf'aluuna artinya, mengetahui apa yang mereka kerjakan.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["يَقْبَلُ","menerima"],["ٱلتَّوْبَةَ","taubat itu"],["عَنْ","daripada"],["عِبَادِهِۦ","hambanya"],["وَيَعْفُوا۟","dan pengampunan"],["عَنِ","[daripada]"],["ٱلسَّيِّـَٔاتِ","yang jahat"],["وَيَعْلَمُ","dan Dia mengetahui"],["مَا","apa"],["تَفْعَلُونَ","kamu lakukan"]]],"4298":["(Dan Dia memperkenankan doa orang-orang yang beriman serta mengerjakan amal yang saleh) maksudnya, Dia mengabulkan apa yang mereka minta (dan menambah kepada mereka) maksudnya, Allah menambah kepada mereka (dari karunia-Nya. Dan orang-orang yang kafir bagi mereka azab yang sangat keras.)",[["وَيَسْتَجِيبُ","Dan Dia menjawab"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["وَيَزِيدُهُم","dan bertambah (bagi) mereka"],["مِّن","daripada"],["فَضْلِهِۦ ۚ","Bounty-Nya"],["وَٱلْكَـٰفِرُونَ","Dan orang-orang kafir"],["لَهُمْ","bagi mereka"],["عَذَابٌۭ","(akan menjadi) azab"],["شَدِيدٌۭ","teruk"]]],"4299":["(Dan jika Allah melapangkan rezeki kepada hamba-hamba-Nya) semuanya (tentulah mereka akan melampaui batas) semuanya akan melampaui batas; tentulah mereka akan berlaku sewenang-wenang (di muka bumi, tetapi Allah menurunkan) dapat dibaca Yunazzilu atau Yunzilu, yakni menurunkan rezeki-Nya (apa yang dikehendaki-Nya dengan ukuran) maka Dia melapangkan rezeki itu kepada sebagian hamba-hamba-Nya, sedangkan yang lainnya tidak; dan timbulnya sikap melampaui batas ini dari melimpahnya rezeki. (Sesungguhnya Dia Maha Mengetahui keadaan hamba-hamba-Nya lagi Maha Melihat.)",[["۞ وَلَوْ","Dan jika"],["بَسَطَ","Allah memanjangkan"],["ٱللَّهُ","Allah memanjangkan"],["ٱلرِّزْقَ","peruntukan itu"],["لِعِبَادِهِۦ","untuk hamba-Nya"],["لَبَغَوْا۟","nescaya mereka akan memberontak"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَلَـٰكِن","tetapi"],["يُنَزِّلُ","Dia menghantar turun"],["بِقَدَرٍۢ","dalam (sewajarnya) ukuran"],["مَّا","apa"],["يَشَآءُ ۚ","Dia kehendaki"],["إِنَّهُۥ","Sesungguhnya Dia"],["بِعِبَادِهِۦ","dari hamba-hamba-Nya"],["خَبِيرٌۢ","(adalah) Maha Mengetahui"],["بَصِيرٌۭ","Maha Melihat"]]],"4300":["(Dan Dialah Yang menurunkan hujan) yakni air hujan (sesudah mereka berputus asa) putus harapan dari turunnya hujan (dan menyebarkan rahmat-Nya) maksudnya, menyebarkan hujan yang diturunkan-Nya. (Dan Dialah Yang Maha Pelindung) yang berbuat baik kepada orang-orang Mukmin (lagi Maha Terpuji) di kalangan orang-orang beriman.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["يُنَزِّلُ","menghantar turun"],["ٱلْغَيْثَ","hujan"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["مَا","[apa]"],["قَنَطُوا۟","mereka telah putus asa"],["وَيَنشُرُ","dan merebak"],["رَحْمَتَهُۥ ۚ","rahmatNya"],["وَهُوَ","Dan Dia"],["ٱلْوَلِىُّ","(ialah) Pelindung"],["ٱلْحَمِيدُ","yang Terpuji"]]],"4301":["(Dan di antara tanda-tanda kekuasaan-Nya ialah menciptakan langit dan bumi dan) menciptakan (apa yang Dia sebarkan) Dia sebar ratakan (pada keduanya, yaitu berupa makhluk yang melata) pengertian Ad-Dabbah ialah makhluk yang menempati bumi, yaitu manusia dan lain-lainnya. (Dan Dia untuk mengumpulkan semuanya) mengumpulkan semua makhluk untuk dihadapkan kepada-Nya (Maha Kuasa jika dikehendaki-Nya) Dhamir Hum yang terdapat pada lafal Jam'ihim lebih memprioritaskan makhluk yang berakal daripada makhluk lainnya.",[["وَمِنْ","Dan antara"],["ءَايَـٰتِهِۦ","Tanda-tandaNya"],["خَلْقُ","(ialah) penciptaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَمَا","dan apa sahaja"],["بَثَّ","Dia telah bersurai"],["فِيهِمَا","dalam kedua-duanya"],["مِن","daripada"],["دَآبَّةٍۢ ۚ","(the) makhluk"],["وَهُوَ","Dan Dia"],["عَلَىٰ","(sudah) tamat"],["جَمْعِهِمْ","perhimpunan mereka"],["إِذَا","apabila"],["يَشَآءُ","Dia kehendaki"],["قَدِيرٌۭ","Maha Berkuasa"]]],"4302":["(Dan apa saja yang telah menimpa kalian) khithab ayat ini ditujukan kepada orang-orang mukmin (berupa musibah) berupa malapetaka dan kesengsaraan (maka adalah karena perbuatan tangan kalian sendiri) artinya, sebab dosa-dosa yang telah kalian lakukan sendiri. Diungkapkan bahwa dosa-dosa tersebut dikerjakan oleh tangan mereka, hal ini mengingat, bahwa kebanyakan pekerjaan manusia itu dilakukan oleh tangan (dan Allah memaafkan sebagian besar) dari dosa-dosa tersebut, karena itu Dia tidak membalasnya. Dia Maha Mulia dari menduakalikan pembalasan-Nya di akhirat. Adapun mengenai musibah yang menimpa kepada orang-orang yang tidak berdosa di dunia, dimaksudkan untuk mengangkat derajatnya di akhirat kelak.",[["وَمَآ","Dan apa sahaja"],["أَصَـٰبَكُم","menimpa kamu"],["مِّن","daripada"],["مُّصِيبَةٍۢ","(the) kemalangan"],["فَبِمَا","(adalah kerana) apa"],["كَسَبَتْ","telah memperolehi"],["أَيْدِيكُمْ","tangan kamu"],["وَيَعْفُوا۟","Tetapi Dia mengampuni"],["عَن","[dari]"],["كَثِيرٍۢ","banyak"]]],"4303":["(Dan kalian tidak dapat) hai orang-orang musyrik (melepaskan diri) melarikan diri dari azab Allah (di muka bumi) maksudnya, kalian tidak akan dapat meloloskan diri dan menghindar dari azab-Nya itu (dan kalian tidak memperoleh selain Allah) (seorang pelindung pun dan tidak pula seorang penolong) yang dapat menolak azab Allah dari kalian.",[["وَمَآ","Dan tidak"],["أَنتُم","kamu"],["بِمُعْجِزِينَ","(boleh) melarikan diri"],["فِى","dalam"],["ٱلْأَرْضِ ۖ","bumi"],["وَمَا","dan bukan"],["لَكُم","bagi kamu"],["مِّن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["مِن","sebarang"],["وَلِىٍّۢ","pelindung"],["وَلَا","dan bukan"],["نَصِيرٍۢ","mana-mana pembantu"]]],"4304":["(Dan di antara tanda-tanda kekuasaan-Nya ialah kapal-kapal) atau perahu-perahu yang dapat berlayar (di laut seperti gunung-gunung) artinya, mirip seperti bukit-bukit dalam besarnya.",[["وَمِنْ","Dan antara"],["ءَايَـٰتِهِ","Tanda-tandaNya"],["ٱلْجَوَارِ","(adalah) kapal-kapal itu"],["فِى","dalam"],["ٱلْبَحْرِ","laut"],["كَٱلْأَعْلَـٰمِ","seperti gunung"]]],"4305":["(Jika Dia menghendaki Dia akan menenangkan angin, maka jadilah kapal-kapal itu) sehingga jadilah kapal-kapal itu (terhenti) diam tidak dapat melaju (di permukaan laut. Sesungguhnya pada yang demikian itu terdapat tanda-tanda kekuasaan-Nya bagi setiap orang yang banyak bersabar dan banyak bersyukur) yang dimaksud adalah orang mukmin, dia dapat bersabar di kala tertimpa musibah dan bersyukur di kala hidup senang.",[["إِن","Jika"],["يَشَأْ","Dia kehendaki"],["يُسْكِنِ","Dia boleh menyebabkan angin menjadi tenang"],["ٱلرِّيحَ","Dia boleh menyebabkan angin menjadi tenang"],["فَيَظْلَلْنَ","maka mereka akan kekal"],["رَوَاكِدَ","tidak bergerak"],["عَلَىٰ","pada"],["ظَهْرِهِۦٓ ۚ","belakangnya"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّكُلِّ","untuk semua orang"],["صَبَّارٍۢ","sabar"],["شَكُورٍ","(dan) bersyukur"]]],"4306":["(Atau kapal-kapal itu dibinasakan-Nya) lafal ayat ini di'athafkan kepada Yuskin artinya, atau Dia menenggelamkan kapal-kapal itu berikut para penumpang dan apa yang dimuatnya, yaitu dengan menimbulkan angin badai (karena perbuatan mereka) disebabkan dosa-dosa yang dilakukan oleh para penumpangnya (atau Dia memberi maaf sebagian besar) dari dosa-dosa itu, yang karenanya Dia tidak menenggelamkan para pelakunya.",[["أَوْ","Atau"],["يُوبِقْهُنَّ","Dia boleh memusnahkan mereka"],["بِمَا","bagi apa"],["كَسَبُوا۟","mereka telah perolehi"],["وَيَعْفُ","tetapi Dia mengampuni"],["عَن","[dari]"],["كَثِيرٍۢ","banyak"]]],"4307":["(Dan supaya mengetahui) lafal ayat ini kalau dibaca Rafa' berarti merupakan jumlah Isti'naf atau kalimat baru, kalau dibaca Nashab berarti di'athafkan kepada Ta'lil yang diperkirakan keberadaannya, yaitu; Dia menenggelamkan mereka sebagai pembalasan dari-Nya kepada mereka, dan supaya mengetahui (orang-orang yang membantah ayat-ayat Kami, bahwa mereka sekali-kali tidak akan memperoleh jalan keluar) maksudnya, tempat untuk melarikan diri dari azab Kami. Jumlah Nafi atau lafal Ma Lahum Min Mahiish menduduki tempat dua Maf'ul bagi lafal Ya'lama. Sedangkan Nafinya sendiri di-mu'allaqkan dari amalnya.",[["وَيَعْلَمَ","Dan mungkin tahu"],["ٱلَّذِينَ","orang yang"],["يُجَـٰدِلُونَ","pertikaian"],["فِىٓ","tentang"],["ءَايَـٰتِنَا","Tanda-Tanda Kami"],["مَا","(itu) tidak"],["لَهُم","bagi mereka"],["مِّن","sebarang"],["مَّحِيصٍۢ","tempat berlindung"]]],"4308":["(Maka apa yang diberikan kepada kalian) khithab ayat ini ditujukan kepada orang-orang mukmin dan lain-lainnya (berupa sesuatu) dari perhiasan duniawi (itu adalah kenikmatan hidup di dunia) untuk dinikmati kemudian lenyap sesudah itu (dan yang ada pada sisi Allah) berupa pahala (lebih baik dan lebih kekal bagi orang-orang yang beriman dan hanya kepada Rabb mereka, mereka bertawakal) kemudian di'athafkan kepadanya ayat berikut ini, yaitu:",[["فَمَآ","Jadi apapun"],["أُوتِيتُم","kamu diberi"],["مِّن","daripada"],["شَىْءٍۢ","sesuatu perkara"],["فَمَتَـٰعُ","(adalah) tetapi kenikmatan yang berlalu"],["ٱلْحَيَوٰةِ","(untuk) kehidupan"],["ٱلدُّنْيَا ۖ","dunia"],["وَمَا","Tetapi apa"],["عِندَ","(adalah) dengan"],["ٱللَّهِ","Allah"],["خَيْرٌۭ","(lebih) baik"],["وَأَبْقَىٰ","dan lebih tahan lama"],["لِلَّذِينَ","bagi mereka yang"],["ءَامَنُوا۟","beriman"],["وَعَلَىٰ","dan seterusnya"],["رَبِّهِمْ","Tuhan mereka"],["يَتَوَكَّلُونَ","meletakkan kepercayaan (mereka)."]]],"4309":["(Dan bagi orang-orang yang menjauhi dosa-dosa besar dan perbuatan-perbuatan keji) yang mengharuskan pelakunya menjalani hukuman Hadd; lafal ayat ini merupakan 'Athful Ba'dh 'Alal Kull (dan apabila mereka marah mereka memberi maaf) maksudnya, mereka selalu bersikap maaf.",[["وَٱلَّذِينَ","Dan orang yang"],["يَجْتَنِبُونَ","elakkan"],["كَبَـٰٓئِرَ","(yang) lebih besar"],["ٱلْإِثْمِ","dosa"],["وَٱلْفَوَٰحِشَ","dan maksiat"],["وَإِذَا","dan apabila"],["مَا","dan apabila"],["غَضِبُوا۟","mereka marah"],["هُمْ","mereka"],["يَغْفِرُونَ","maafkan"]]],"4310":["(Dan bagi orang-orang yang menerima seruan Rabbnya) yang mematuhi apa yang diserukan Rabbnya yaitu, mentauhidkan-Nya dan menyembah-Nya (dan mendirikan salat) memeliharanya (sedangkan urusan mereka) yang berkenaan dengan diri mereka (mereka putuskan di antara mereka dengan musyawarah) memutuskannya secara musyawarah dan tidak tergesa-gesa dalam memutuskannya (dan sebagian dari apa yang Kami rezekikan kepada mereka) atau sebagian dari apa yang Kami berikan kepada mereka (mereka menafkahkannya) untuk jalan ketaatan kepada Allah. Dan orang-orang yang telah disebutkan tadi merupakan suatu golongan kemudian golongan yang lainnya ialah;",[["وَٱلَّذِينَ","Dan orang yang"],["ٱسْتَجَابُوا۟","bertindak balas"],["لِرَبِّهِمْ","kepada Tuhan mereka"],["وَأَقَامُوا۟","dan mendirikan"],["ٱلصَّلَوٰةَ","solat"],["وَأَمْرُهُمْ","dan urusan mereka"],["شُورَىٰ","(dikendalikan oleh) perundingan"],["بَيْنَهُمْ","antara mereka"],["وَمِمَّا","dan dari apa"],["رَزَقْنَـٰهُمْ","Kami rezekikan kepada mereka"],["يُنفِقُونَ","mereka nafkahkan"]]],"4311":["(Dan bagi orang-orang yang apabila mereka diperlakukan dengan lalim) dizalimi (mereka membela diri) maksudnya membalas perlakuan zalim itu sesuai dengan kelaliman yang diterimanya, sebagaimana yang diungkapkan oleh firman-Nya:",[["وَٱلَّذِينَ","Dan orang yang"],["إِذَآ","apabila"],["أَصَابَهُمُ","menyerang mereka"],["ٱلْبَغْىُ","kezaliman"],["هُمْ","mereka"],["يَنتَصِرُونَ","mempertahankan diri"]]],"4312":["(Dan balasan suatu kejahatan adalah kejahatan yang serupa) kejahatan yang kedua ini dinamakan pula sebagai kejahatan bukan pembalasan, karena jenis dan gambarannya sama dengan yang pertama. Hal ini tampak jelas di dalam masalah yang menyangkut kisas luka. Sebagian di antara para ahli fikih mengatakan, bahwa jika ada seseorang mengatakan kepadamu, \"Semoga Allah menghinakan kamu,\" maka pembalasan yang setimpal ialah harus dikatakan pula kepadanya, \"Semoga Allah menghinakan kamu pula (maka barang siapa memaafkan) orang yang berbuat lalim kepadanya (dan berbuat baik) yakni tetap berlaku baik kepada orang yang telah ia maafkan (maka pahalanya atas tanggungan Allah) artinya, Allah pasti akan membalas pahalanya. (Sesungguhnya Dia tidak menyukai orang-orang yang lalim) maksudnya Dia tidak menyukai orang-orang yang memulai berbuat lalim, maka barang siapa yang memulai berbuat lalim dia akan menanggung akibatnya, yaitu siksaan dari-Nya.",[["وَجَزَٰٓؤُا۟","(The) balasan"],["سَيِّئَةٍۢ","(dari) kejahatan"],["سَيِّئَةٌۭ","(adalah) kejahatan"],["مِّثْلُهَا ۖ","suka"],["فَمَنْ","Tetapi siapa pun"],["عَفَا","pengampunan"],["وَأَصْلَحَ","dan membuat perdamaian"],["فَأَجْرُهُۥ","maka pahalanya"],["عَلَى","(berada) di atas"],["ٱللَّهِ ۚ","Allah"],["إِنَّهُۥ","Sesungguhnya Dia"],["لَا","tidak"],["يُحِبُّ","suka"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"4313":["(Dan sesungguhnya orang-orang yang membela diri sesudah teraniaya) sesudah ia menerima penganiayaan dari orang lain (tidak ada suatu dosa pun atas mereka) maksudnya, mereka tidak berdosa bila menuntut.",[["وَلَمَنِ","Dan pastinya sesiapa sahaja"],["ٱنتَصَرَ","mempertahankan dirinya"],["بَعْدَ","selepas"],["ظُلْمِهِۦ","dia telah dizalimi"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["مَا","tidak"],["عَلَيْهِم","(adalah) menentang mereka"],["مِّن","sebarang"],["سَبِيلٍ","cara"]]],"4314":["(Sesungguhnya dosa itu atas orang-orang yang berbuat lalim kepada manusia dan melampaui batas) yaitu mereka mengerjakan hal-hal (di muka bumi tanpa hak) mereka mengerjakan perbuatan-perbuatan maksiat. (Mereka itu mendapat azab yang pedih) yaitu azab yang menyakitkan.",[["إِنَّمَا","Hanya"],["ٱلسَّبِيلُ","caranya"],["عَلَى","terhadap"],["ٱلَّذِينَ","orang yang"],["يَظْلِمُونَ","menindas"],["ٱلنَّاسَ","manusia"],["وَيَبْغُونَ","dan memberontak"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["بِغَيْرِ","tanpa"],["ٱلْحَقِّ ۚ","betul"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["لَهُمْ","bagi mereka"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"]]],"4315":["(Tetapi orang yang bersabar) dan ia tidak membela dirinya atau tidak menuntut balas (dan memaafkan) memaafkan kelaliman orang lain terhadap dirinya (sesungguhnya yang demikian itu) yaitu sabar dan pemaaf (termasuk hal-hal yang diutamakan) yang dianjurkan oleh syariat.",[["وَلَمَن","Dan sesiapa"],["صَبَرَ","(adalah) sabar"],["وَغَفَرَ","dan memaafkan"],["إِنَّ","sesungguhnya"],["ذَٰلِكَ","bahawa"],["لَمِنْ","(adalah) pasti daripada"],["عَزْمِ","perkara penentuan"],["ٱلْأُمُورِ","perkara penentuan"]]],"4316":["(Dan siapa yang disesatkan Allah maka tidak ada baginya seorang pemimpin pun sesudah itu) artinya tiada seorang pun yang dapat memberikan petunjuk kepadanya sesudah ia disesatkan oleh Allah (Dan kamu akan melihat orang-orang yang lalim ketika mereka melihat azab berkata, \"Adakah kiranya jalan untuk kembali) ke dunia bagi kami.\"",[["وَمَن","Dan sesiapa"],["يُضْلِلِ","Allah biarkan sesat"],["ٱللَّهُ","Allah biarkan sesat"],["فَمَا","maka tidak"],["لَهُۥ","baginya"],["مِن","sebarang"],["وَلِىٍّۢ","pelindung"],["مِّنۢ","selepas Dia"],["بَعْدِهِۦ ۗ","selepas Dia"],["وَتَرَى","Dan kamu akan melihat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["لَمَّا","apabila"],["رَأَوُا۟","mereka lihat"],["ٱلْعَذَابَ","azab"],["يَقُولُونَ","berkata"],["هَلْ","Adakah"],["إِلَىٰ","(di sana) untuk"],["مَرَدٍّۢ","kembali"],["مِّن","sebarang"],["سَبِيلٍۢ","cara"]]],"4317":["(Dan kamu akan melihat mereka dihadapkan kepadanya) yakni ke neraka (dalam keadaan tunduk) takut dan merasa rendah diri (karena merasa hina, mereka melihat) ke neraka (dengan pandangan yang lesu) atau dengan pandangan yang malas. Huruf Min di sini bermakna Ibtidaiyah atau bermakna sama dengan huruf Ba. (Dan orang-orang yang beriman berkata, \"Sesungguhnya orang-orang yang merugi ialah orang-orang yang kehilangan diri mereka sendiri dan kehilangan keluarga mereka pada hari kiamat\") karena mereka kekal menjadi penghuni neraka dan tidak memperoleh bidadari-bidadari yang telah disediakan buat mereka seandainya mereka beriman. Isim Maushul atau lafal Al Ladziina Khasiruu Anfusahum merupakan Khabar dari lafal Inna. (Ingatlah, sesungguhnya orang-orang yang zalim itu) yakni orang-orang yang kafir itu (berada dalam azab yang kekal) azab yang abadi; ini adalah firman Allah swt.",[["وَتَرَىٰهُمْ","Dan kamu akan melihat mereka"],["يُعْرَضُونَ","sedang terdedah"],["عَلَيْهَا","kepadanya"],["خَـٰشِعِينَ","merendah diri"],["مِنَ","oleh"],["ٱلذُّلِّ","aib"],["يَنظُرُونَ","mencari"],["مِن","dengan"],["طَرْفٍ","sepintas lalu"],["خَفِىٍّۢ ۗ","senyap-senyap"],["وَقَالَ","Dan akan berkata"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوٓا۟","beriman"],["إِنَّ","Sesungguhnya"],["ٱلْخَـٰسِرِينَ","yang rugi"],["ٱلَّذِينَ","(adalah) mereka yang"],["خَسِرُوٓا۟","hilang"],["أَنفُسَهُمْ","diri mereka"],["وَأَهْلِيهِمْ","dan keluarga mereka"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ ۗ","Kiamat"],["أَلَآ","Tidak dinafikan"],["إِنَّ","Sesungguhnya"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["فِى","(ada) dalam"],["عَذَابٍۢ","azab"],["مُّقِيمٍۢ","berkekalan"]]],"4318":["(Dan mereka sekali-kali tidak mempunyai pelindung-pelindung yang dapat menolong mereka selain Allah) yang dapat menolak azab-Nya dari diri mereka (Dan siapa yang disesatkan Allah maka tidaklah ada baginya sesuatu jalan pun) yaitu jalan yang benar baginya di dunia dan jalan yang dapat mengantarkannya ke surga, di akhirat kelak.",[["وَمَا","Dan tidak"],["كَانَ","akan menjadi"],["لَهُم","bagi mereka"],["مِّنْ","sebarang"],["أَوْلِيَآءَ","pelindung"],["يَنصُرُونَهُم","(yang) akan menolong mereka"],["مِّن","selain"],["دُونِ","selain"],["ٱللَّهِ ۗ","Allah"],["وَمَن","Dan siapa"],["يُضْلِلِ","Allah biarkan sesat"],["ٱللَّهُ","Allah biarkan sesat"],["فَمَا","maka tidak"],["لَهُۥ","baginya"],["مِن","sebarang"],["سَبِيلٍ","cara"]]],"4319":["(Patuhilah seruan Rabb kalian) perkenankanlah seruan-Nya, yaitu dengan mentauhidkan-Nya dan menyembah-Nya (sebelum datang suatu hari) yakni hari kiamat (dari Allah yang tidak dapat ditolak kedatangannya) apabila hari itu datang tidak dapat ditolak. (Kalian tidak memperoleh tempat berlindung) yang kalian dapat berlindung di dalamnya (pada hari itu dan tidak pula dapat mengingkari) dosa-dosa kalian.",[["ٱسْتَجِيبُوا۟","Balas"],["لِرَبِّكُم","kepada Tuhanmu"],["مِّن","sebelum"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["يَأْتِىَ","datang"],["يَوْمٌۭ","sehari"],["لَّا","(ada) tidak"],["مَرَدَّ","mengelak"],["لَهُۥ","baginya"],["مِنَ","daripada"],["ٱللَّهِ ۚ","Allah"],["مَا","Tidak"],["لَكُم","(adalah) untuk kamu"],["مِّن","sebarang"],["مَّلْجَإٍۢ","tempat perlindungan"],["يَوْمَئِذٍۢ","(pada) hari itu"],["وَمَا","dan bukan"],["لَكُم","bagi kamu"],["مِّن","sebarang"],["نَّكِيرٍۢ","penafian"]]],"4320":["(Jika mereka berpaling) tidak mau mematuhi seruan-Nya itu (maka Kami tidak mengutus kamu sebagai pemelihara bagi mereka) sebagai orang yang memelihara amal perbuatan mereka, umpamanya kamu menjadi orang yang memperturutkan apa yang dikehendaki oleh mereka. (Tidak lain) tiada lain (kewajibanmu hanyalah menyampaikan risalah) hal ini sebelum ada perintah untuk berjihad. (Sesungguhnya apabila Kami merasakan kepada manusia sesuatu rahmat dari Kami) berupa nikmat seperti kekayaan atau kecukupan dan kesehatan (dia bergembira ria karena rahmat itu. Dan jika mereka ditimpa) Dhamir yang kembali kepada lafal Al-Insaan memandang kepada segi maknanya atau jenisnya (kesusahan) malapetaka atau musibah (disebabkan perbuatan tangan mereka sendiri) disebabkan yang mereka lakukan; dalam ayat ini diungkapkan kata 'tangan mereka sendiri' karena kebanyakan pekerjaan manusia itu dilakukan oleh tangannya (karena sesungguhnya manusia itu amat ingkar) kepada nikmat yang telah diberikan kepadanya.",[["فَإِنْ","Kemudian jika"],["أَعْرَضُوا۟","mereka berpaling"],["فَمَآ","maka tidak"],["أَرْسَلْنَـٰكَ","Kami telah menghantar kamu"],["عَلَيْهِمْ","atas mereka"],["حَفِيظًا ۖ","(sebagai) penjaga"],["إِنْ","Tidak"],["عَلَيْكَ","(ada) pada kamu"],["إِلَّا","kecuali"],["ٱلْبَلَـٰغُ ۗ","pengangkutan itu"],["وَإِنَّآ","Dan sesungguhnya"],["إِذَآ","apabila"],["أَذَقْنَا","Kami menyebabkan rasa"],["ٱلْإِنسَـٰنَ","lelaki itu"],["مِنَّا","daripada Kami"],["رَحْمَةًۭ","belas kasihan"],["فَرِحَ","dia bergembira"],["بِهَا ۖ","di dalamnya"],["وَإِن","Tetapi jika"],["تُصِبْهُمْ","menimpa mereka"],["سَيِّئَةٌۢ","jahat"],["بِمَا","bagi apa"],["قَدَّمَتْ","telah menghantar"],["أَيْدِيهِمْ","tangan mereka"],["فَإِنَّ","maka sesungguhnya"],["ٱلْإِنسَـٰنَ","lelaki itu"],["كَفُورٌۭ","(adalah) tidak bersyukur"]]],"4321":["(Kepunyaan Allahlah kerajaan langit dan bumi. Dia menciptakan apa yang Dia kehendaki. Dia memberikan kepada siapa yang Dia kehendaki) yakni berupa anak-anak (yaitu anak-anak perempuan dan Dia memberikan anak-anak lelaki kepada siapa yang Dia kehendaki.)",[["لِّلَّهِ","Kepada Allah"],["مُلْكُ","(kepunyaan) kekuasaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["يَخْلُقُ","Dia mencipta"],["مَا","apa"],["يَشَآءُ ۚ","Dia kehendaki"],["يَهَبُ","Dia memberi"],["لِمَن","kepada siapa"],["يَشَآءُ","Dia kehendaki"],["إِنَـٰثًۭا","perempuan"],["وَيَهَبُ","dan Dia mengabulkan"],["لِمَن","kepada siapa"],["يَشَآءُ","Dia kehendaki"],["ٱلذُّكُورَ","[the] lelaki"]]],"4322":["(Atau Dia menganugerahkan kedua jenis) atau Dia menjadikan buat mereka (laki-laki dan perempuan, dan Dia menjadikan mandul siapa yang Dia kehendaki) sehingga tidak mempunyai anak dan tidak dapat membuahi. (Sesungguhnya Dia Maha Mengetahui) apa yang diciptakan-Nya (lagi Maha Kuasa) atas semua apa yang dikehendaki-Nya.",[["أَوْ","Atau"],["يُزَوِّجُهُمْ","Dia menganugerahkan mereka"],["ذُكْرَانًۭا","jantan"],["وَإِنَـٰثًۭا ۖ","dan perempuan"],["وَيَجْعَلُ","dan Dia menjadikan"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["عَقِيمًا ۚ","mandul"],["إِنَّهُۥ","Sesungguhnya Dia"],["عَلِيمٌۭ","Maha Mengetahui"],["قَدِيرٌۭ","Maha Berkuasa"]]],"4323":["(Dan tidak mungkin bagi seorang manusia pun bahwa Allah berkata-kata dengan dia kecuali) dengan perantaraan (wahyu) yang Dia wahyukan kepadanya di dalam tidurnya atau melalui ilham (atau) melainkan (di belakang tabir) seumpamanya Allah memperdengarkan kalam-Nya kepadanya, tetapi dia tidak dapat melihat-Nya, sebagaimana yang telah terjadi pada Nabi Musa a.s. (atau) kecuali (dengan mengutus seorang utusan) yakni malaikat, seperti Jibril (lalu diwahyukan kepadanya) maksudnya, utusan itu menyampaikan wahyu-Nya kepada rasul yang dituju (dengan seizin-Nya) dengan seizin Allah (apa yang Dia kehendaki) apa yang Allah kehendaki. (Sesungguhnya Dia Maha Tinggi) dari sifat-sifat yang dimiliki oleh semua makhluk (lagi Maha Bijaksana) di dalam perbuatan-Nya.",[["۞ وَمَا","Dan tidak"],["كَانَ","ialah"],["لِبَشَرٍ","untuk mana-mana manusia"],["أَن","bahawa"],["يُكَلِّمَهُ","Allah hendaklah bercakap dengannya"],["ٱللَّهُ","Allah hendaklah bercakap dengannya"],["إِلَّا","kecuali"],["وَحْيًا","(oleh) wahyu"],["أَوْ","atau"],["مِن","daripada"],["وَرَآئِ","belakang"],["حِجَابٍ","sebuah tudung"],["أَوْ","atau"],["يُرْسِلَ","(dengan) menghantar"],["رَسُولًۭا","seorang utusan"],["فَيُوحِىَ","kemudian dia mendedahkan"],["بِإِذْنِهِۦ","dengan izinNya"],["مَا","apa"],["يَشَآءُ ۚ","Dia kehendaki"],["إِنَّهُۥ","Sesungguhnya Dia"],["عَلِىٌّ","(adalah) Yang Maha Tinggi"],["حَكِيمٌۭ","Maha Bijaksana"]]],"4324":["(Dan demikianlah) maksudnya, sebagaimana Kami wahyukan kepada rasul-rasul selain kamu (Kami wahyukan kepadamu) hai Muhammad (wahyu) yakni Alquran, yang karenanya kalbu manusia dapat hidup (dengan perintah Kami) yang Kami wahyukan kepadamu. (Sebelumnya kamu tidaklah mengetahui) sebelum Kami mewahyukan kepadamu (apakah Alkitab) yakni Alquran itu (dan tidak pula mengetahui apakah iman itu) yakni syariat-syariat dan tanda-tanda-Nya Nafi dalam ayat ini amalnya di-ta'alluqkan kepada Fi'il dan lafal-lafal sesudah Fi'il menempati kedudukan dua Maf'ulnya (tetapi Kami menjadikan Alquran itu) wahyu atau Alquran itu (cahaya, yang Kami tunjuki dengan dia siapa yang Kami kehendaki di antara hamba-hamba Kami. Dan sesungguhnya kamu benar-benar memberi petunjuk) maksudnya kamu menyeru dengan wahyu yang diturunkan kepadamu (kepada jalan) tuntunan (yang lurus) yakni agama Islam.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["أَوْحَيْنَآ","Kami telah mendedahkan"],["إِلَيْكَ","kepada kamu"],["رُوحًۭا","sebuah inspirasi"],["مِّنْ","oleh"],["أَمْرِنَا ۚ","Perintah Kami"],["مَا","Tidak"],["كُنتَ","(adakah) kamu"],["تَدْرِى","mengetahui"],["مَا","apa"],["ٱلْكِتَـٰبُ","Buku (adalah)"],["وَلَا","dan bukan"],["ٱلْإِيمَـٰنُ","iman"],["وَلَـٰكِن","Tetapi"],["جَعَلْنَـٰهُ","Kami telah berjaya"],["نُورًۭا","sebuah cahaya"],["نَّهْدِى","Kami bimbing"],["بِهِۦ","dengannya"],["مَن","yang"],["نَّشَآءُ","Kami akan"],["مِنْ","daripada"],["عِبَادِنَا ۚ","hamba kita"],["وَإِنَّكَ","Dan sesungguhnya, kamu"],["لَتَهْدِىٓ","pasti memberi petunjuk"],["إِلَىٰ","kepada"],["صِرَٰطٍۢ","(the) Jalan"],["مُّسْتَقِيمٍۢ","Lurus"]]],"4325":["(Yaitu jalan Allah yang kepunyaan-Nya segala apa yang ada di langit dan apa yang ada di bumi) sebagai milik-Nya, makhluk-Nya dan hamba-hamba-Nya. (Ingatlah, bahwa kepada Allahlah kembali semua urusan) semua urusan dikembalikan.",[["صِرَٰطِ","jalan"],["ٱللَّهِ","(milik) Allah"],["ٱلَّذِى","yang Satu"],["لَهُۥ","kepada Siapa"],["مَا","(kepunyaan) apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۗ","bumi"],["أَلَآ","Tidak dinafikan"],["إِلَى","Kepada"],["ٱللَّهِ","Allah"],["تَصِيرُ","capai"],["ٱلْأُمُورُ","semua urusan"]]],"4326":["(Ha Mim) hanya Allah sajalah yang mengetahui arti dan maksudnya.",[["حمٓ","Ha Mim"]]],"4327":["(Demi Alkitab) demi Alquran (yang menerangkan) yang menonjolkan jalan petunjuk beserta dengan sarana yang diperlukannya yaitu berupa syariat.",[["وَٱلْكِتَـٰبِ","Oleh Kitab"],["ٱلْمُبِينِ","yang jelas"]]],"4328":["(Sesungguhnya Kami menjadikan Alquran) maksudnya, Kami adakan Alkitab ini (bacaan yang berbahasa Arab) atau memakai bahasa Arab (supaya kalian) hai penduduk Mekah (memahaminya) memahami makna-maknanya.",[["إِنَّا","Sesungguhnya Kami"],["جَعَلْنَـٰهُ","(telah) berjaya"],["قُرْءَٰنًا","sebuah Al-Quran"],["عَرَبِيًّۭا","(dalam) bahasa Arab"],["لَّعَلَّكُمْ","supaya kamu"],["تَعْقِلُونَ","faham"]]],"4329":["(Dan sesungguhnya Alquran itu) telah ditetapkan (dalam induk Alkitab) asal Kitab, yaitu Lohmahfuz (di sisi Kami) lafal ayat ini menjadi Badal dari lafal 'Indana (adalah benar-benar tinggi) yang jauh lebih tinggi daripada Kitab-kitab sebelumnya (dan amat banyak mengandung hikmah) artinya sangat padat dengan hikmah-hikmah.",[["وَإِنَّهُۥ","Dan sesungguhnya, ia"],["فِىٓ","(berada) dalam"],["أُمِّ","(the) Ibu"],["ٱلْكِتَـٰبِ","Kitab"],["لَدَيْنَا","dengan Kami"],["لَعَلِىٌّ","pasti ditinggikan"],["حَكِيمٌ","penuh hikmah"]]],"4330":["(Maka apakah Kami akan berhenti) akan menahan (menurunkan Adz-Dzikr kepada kalian) yakni Alquran (dengan sebenar-benarnya) maksudnya Kami benar-benar menahan Alquran dan tidak menurunkannya kepada kalian, karena itu kalian tidak lagi terkena amar makruf dan nahi mungkar, demikian itu hanya (karena kalian adalah kaum yang melampaui batas?) kaum yang musyrik tentu tidak.",[["أَفَنَضْرِبُ","Maka hendaklah Kami hapuskan"],["عَنكُمُ","daripada kamu"],["ٱلذِّكْرَ","Peringatan itu"],["صَفْحًا","tidak menghiraukan (kamu)"],["أَن","kerana"],["كُنتُمْ","kamu"],["قَوْمًۭا","suatu kaum"],["مُّسْرِفِينَ","melanggar"]]],"4331":["(Berapa banyak nabi-nabi yang telah Kami utus kepada umat-umat yang terdahulu.)",[["وَكَمْ","Dan berapa banyak"],["أَرْسَلْنَا","Kami utus"],["مِن","daripada"],["نَّبِىٍّۢ","seorang Nabi"],["فِى","antara"],["ٱلْأَوَّلِينَ","bekas (orang)"]]],"4332":["(Dan tiada) (yang datang kepada mereka) atau tiba kepada mereka (seorang nabi pun melainkan mereka selalu memperolok-olokkannya) sebagaimana kaummu memperolok-olokkan kamu, ayat ini merupakan penghibur bagi Nabi saw.",[["وَمَا","Dan tidak"],["يَأْتِيهِم","datang kepada mereka"],["مِّن","mana-mana Nabi"],["نَّبِىٍّ","mana-mana Nabi"],["إِلَّا","tetapi"],["كَانُوا۟","mereka dahulu"],["بِهِۦ","mengejek dia"],["يَسْتَهْزِءُونَ","mengejek dia"]]],"4333":["(Maka telah Kami binasakan orang-orang yang lebih hebat daripada mereka) daripada kaummu (kekuatannya) maksudnya daya dan kekuatan mereka lebih kuat daripada kaummu (dan telah terdahulu) telah disebutkan di dalam ayat-ayat yang lain (perumpamaan umat-umat yang terdahulu) yaitu mengenai dibinasakannya mereka, maka akibat yang akan dialami oleh kaummu sama saja.",[["فَأَهْلَكْنَآ","Kemudian Kami binasakan"],["أَشَدَّ","lebih kuat"],["مِنْهُم","daripada mereka"],["بَطْشًۭا","(dalam) kuasa"],["وَمَضَىٰ","dan telah berlalu"],["مَثَلُ","(the) contoh"],["ٱلْأَوَّلِينَ","(dari) orang-orang dahulu"]]],"4334":["(Dan sungguh jika) huruf Lam di sini bermakna Qasam (kamu tanyakan kepada mereka, \"Siapakah yang menciptakan langit dan bumi?\" Niscaya mereka akan menjawab,) dari lafal Layaquulunna terbuang Nun alamat Rafa'nya, karena jika masih ada, maka akan terjadilah huruf Nun yang berturut-turut, dan hal ini dinilai jelek oleh orang-orang Arab. Sebagaimana dibuang pula daripadanya Wawu Dhamir jamak, tetapi 'Illatnya bukan karena bertemunya dua huruf yang disukunkan (\"Semuanya diciptakan oleh Yang Maha Perkasa lagi Maha Mengetahui\") jawaban terakhir mereka adalah, \"Allah Yang Maha Perkasa dan Maha Mengetahuilah yang menciptakan kesemuanya itu.\" Selanjutnya Allah swt. menambahkan:",[["وَلَئِن","Dan jika"],["سَأَلْتَهُم","kamu bertanya kepada mereka"],["مَّنْ","Siapa"],["خَلَقَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["لَيَقُولُنَّ","Mereka pasti akan berkata"],["خَلَقَهُنَّ","Mencipta mereka"],["ٱلْعَزِيزُ","Yang Maha Perkasa"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"4335":["(Yang menjadikan bumi untuk kalian sebagai tempat menetap) sebagai hamparan yang mirip dengan ayunan bayi (dan Dia membuat jalan-jalan di atas bumi untuk kalian) dilalui (supaya kalian mendapat petunjuk) untuk mencapai tujuan-tujuan di dalam perjalanan kalian.",[["ٱلَّذِى","Dia yang"],["جَعَلَ","dibuat"],["لَكُمُ","bagi kamu"],["ٱلْأَرْضَ","bumi"],["مَهْدًۭا","sebuah katil"],["وَجَعَلَ","dan dibuat"],["لَكُمْ","bagi kamu"],["فِيهَا","di dalamnya"],["سُبُلًۭا","jalan raya"],["لَّعَلَّكُمْ","supaya kamu"],["تَهْتَدُونَ","(dibimbing)."]]],"4336":["(Dan Yang menurunkan air dari langit menurut kadar) yang diperlukan oleh kalian, dan Dia tidak menurunkannya dalam bentuk hujan yang sangat besar yang disertai dengan angin topan (lalu Kami hidupkan dengan air itu negeri yang mati, seperti itulah) sebagaimana cara menghidupkan itulah (kalian akan dikeluarkan) dari dalam kubur kalian lalu kalian menjadi hidup kembali.",[["وَٱلَّذِى","Dan Dia yang"],["نَزَّلَ","menghantar turun"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۢ","air"],["بِقَدَرٍۢ","dalam (sewajarnya) ukuran"],["فَأَنشَرْنَا","kemudian Kami hidupkan"],["بِهِۦ","dengannya"],["بَلْدَةًۭ","sebuah tanah"],["مَّيْتًۭا ۚ","mati"],["كَذَٰلِكَ","dengan demikian"],["تُخْرَجُونَ","kamu akan dilahirkan"]]],"4337":["(Dan Yang menciptakan makhluk yang berpasang-pasangan) berbagai jenis makhluk berpasang-pasangan (semuanya, dan menjadikan untuk kalian kapal) atau perahu-perahu (dan binatang ternak) misalnya unta (yang kalian tunggangi) di dalam lafal ayat ini dibuang daripadanya Dhamir yang kembali kepada lafal Ma demi untuk meringkas, Dhamir tersebut adalah lafal Fihi maksudnya, yang dapat kalian kendarai.",[["وَٱلَّذِى","Dan Dia yang"],["خَلَقَ","dicipta"],["ٱلْأَزْوَٰجَ","pasangan itu"],["كُلَّهَا","kesemuanya"],["وَجَعَلَ","dan dibuat"],["لَكُم","bagi kamu"],["مِّنَ","[daripada]"],["ٱلْفُلْكِ","kapal-kapal itu"],["وَٱلْأَنْعَـٰمِ","dan lembu"],["مَا","apa"],["تَرْكَبُونَ","kamu naik"]]],"4338":["(Supaya kalian dapat duduk) tetap (di atas punggungnya) Dhamir yang ada pada ayat ini dimudzakkarkan, dan lafal Zhahr dikemukakan dalam bentuk jamak sehingga menjadi Zhuhur; hal ini karena memandang makna yang terkandung di dalam lafal Ma (kemudian kalian ingat nikmat Rabb kalian apabila kalian telah duduk di atasnya dan supaya kalian mengatakan, \"Maha Suci Tuhan yang telah menundukkan semua ini bagi kami padahal kami sebelumnya tidak mampu menguasainya) tidak dapat menguasainya.",[["لِتَسْتَوُۥا۟","Supaya kamu boleh duduk dengan teguh"],["عَلَىٰ","pada"],["ظُهُورِهِۦ","belakang mereka"],["ثُمَّ","kemudian"],["تَذْكُرُوا۟","ingat"],["نِعْمَةَ","(yang) nikmat"],["رَبِّكُمْ","Tuhanmu"],["إِذَا","apabila"],["ٱسْتَوَيْتُمْ","kamu duduk dengan teguh"],["عَلَيْهِ","ke atas mereka"],["وَتَقُولُوا۟","dan katakan"],["سُبْحَـٰنَ","Maha Suci (kepada)"],["ٱلَّذِى","yang Esa"],["سَخَّرَ","(telah) tertakluk"],["لَنَا","kepada kami"],["هَـٰذَا","ini"],["وَمَا","dan bukan"],["كُنَّا","kami"],["لَهُۥ","daripadanya"],["مُقْرِنِينَ","berkemampuan"]]],"4339":["(Dan sesungguhnya kami akan kembali kepada Rabb kami\") kami akan dikembalikan kepada-Nya.",[["وَإِنَّآ","Dan sesungguhnya, kita"],["إِلَىٰ","kepada"],["رَبِّنَا","Tuhan kami"],["لَمُنقَلِبُونَ","pasti akan kembali"]]],"4340":["(Dan mereka menjadikan sebagian dari hamba-hamba-Nya sebagai bagian daripada-Nya) karena mereka telah mengatakan, bahwa malaikat-malaikat itu adalah anak-anak perempuan Allah. Dikatakan Juz'an atau bagian, karena anak itu adalah bagian dari orang tuanya; padahal hakikatnya malaikat-malaikat itu adalah hamba-hamba Allah swt. (Sesungguhnya manusia) yang telah mengatakan perkataan tadi (benar-benar pengingkar yang nyata) yang jelas dan nyata kekafirannya.",[["وَجَعَلُوا۟","Tetapi mereka sifatkan"],["لَهُۥ","kepada-Nya"],["مِنْ","daripada"],["عِبَادِهِۦ","hambanya"],["جُزْءًا ۚ","sebahagian"],["إِنَّ","Sesungguhnya"],["ٱلْإِنسَـٰنَ","lelaki"],["لَكَفُورٌۭ","sesungguhnya (adalah) nyata ingkar"],["مُّبِينٌ","sesungguhnya (adalah) nyata ingkar"]]],"4341":["(Patutkah) lafal Am di sini bermakna Istifham Inkari, sedangkan lafal Al Qaulu diperkirakan keberadaannya sesudah itu, yakni Ataquluna: Apakah kalian patut mengatakan (Dia mengambil anak perempuan dari yang diciptakan-Nya) untuk diri-Nya sendiri (dan Dia mengkhususkan buat kalian) memilihkan buat kalian (anak laki-laki) yang hal ini disimpulkan daripada perkataan kalian yang tadi itu; jumlah kalimat ini merupakan kalimat yang diinkari oleh Istifham tadi.",[["أَمِ","Atau"],["ٱتَّخَذَ","telah Dia ambil"],["مِمَّا","tentang apa"],["يَخْلُقُ","Dia telah mencipta"],["بَنَاتٍۢ","anak perempuan"],["وَأَصْفَىٰكُم","dan Dia telah memilih (untuk) kamu"],["بِٱلْبَنِينَ","anak lelaki"]]],"4342":["(Padahal apabila salah seorang di antara mereka diberi kabar gembira dengan apa yang dijadikan sebagai misal bagi Allah Yang Maha Pemurah) maksudnya, dijadikan baginya hal serupa dengan apa yang ia nisbatkan kepada Allah, yaitu diberi anak-anak perempuan. Atau dengan kata lain, apabila ia diberi berita gembira tentang kelahiran anak perempuannya (jadilah) maka menjadi berubahlah (mukanya hitam) artinya, roman mukanya tampak berubah menjadi kelabu (sedangkan dia amat menahan sedih) penuh dengan kedukaan, maka mengapa mereka berani menisbatkan anak-anak perempuan kepada Allah swt.?",[["وَإِذَا","Dan apabila"],["بُشِّرَ","diberi khabar gembira"],["أَحَدُهُم","(kepada) salah seorang daripada mereka"],["بِمَا","tentang apa"],["ضَرَبَ","dia sediakan"],["لِلرَّحْمَـٰنِ","untuk Yang Maha Pemurah"],["مَثَلًۭا","(sebagai) persamaan"],["ظَلَّ","menjadi"],["وَجْهُهُۥ","mukanya"],["مُسْوَدًّۭا","gelap"],["وَهُوَ","dan dia"],["كَظِيمٌ","(adalah) dipenuhi dengan kesedihan"]]],"4343":["(Dan apakah patut) Hamzah atau kata tanya di sini mengandung pengertian ingkar, sedangkan Wawu 'Athafnya menunjukkan 'Athaf jumlah kepada jumlah yang lain. Maksudnya, apakah patut mereka menjadikan bagi Allah (orang yang dibesarkan dalam perhiasan) maksudnya selalu berhias diri (sedangkan dia tidak dapat memberi alasan yang terang dalam pertengkaran) tidak pernah menang di dalam adu argumentasi karena kelemahan akalnya sebagai perempuan.",[["أَوَمَن","Kemudian (adalah) yang"],["يُنَشَّؤُا۟","dibesarkan"],["فِى","dalam"],["ٱلْحِلْيَةِ","perhiasan"],["وَهُوَ","dan dia"],["فِى","dalam"],["ٱلْخِصَامِ","pertikaian itu"],["غَيْرُ","(adalah) tidak"],["مُبِينٍۢ","yang nyata"]]],"4344":["(Dan mereka menjadikan malaikat-malaikat yang mereka itu adalah hamba-hamba Allah Yang Maha Pemurah sebagai orang-orang perempuan. Apakah mereka menyaksikan) apakah mereka hadir menyaksikan (penciptaan malaikat-malaikat itu? Kelak akan dituliskan persaksian mereka) yang menyatakan bahwa malaikat-malaikat itu adalah orang-orang perempuan (dan mereka akan dimintai pertanggungjawaban) di akhirat kelak tentang perkataan itu, karenanya mereka akan menerima siksaan yang pedih.",[["وَجَعَلُوا۟","Dan mereka buat"],["ٱلْمَلَـٰٓئِكَةَ","para Malaikat"],["ٱلَّذِينَ","orang yang"],["هُمْ","diri mereka"],["عِبَـٰدُ","(adalah) hamba"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["إِنَـٰثًا ۚ","perempuan"],["أَشَهِدُوا۟","Adakah mereka menyaksikan"],["خَلْقَهُمْ ۚ","ciptaan mereka"],["سَتُكْتَبُ","Akan dirakam"],["شَهَـٰدَتُهُمْ","kesaksian mereka"],["وَيُسْـَٔلُونَ","dan mereka akan ditanya"]]],"4345":["(Dan mereka berkata, \"Jika Allah Yang Maha Pemurah menghendaki tentulah kami tidak menyembah mereka\") tidak menyembah malaikat; maka ibadah atau penyembahan kami kepada mereka berdasarkan kehendak dari-Nya, Dia rela kami melakukan hal itu. Lalu Allah berfirman, \"(Tiadalah bagi mereka tentang hal itu) yakni dugaan mereka yang mengatakan bahwa Allah rela mereka menyembah malaikat (suatu pengetahuan pun, tidak lain) tiada lain (mereka hanya menduga-duga belaka) hanya berdusta belaka tentang itu, karenanya mereka harus menerima siksaan.",[["وَقَالُوا۟","Dan mereka berkata"],["لَوْ","Jika"],["شَآءَ","telah berkehendak"],["ٱلرَّحْمَـٰنُ","Yang Maha Pemurah"],["مَا","kami tidak akan menyembah mereka"],["عَبَدْنَـٰهُم ۗ","kami tidak akan menyembah mereka"],["مَّا","Tidak"],["لَهُم","mereka ada"],["بِذَٰلِكَ","tentang itu"],["مِنْ","sebarang"],["عِلْمٍ ۖ","pengetahuan"],["إِنْ","tiada apa"],["هُمْ","mereka (buat)"],["إِلَّا","tetapi"],["يَخْرُصُونَ","berbohong"]]],"4346":["(Atau adakah Kami memberikan sebuah Kitab kepada mereka sebelumnya) sebelum Alquran yang di dalamnya terdapat anjuran untuk menyembah selain Allah (lalu mereka berpegang dengan kitab itu?) hal tersebut tentu saja tidak akan terjadi.",[["أَمْ","Atau"],["ءَاتَيْنَـٰهُمْ","telah Kami berikan kepada mereka"],["كِتَـٰبًۭا","sebuah buku"],["مِّن","sebelum itu"],["قَبْلِهِۦ","sebelum itu"],["فَهُم","jadi mereka"],["بِهِۦ","kepadanya"],["مُسْتَمْسِكُونَ","(sedang) berpegang teguh"]]],"4347":["(Bahkan mereka berkata, 'Sesungguhnya kami mendapati bapak-bapak kami menganut suatu agama) yang diyakininya (dan sesungguhnya kami) berjalan atau mengikuti (jejak-jejak mereka sebagai petunjuk kami')\" dan bapak-bapak kami itu menyembah selain Allah.",[["بَلْ","Bahkan"],["قَالُوٓا۟","mereka berkata"],["إِنَّا","Sesungguhnya kami"],["وَجَدْنَآ","[kami] jumpa"],["ءَابَآءَنَا","nenek moyang kita"],["عَلَىٰٓ","ke atas"],["أُمَّةٍۢ","sebuah agama"],["وَإِنَّا","dan sesungguhnya, kita"],["عَلَىٰٓ","pada"],["ءَاثَـٰرِهِم","jejak kaki mereka"],["مُّهْتَدُونَ","(adalah) dibimbing"]]],"4348":["(Dan demikianlah Kami tidak mengutus sebelum kamu seorang pemberi peringatan pun dalam suatu negeri, melainkan orang-orang yang hidup mewah di negeri itu berkata) yakni mereka yang bergelimang di dalam kemewahan hidup pasti mengatakan sebagaimana apa yang telah dikatakan oleh kaummu, (\"Sesungguhnya kami mendapati bapak-bapak kami menganut suatu agama) suatu tuntunan (dan sesungguhnya kami adalah pengikut jejak-jejak mereka\") mengikuti jejak-jejak mereka.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["مَآ","tidak"],["أَرْسَلْنَا","Kami utus"],["مِن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["فِى","dalam"],["قَرْيَةٍۢ","sebuah bandar"],["مِّن","sebarang"],["نَّذِيرٍ","pemberi amaran"],["إِلَّا","kecuali"],["قَالَ","berkata"],["مُتْرَفُوهَآ","(orang-orang) yang kaya daripadanya"],["إِنَّا","Sesungguhnya kami"],["وَجَدْنَآ","[kami] jumpa"],["ءَابَآءَنَا","nenek moyang kita"],["عَلَىٰٓ","pada"],["أُمَّةٍۢ","sebuah agama"],["وَإِنَّا","dan sesungguhnya, kita"],["عَلَىٰٓ","[pada]"],["ءَاثَـٰرِهِم","jejak kaki mereka"],["مُّقْتَدُونَ","(ada) mengikuti"]]],"4349":["(Rasul itu berkata) kepada mereka, (\"Apakah) kalian akan mengikutinya juga (sekalipun aku membawa untuk kalian agama yang lebih nyata memberi petunjuk daripada apa yang kalian dapati bapak-bapak kalian menganutnya?\" Mereka menjawab, \"Sesungguhnya kami terhadap agama yang kamu diutus untuk menyampaikannya) yaitu yang disampaikan oleh kamu dan oleh rasul-rasul yang sebelum kamu (adalah orang-orang yang ingkar\") maka Allah berfirman seraya mengancam mereka melalui firman selanjutnya:",[["۞ قَـٰلَ","Dia berkata"],["أَوَلَوْ","Walaupun"],["جِئْتُكُم","Aku bawa kamu"],["بِأَهْدَىٰ","bimbingan yang lebih baik"],["مِمَّا","daripada apa"],["وَجَدتُّمْ","kamu jumpa"],["عَلَيْهِ","di atasnya"],["ءَابَآءَكُمْ ۖ","nenek moyang kamu"],["قَالُوٓا۟","Mereka berkata"],["إِنَّا","Sesungguhnya kami"],["بِمَآ","dengan apa"],["أُرْسِلْتُم","kamu dihantar"],["بِهِۦ","dengan [ia]"],["كَـٰفِرُونَ","(adalah) orang-orang kafir"]]],"4350":["(Maka Kami binasakan mereka) orang-orang yang mendustakan rasul-rasul sebelum kamu itu (maka perhatikanlah bagaimana kesudahan orang-orang yang mendustakan itu)",[["فَٱنتَقَمْنَا","Maka Kami mengambil pembalasan"],["مِنْهُمْ ۖ","daripada mereka"],["فَٱنظُرْ","Kemudian lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلْمُكَذِّبِينَ","(dari) orang-orang yang mendustakan"]]],"4351":["(Dan) ingatlah (ketika Ibrahim berkata kepada bapaknya dan kaumnya, \"Sesungguhnya aku tidak bertanggung jawab) atau berlepas diri (terhadap apa yang kalian sembah.)",[["وَإِذْ","Dan apabila"],["قَالَ","Ibrahim Said"],["إِبْرَٰهِيمُ","Ibrahim Said"],["لِأَبِيهِ","kepada bapanya"],["وَقَوْمِهِۦٓ","dan umatnya"],["إِنَّنِى","Sesungguhnya aku (adalah)"],["بَرَآءٌۭ","dipisahkan"],["مِّمَّا","daripada apa"],["تَعْبُدُونَ","kamu menyembah"]]],"4352":["(Tetapi aku menyembah Tuhan Yang menjadikanku) menyembah Allah yang telah menciptakan aku (karena sesungguhnya Dia akan memberi taufik kepadaku\") artinya Dia pasti membimbingku kepada agama-Nya.",[["إِلَّا","Kecuali"],["ٱلَّذِى","yang Esa"],["فَطَرَنِى","mencipta aku"],["فَإِنَّهُۥ","dan sesungguhnya, Dia"],["سَيَهْدِينِ","akan membimbing aku"]]],"4353":["(Dan Ibrahim menjadikannya) kalimat tauhid, yang tersimpul dari perkataannya, sebagaimana yang disitir oleh firman-Nya, \"Sesungguhnya aku pergi menghadap kepada Rabbku, dan Dia akan memberi petunjuk kepadaku...\" (Q.S. Ash shaffat, 99). (sebagai kalimat yang kekal pada keturunannya) pada anak cucunya, maka tetap akan ada orang-orang yang mengesakan Allah di antara keturunannya itu (supaya mereka) penduduk Mekah (kembali) meninggalkan apa yang biasa mereka lakukan, yaitu menyembah berhala, kemudian memeluk agama bapak moyang mereka, yakni Nabi Ibrahim.",[["وَجَعَلَهَا","Dan dia berjaya"],["كَلِمَةًۢ","satu perkataan"],["بَاقِيَةًۭ","berkekalan"],["فِى","antara"],["عَقِبِهِۦ","keturunannya"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَرْجِعُونَ","kembali"]]],"4354":["(Tetapi Aku telah memberikan kenikmatan hidup kepada mereka) kepada orang-orang musyrik itu (dan bapak-bapak mereka) dan Aku tidak menyegerakan hukuman-Ku kepada mereka (sehingga datanglah kebenaran kepada mereka) Alquran yang membawa kebenaran (dan seorang rasul yang memberi penjelasan) yang menampakkan kepada mereka hukum-hukum syariat, yaitu Nabi Muhammad saw.",[["بَلْ","Bahkan"],["مَتَّعْتُ","Aku memberi kenikmatan"],["هَـٰٓؤُلَآءِ","(kepada) ini"],["وَءَابَآءَهُمْ","dan nenek moyang mereka"],["حَتَّىٰ","sehingga"],["جَآءَهُمُ","datang kepada mereka"],["ٱلْحَقُّ","kebenaran"],["وَرَسُولٌۭ","dan seorang Rasul"],["مُّبِينٌۭ","yang nyata"]]],"4355":["(Dan tatkala kebenaran itu datang kepada mereka) yakni Alquran (mereka berkata, \"Ini adalah sihir dan sesungguhnya kami adalah orang-orang yang mengingkarinya.\")",[["وَلَمَّا","Dan apabila"],["جَآءَهُمُ","datang kepada mereka"],["ٱلْحَقُّ","kebenaran"],["قَالُوا۟","mereka berkata"],["هَـٰذَا","Ini"],["سِحْرٌۭ","(ialah) sihir"],["وَإِنَّا","dan sesungguhnya, kita"],["بِهِۦ","daripadanya"],["كَـٰفِرُونَ","(adalah) orang-orang kafir"]]],"4356":["(Dan mereka berkata, \"Mengapa tidak) kenapa tidak (diturunkan Alquran ini kepada seorang besar dari) kalangan penduduk (da negeri) yakni Mekah dan Madinah, maksudnya dari salah satu antara keduanya (yang besar ini?\") yang dimaksud oleh mereka adalah Al Walid Ibnu Mughirah di Mekah, atau Urwah ibnu Mas'ud Ats Tsaqafi di Thaif.",[["وَقَالُوا۟","Dan mereka berkata"],["لَوْلَا","kenapa tidak"],["نُزِّلَ","telah diturunkan"],["هَـٰذَا","ini"],["ٱلْقُرْءَانُ","al-Quran"],["عَلَىٰ","kepada"],["رَجُلٍۢ","seorang lelaki"],["مِّنَ","daripada"],["ٱلْقَرْيَتَيْنِ","kedua-dua bandar itu"],["عَظِيمٍ","yang besar"]]],"4357":["(Apakah mereka yang membagi-bagi rahmat Rabbmu?) yang dimaksud dengan rahmat adalah kenabian (Kami telah menentukan antara mereka penghidupan mereka dalam kehidupan dunia) maka Kami jadikan sebagian dari mereka kaya dan sebagian lainnya miskin (dan Kami telah meninggikan sebagian mereka) dengan diberi kekayaan (atas sebagian yang lain beberapa derajat, agar sebagian mereka dapat mempergunakan) golongan orang-orang yang berkecukupan (sebagian yang lain) atas golongan orang-orang yang miskin (sebagai pekerja) maksudnya, pekerja berupah; huruf Ya di sini menunjukkan makna Nasab, dan menurut suatu qiraat lafal Sukhriyyan dibaca Sikhriyyan yaitu dengan dikasrahkan huruf Sin-nya (Dan rahmat Rabbmu) yakni surga Rabbmu (lebih baik daripada apa yang mereka kumpulkan) di dunia.",[["أَهُمْ","Adakah mereka"],["يَقْسِمُونَ","mengedarkan"],["رَحْمَتَ","(the) Rahmat"],["رَبِّكَ ۚ","Tuhanmu"],["نَحْنُ","Kami"],["قَسَمْنَا","[Kami] mengedarkan"],["بَيْنَهُم","antara mereka"],["مَّعِيشَتَهُمْ","rezeki mereka"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا ۚ","dunia"],["وَرَفَعْنَا","dan Kami bangkitkan"],["بَعْضَهُمْ","sebahagian mereka"],["فَوْقَ","di atas"],["بَعْضٍۢ","yang lain"],["دَرَجَـٰتٍۢ","(dalam) darjah"],["لِّيَتَّخِذَ","supaya boleh mengambil"],["بَعْضُهُم","sebahagian mereka"],["بَعْضًۭا","yang lain"],["سُخْرِيًّۭا ۗ","(untuk) perkhidmatan"],["وَرَحْمَتُ","Tetapi Rahmat"],["رَبِّكَ","Tuhanmu"],["خَيْرٌۭ","(lebih) baik"],["مِّمَّا","daripada apa"],["يَجْمَعُونَ","mereka terkumpul"]]],"4358":["(Dan sekiranya bukan karena hendak menghindari manusia menjadi umat yang satu) dalam kekafiran (tentulah Kami buatkan bagi orang-orang yang kafir kepada Tuhan Yang Maha Pemurah bagi rumah-rumah mereka) lafal Libuyutihim menjadi Badal dari lafal Liman (loteng-loteng) dapat dibaca Saqfan atau Suqfan keduanya adalah bentuk jamak (dari perak dan juga tangga-tangga) dari perak pula (yang mereka menaikinya) yang dapat mereka naiki untuk mencapai atap rumah-rumah mereka.",[["وَلَوْلَآ","Dan jika tidak"],["أَن","bahawa"],["يَكُونَ","(akan) menjadi"],["ٱلنَّاسُ","[the] manusia"],["أُمَّةًۭ","sesebuah komuniti"],["وَٰحِدَةًۭ","satu"],["لَّجَعَلْنَا","Kami (akan) buat"],["لِمَن","untuk (seorang) yang"],["يَكْفُرُ","tidak beriman"],["بِٱلرَّحْمَـٰنِ","dalam Yang Maha Pemurah"],["لِبُيُوتِهِمْ","untuk rumah mereka"],["سُقُفًۭا","bumbung"],["مِّن","daripada"],["فِضَّةٍۢ","perak"],["وَمَعَارِجَ","dan tangga"],["عَلَيْهَا","atas mana"],["يَظْهَرُونَ","mereka melekap"]]],"4359":["(Dan Kami buatkan pula -pintu-pintu bagi rumah-rumah mereka) yang juga terbuat dari perak (dan) begitu pula Kami buatkan untuk mereka (dipan-dipan) yang terbuat dari perak; lafal Sururan adalah bentuk jamak dari lafal Sarirun artinya, ranjang atau dipan (yang mereka bertelekan atasnya.)",[["وَلِبُيُوتِهِمْ","Dan untuk rumah mereka"],["أَبْوَٰبًۭا","pintu"],["وَسُرُرًا","dan pelamin"],["عَلَيْهَا","atas mana"],["يَتَّكِـُٔونَ","mereka bersandar"]]],"4360":["(Dan Kami buatkan pula perhiasan-perhiasan) dari emas untuk mereka. Makna ayat, seandainya tidak karena khawatir orang mukmin akan menjadi kafir, bila Kami anugerahkan kepadanya hal-hal tersebut sebagaimana yang telah Kami berikan kepada orang kafir, tentulah Kami akan memberikan kepada orang mukmin hal-hal itu. Karena keduniaan itu tidak ada artinya di sisi Kami, dan kelak di akhirat tidak berharga sama sekali bila dibandingkan dengan nikmat surga. (Dan sesungguhnya) lafal In di sini adalah bentuk Takhfif dari Inna yang Tsaqilah; artinya sesungguhnya (semuanya itu tiada lain) jika dibaca Lama dengan cara Takhfif, maka huruf Ma adalah Zaidah, jika dibaca Lamma dengan memakai Tasydid pada huruf Mim maknanya sama dengan lafal Illa, dan lafal In bermakna Nafi. Menurut bacaan pertama arti ayat ini ialah, \"Dan sesungguhnya semuanya itu hanyalah. \" Menurut bacaan kedua artinya menjadi, \"Dan tiadalah semuanya itu melainkan (kesenangan kehidupan dunia) yang dapat dipakai untuk bersenang-senang kemudian lenyap sesudah itu (dan kehidupan di akhirat itu) yakni di surga (di sisi Rabbmu bagi orang-orang yang bertakwa.)",[["وَزُخْرُفًۭا ۚ","Dan perhiasan emas"],["وَإِن","Dan bukan (adalah)"],["كُلُّ","semua"],["ذَٰلِكَ","bahawa"],["لَمَّا","tetapi"],["مَتَـٰعُ","suatu kenikmatan"],["ٱلْحَيَوٰةِ","(dari) kehidupan"],["ٱلدُّنْيَا ۚ","dunia"],["وَٱلْـَٔاخِرَةُ","Dan akhirat"],["عِندَ","dengan"],["رَبِّكَ","Tuhanmu"],["لِلْمُتَّقِينَ","(adalah) untuk orang-orang yang bertakwa"]]],"4361":["(Barang siapa yang berpaling) yaitu memalingkan diri (dari pengajaran Tuhan Yang Maha Pemurah) dari Alquran (Kami adakan) Kami jadikan (baginya setan, maka setan itulah yang menjadi teman yang selalu menyertainya) yakni tidak pernah berpisah darinya.",[["وَمَن","Dan sesiapa"],["يَعْشُ","berpaling"],["عَن","daripada"],["ذِكْرِ","(the) zikir"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["نُقَيِّضْ","Kami melantik"],["لَهُۥ","baginya"],["شَيْطَـٰنًۭا","syaitan"],["فَهُوَ","kemudian dia"],["لَهُۥ","(adalah) kepadanya"],["قَرِينٌۭ","seorang peneman"]]],"4362":["(Dan sesungguhnya mereka) setan-setan itu (benar-benar menghalangi mereka) menghalangi orang-orang yang berpaling itu (dari jalan yang benar) atau jalan petunjuk (dan mereka menyangka bahwa mereka mendapat petunjuk) disebutkannya Dhamir dengan memakai kata jamak karena memandang segi makna yang dikandung lafal Man.",[["وَإِنَّهُمْ","Dan sesungguhnya, mereka"],["لَيَصُدُّونَهُمْ","sesungguhnya, balikkanlah mereka"],["عَنِ","daripada"],["ٱلسَّبِيلِ","Jalan"],["وَيَحْسَبُونَ","dan mereka berfikir"],["أَنَّهُم","bahawa mereka"],["مُّهْتَدُونَ","(adalah) dibimbing"]]],"4363":["(Sehingga apabila orang yang berpaling itu datang kepada Kami) bersama dengan temannya atau setannya di hari kiamat kelak (dia berkata,) orang yang berpaling itu kepada temannya atau setannya (\"Aduhai) huruf Ya di sini menunjukkan makna Tanbih (seandainya jarak antara aku dan kamu seperti jarak antara masyriq dan Magrib) yakni sejauh jarak antara timur dan barat (maka sejelek-jelek teman) bagiku adalah kamu.\" Lalu Allah berfirman:",[["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["جَآءَنَا","dia datang kepada Kami"],["قَالَ","katanya"],["يَـٰلَيْتَ","Oh, adakah itu"],["بَيْنِى","antara aku"],["وَبَيْنَكَ","dan antara kamu"],["بُعْدَ","(adalah) jarak"],["ٱلْمَشْرِقَيْنِ","(dari) Timur dan Barat"],["فَبِئْسَ","Betapa celakanya"],["ٱلْقَرِينُ","pendamping itu"]]],"4364":["(Sekali-kali tidak akan memberi manfaat kepada kalian) angan-angan dan penyesalan kalian itu, hai orang-orang yang berpaling (di hari ini karena kalian telah berbuat aniaya) maksudnya telah jelaslah kelaliman kalian dengan sebab menyekutukan Allah sewaktu di dunia. Lafal Idz merupakan Badal dari lafal Al Yaumu. (Bahwasanya kalian) bersama dengan teman-teman kalian (bersekutu dalam azab ini) adanya illat dalam ayat ini diperkirakan keberadaannya, tidak disebutkan karena kurang penting.",[["وَلَن","Dan tidak pernah"],["يَنفَعَكُمُ","akan memberi manfaat kepada kamu"],["ٱلْيَوْمَ","Hari itu"],["إِذ","apabila"],["ظَّلَمْتُمْ","kamu telah melakukan kesalahan"],["أَنَّكُمْ","bahawa kamu"],["فِى","(akan) masuk"],["ٱلْعَذَابِ","azab"],["مُشْتَرِكُونَ","perkongsian"]]],"4365":["(Maka apakah kamu dapat menjadikan orang yang pekak dapat mendengar, atau dapatkah kamu memberi petunjuk kepada orang yang buta hatinya dan kepada orang yang tetap dalam kesesatan yang nyata?) jelas sesatnya, maksudnya mereka tidak beriman.",[["أَفَأَنتَ","Kemudian bolehkah kamu"],["تُسْمِعُ","sebab dengar"],["ٱلصُّمَّ","yang pekak"],["أَوْ","atau"],["تَهْدِى","panduan"],["ٱلْعُمْىَ","yang buta"],["وَمَن","dan (satu) siapa"],["كَانَ","ialah"],["فِى","dalam"],["ضَلَـٰلٍۢ","satu kesilapan"],["مُّبِينٍۢ","yang nyata"]]],"4366":["(Sungguh, jika) lafal Imma asalnya adalah gabungan antara Syarthiyyah dan Ma Zaidah (Kami mewafatkan kamu) sebelum Kami mengazab mereka (maka sesungguhnya Kami akan menyiksa mereka) di akhirat.",[["فَإِمَّا","Dan sama ada"],["نَذْهَبَنَّ","Kami bawa kamu pergi"],["بِكَ","Kami bawa kamu pergi"],["فَإِنَّا","maka sesungguhnya Kami"],["مِنْهُم","daripada mereka"],["مُّنتَقِمُونَ","(akan) mengambil pembalasan"]]],"4367":["(Atau kami memperlihatkan kepadamu) sewaktu kamu masih hidup (apa yang telah Kami ancamkan kepada mereka) yakni azab yang Kami ancamkan itu (maka sesungguhnya Kami atas mereka) maksudnya, untuk mengazab mereka (berkuasa) sangat berkuasa atau sangat mampu.",[["أَوْ","Atau"],["نُرِيَنَّكَ","Kami tunjukkan kepada kamu"],["ٱلَّذِى","itu yang"],["وَعَدْنَـٰهُمْ","Kami telah berjanji kepada mereka"],["فَإِنَّا","maka sesungguhnya Kami"],["عَلَيْهِم","atas mereka"],["مُّقْتَدِرُونَ","mempunyai kuasa penuh"]]],"4368":["(Maka berpegang teguhlah kamu kepada apa yang telah diwahyukan kepadamu) yakni Alquran. (Sesungguhnya kamu berada di atas jalan) atau tuntunan (yang lurus.)",[["فَٱسْتَمْسِكْ","Jadi berpegang teguh"],["بِٱلَّذِىٓ","kepada yang"],["أُوحِىَ","didedahkan"],["إِلَيْكَ ۖ","kepada kamu"],["إِنَّكَ","Sesungguhnya kamu"],["عَلَىٰ","(ada) pada"],["صِرَٰطٍۢ","a Laluan"],["مُّسْتَقِيمٍۢ","Lurus"]]],"4369":["(Dan sesungguhnya Alquran itu benar-benar adalah suatu kemuliaan besar) benar-benar merupakan kemuliaan yang besar (bagimu dan bagi kaummu) karena diturunkan dengan memakai bahasa mereka (dan kelak kalian akan diminta pertanggungan jawab) tentang pengamalannya.",[["وَإِنَّهُۥ","Dan sesungguhnya, ia"],["لَذِكْرٌۭ","(adalah) sesungguhnya, peringatan"],["لَّكَ","bagi kamu"],["وَلِقَوْمِكَ ۖ","dan rakyatmu"],["وَسَوْفَ","dan tidak lama lagi"],["تُسْـَٔلُونَ","kamu akan disoal siasat"]]],"4370":["(Dan tanyakanlah kepada rasul-rasul Kami yang telah Kami utus sebelum kamu, \"Adakah Kami menentukan selain Allah Yang Maha Pemurah) (sebagai tuhan-tuhan untuk disembah), menurut suatu pendapat bahwa hal ini memang berdasarkan kenyataan, yaitu seumpamanya Allah mengumpulkan rasul-rasul itu pada malam sewaktu nabi diisra-kan. Menurut pendapat yang lain bahwa yang dimaksud adalah umat-umat dari kalangan ahli kitab. Kedua pendapat tadi tidak usah diselidiki kebenarannya, karena makna yang dimaksud dari perintah menanyakan ini ialah untuk menetapkan terhadap orang-orang musyrik Quraisy, bahwasanya tiada seorang utusan pun dari Allah dan tiada pula suatu kitab pun yang diturunkan-Nya yang memerintahkan untuk menyembah kepada selain Allah.",[["وَسْـَٔلْ","Dan bertanya"],["مَنْ","(mereka) siapa"],["أَرْسَلْنَا","Kami utus"],["مِن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["مِن","daripada"],["رُّسُلِنَآ","Rasul-rasul Kami"],["أَجَعَلْنَا","adakah Kami jadikan"],["مِن","selain"],["دُونِ","selain"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["ءَالِهَةًۭ","tuhan"],["يُعْبَدُونَ","untuk disembah"]]],"4371":["(Dan sesungguhnya Kami telah mengutus Musa dengan membawa mukjizat-mukjizat Kami kepada Firaun dan pemuka-pemuka kaumnya) yaitu bangsa Kobtik, (maka Musa berkata, \"Sesungguhnya aku adalah utusan dari Rabb seru sekalian alam.\")",[["وَلَقَدْ","Dan sungguh"],["أَرْسَلْنَا","Kami utus"],["مُوسَىٰ","Musa"],["بِـَٔايَـٰتِنَآ","dengan Tanda-tanda Kami"],["إِلَىٰ","kepada"],["فِرْعَوْنَ","Firaun"],["وَمَلَإِي۟هِۦ","dan ketua-ketuanya"],["فَقَالَ","dan dia berkata"],["إِنِّى","Memang aku"],["رَسُولُ","seorang Rasul"],["رَبِّ","(dari) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"4372":["(Maka tatkala dia datang kepada mereka dengan membawa mukjirat-mukjizat Kami) yang menunjukkan kebenaran risalah-Nya (dengan serta merta mereka menertawakannya.)",[["فَلَمَّا","Tetapi apabila"],["جَآءَهُم","dia datang kepada mereka"],["بِـَٔايَـٰتِنَآ","dengan Tanda-tanda Kami"],["إِذَا","lihatlah"],["هُم","mereka"],["مِّنْهَا","pada mereka"],["يَضْحَكُونَ","ketawa"]]],"4373":["(Dan tidaklah Kami perlihatkan kepada mereka sesuatu tanda) yang menunjukkan azab Kami seperti banjir, topan, yaitu berupa air bah yang melanda rumah-rumah mereka yang ketinggiannya mencapai leher orang yang sedang duduk, hal ini berlangsung selama. tujuh hari, dan juga belalang-belalang yang memusnahkan tanaman-tanaman mereka (melainkan tanda atau azab itu lebih besar daripada azab-azab lainnya) yang sebelumnya. (Dan Kami timpakan kepada mereka azab supaya mereka kembali) sadar dari kekafirannya.",[["وَمَا","Dan tidak"],["نُرِيهِم","Kami menunjukkan kepada mereka"],["مِّنْ","daripada"],["ءَايَةٍ","sebuah Tanda"],["إِلَّا","tetapi"],["هِىَ","ia"],["أَكْبَرُ","(adalah) lebih besar"],["مِنْ","daripada"],["أُخْتِهَا ۖ","kakaknya"],["وَأَخَذْنَـٰهُم","dan Kami siksa mereka"],["بِٱلْعَذَابِ","dengan hukuman"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَرْجِعُونَ","kembali"]]],"4374":["(Dan mereka berkata) kepada Musa tatkala mereka melihat adanya azab itu, (\"Hai ahli sihir!) maksudnya, hai orang yang alim lagi sempurna ilmunya! Dikatakan demikian karena menurut mereka ilmu sihir itu adalah ilmu yang paling diagungkan di kalaagan mereka (Berdoalah kepada Rabbmu untuk kami, sesuai dengan apa yang telah dijanjikan-Nya kepadamu) yakni Dia akan melepaskan kami dari azab ini jika kami beriman (sesungguhnya kami benar-benar akan menjadi orang-orang yang mendapat petunjuk\") atau mau beriman.",[["وَقَالُوا۟","Dan mereka berkata"],["يَـٰٓأَيُّهَ","Wahai"],["ٱلسَّاحِرُ","[si] ahli silap mata"],["ٱدْعُ","Ajak"],["لَنَا","bagi kami"],["رَبَّكَ","Tuhanmu"],["بِمَا","oleh apa"],["عَهِدَ","Dia telah membuat perjanjian"],["عِندَكَ","bersama kamu"],["إِنَّنَا","Sesungguhnya kami"],["لَمُهْتَدُونَ","(akan) mendapat petunjuk"]]],"4375":["(Maka tatkala Kami hilangkan) berkat doa Musa (azab itu dari mereka, dengan serta merta mereka memungkiri) janjinya, bahkan mereka masih tetap melaju di dalam kekafirannya.",[["فَلَمَّا","Tetapi apabila"],["كَشَفْنَا","Kami mengeluarkan"],["عَنْهُمُ","daripada mereka"],["ٱلْعَذَابَ","azab"],["إِذَا","lihatlah"],["هُمْ","mereka"],["يَنكُثُونَ","pecah (perkataan mereka)"]]],"4376":["(Dan Firaun berseru) dengan nada penuh kesombongan (kepada kaumnya seraya berkata, \"Hai kaumku, bukankah kerajaan Mesir ini kepunyaanku dan sungai-sungai ini) yaitu sungai Nil dan anak-anaknya (mengalir di bawahku) di bawah keraton-keratonku, adalah kepunyaanku juga (maka apakah kalian tidak melihat) keagungan dan kebesaranku?",[["وَنَادَىٰ","Dan dipanggil keluar"],["فِرْعَوْنُ","Firaun"],["فِى","antara"],["قَوْمِهِۦ","umatnya"],["قَالَ","dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["أَلَيْسَ","bukan"],["لِى","untuk aku"],["مُلْكُ","(kerajaan)."],["مِصْرَ","(dari) Mesir"],["وَهَـٰذِهِ","dan ini"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["تَجْرِى","mengalir"],["مِن","di bawah aku"],["تَحْتِىٓ ۖ","di bawah aku"],["أَفَلَا","Kemudian jangan"],["تُبْصِرُونَ","kamu lihat"]]],"4377":["(Bukankah) kalian telah melihat sesudah kesemuanya itu (aku lebih baik dari orang ini) dari Nabi Musa (yang dia adalah orang hina) lemah lagi hina (dan yang hampir tidak dapat berbicara dengan jelas) tidak dapat menjelaskan perkataannya, karena sewaktu kecil ia pernah memakan bara api, hingga lisannya pelan atau tidak fasih.",[["أَمْ","Atau"],["أَنَا۠","adakah aku"],["خَيْرٌۭ","lebih baik"],["مِّنْ","daripada"],["هَـٰذَا","ini"],["ٱلَّذِى","seorang yang"],["هُوَ","dia"],["مَهِينٌۭ","(adalah) tidak penting"],["وَلَا","dan hampir tidak"],["يَكَادُ","dan hampir tidak"],["يُبِينُ","yang nyata"]]],"4378":["(Mengapa tidak) kenapa tidak dipakaikan kepadanya jika memang ia orang yang benar di dalam pengakuannya (gelang dari emas) lafal Asawirah adalah bentuk jamak dari lafal Aswiratun yang wazannya sama dengan lafal Aghribatun, dan lafal Aswiratun ini merupakan bentuk jamak pula dari lafal Siwarun. Maksud Firaun, mengapa tidak dipakaikan kepadanya gelang dari emas sebagaimana kebiasaan orang-orang yang diberi kekuasaan olehnya, yaitu orang tersebut diberi pakaian kebesaran yang terbuat dari emas dan pula dipakaikan kepadanya gelang emas sebagai tanda kedudukannya (atau malaikat datang bersama-sama dia mengiringkannya\") datang berturut-turut kepadanya seraya menyatakan kebenaran kerasulannya.",[["فَلَوْلَآ","Lalu kenapa tidak"],["أُلْقِىَ","diletakkan"],["عَلَيْهِ","pada dia"],["أَسْوِرَةٌۭ","gelang tangan"],["مِّن","daripada"],["ذَهَبٍ","emas"],["أَوْ","atau"],["جَآءَ","datang"],["مَعَهُ","dengan dia"],["ٱلْمَلَـٰٓئِكَةُ","para Malaikat"],["مُقْتَرِنِينَ","menemani (dia)"]]],"4379":["(Maka Firaun mempengaruhi) berupaya menanamkan pengaruhnya kepada (kaumnya, lalu mereka patuh kepadanya) mematuhi apa yang dikehendaki oleh Firaun, yaitu mendustakan Musa (karena sesungguhnya mereka adalah kaum yang fasik.)",[["فَٱسْتَخَفَّ","Jadi dia tertipu"],["قَوْمَهُۥ","umatnya"],["فَأَطَاعُوهُ ۚ","dan mereka taat kepadanya"],["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوا۟","adalah"],["قَوْمًۭا","suatu kaum"],["فَـٰسِقِينَ","membangkang menderhaka"]]],"4380":["(Maka tatkala mereka membuat Kami murka) (Kami menghukum mereka lalu Kami tenggelamkan mereka semuanya di laut.)",[["فَلَمَّآ","Maka apabila"],["ءَاسَفُونَا","mereka membuat Kami marah"],["ٱنتَقَمْنَا","Kami mengambil pembalasan"],["مِنْهُمْ","daripada mereka"],["فَأَغْرَقْنَـٰهُمْ","dan Kami tenggelamkan mereka"],["أَجْمَعِينَ","semua"]]],"4381":["(Dan Kami jadikan mereka sebagai pelajaran) lafal Salafan merupakan bentuk jamak dari lafal salifun, wazannya sama dengan lafal Khadimun atau pelayan, yang jamaknya adalah Khadamun; yakni orang-orang terdahulu yang dijadikan sebagai pelajaran (dan contoh bagi orang-orang yang kemudian) sesudah mereka, di mana orang-orang yang sesudah mereka itu dapat mengambil contoh dari keadaan mereka, karena itu mereka tidak berani melakukan hal-hal serupa.",[["فَجَعَلْنَـٰهُمْ","Dan Kami jadikan mereka"],["سَلَفًۭا","satu preseden"],["وَمَثَلًۭا","dan contoh"],["لِّلْـَٔاخِرِينَ","untuk (generasi) kemudian"]]],"4382":["(Dan tatkala dijadikan) dibuat (putra Maryam sebagai perumpamaan) yaitu ketika Allah swt. menurunkan firman-Nya, \"Sesungguhnya kalian dan apa yang kalian sembah selain Allah adalah makanan neraka Jahanam..\" (Q.S. Al Anbiya, 98). Seketika itu juga orang-orang musyrik mengatakan, \"Kami rela bila ternyata tuhan-tuhan sesembahan kami bersama dengan Isa, karena ia pun menjadi sesembahan selain Allah pula (tiba-tiba kaummu) yakni mereka yang musyrik (terhadap perumpamaan itu) terhadap misal tersebut (menertawakannya) karena gembira mendengar perumpamaan itu.",[["۞ وَلَمَّا","Dan apabila"],["ضُرِبَ","dibentangkan"],["ٱبْنُ","(si) anak lelaki"],["مَرْيَمَ","(dari) Maryam"],["مَثَلًا","(sebagai) contoh"],["إِذَا","lihatlah"],["قَوْمُكَ","orang kamu"],["مِنْهُ","mengenainya"],["يَصِدُّونَ","ketawa kuat"]]],"4383":["(Dan mereka berkata, 'Manakah yang lebih baik tuhan-tuhan kami atau dia?') yakni nabi Isa, maka karenanya kami rela tuhan-tuhan kami bersama dia (Mereka tidak memberikan perumpamaan itu) atau misal tersebut (kepadamu melainkan dengan maksud membantah saja) atau menyanggah kamu dengan cara yang batil, karena mereka telah mengetahui, bahwa berhala-berhala yang tidak berakal itu tidak akan dapat menyamai Nabi Isa a.s. (sebenarnya mereka adalah kaum yang suka bertengkar\") sangat gemar bertengkar.",[["وَقَالُوٓا۟","Dan mereka berkata"],["ءَأَـٰلِهَتُنَا","Adakah tuhan kita"],["خَيْرٌ","lebih baik"],["أَمْ","atau"],["هُوَ ۚ","dia"],["مَا","Tidak"],["ضَرَبُوهُ","mereka membentangkannya"],["لَكَ","kepada kamu"],["إِلَّا","kecuali"],["جَدَلًۢا ۚ","(untuk) hujah"],["بَلْ","Bahkan"],["هُمْ","mereka"],["قَوْمٌ","(adalah) suatu kaum"],["خَصِمُونَ","bersifat argumentatif"]]],"4384":["(Bukankah) tidak lain (dia) yakni Nabi Isa itu (hanyalah seorang hamba yang Kami berikan kepadanya nikmat) kenabian (dan Kami jadikan dia) yaitu kelahirannya dengan tanpa ayah (sebagai perumpamaan untuk Bani Israel) maksudnya, sebagai bukti yang menunjukkan akan kekuasaan Allah swt. yang mampu menciptakan apa yang dikehendaki-Nya.",[["إِنْ","Tidak"],["هُوَ","dia"],["إِلَّا","(adalah) kecuali"],["عَبْدٌ","seorang hamba"],["أَنْعَمْنَا","Kami melimpahkan nikmat Kami"],["عَلَيْهِ","pada dia"],["وَجَعَلْنَـٰهُ","dan Kami jadikan dia"],["مَثَلًۭا","satu contoh"],["لِّبَنِىٓ","untuk (kaum) Bani Israil"],["إِسْرَٰٓءِيلَ","untuk (kaum) Bani Israil"]]],"4385":["(Dan kalau Kami kehendaki benar-benar Kami jadikan sebagai ganti kalian) untuk mengganti kalian (di muka bumi malaikat-malaikat yang turun temurun) misalnya, kalian Kami binasakan terlebih dahulu, lalu Kami jadikan malaikat sebagai ganti kalian.",[["وَلَوْ","Dan jika"],["نَشَآءُ","Kami berkehendak"],["لَجَعَلْنَا","sesungguhnya Kami (boleh) menjadikan"],["مِنكُم","antara kamu"],["مَّلَـٰٓئِكَةًۭ","malaikat"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["يَخْلُفُونَ","berjaya"]]],"4386":["(Dan sesungguhnya dia) Nabi Isa itu (benar-benar merupakan pengetahuan tentang hari kiamat) artinya, dengan diturunkannya dia maka diketahuilah dekatnya hari kiamat. (Karena itu janganlah kalian ragu-ragu tentang kiamat itu) atau janganlah kalian meragukannya. Lafal Tamtarunna asalnya Tamtarunanna, kemudian dibuang daripadanya Nun alamat rafa' karena dijazmkan, dan dibuang pula daripadanya Wawu Dhamir jamak tetapi bukan karena Illat bertemunya dua huruf yang disukunkan, sehingga jadilah Tamtarunna. (Dan) katakanlah kepada mereka, (\"Ikutilah aku) yakni ajaran tauhid ini. (Inilah) apa yang kuperintahkan kalian menjalankannya (jalan) atau tuntunan (yang lurus.)",[["وَإِنَّهُۥ","Dan sesungguhnya, ia"],["لَعِلْمٌۭ","sesungguhnya (adalah) ilmu"],["لِّلسَّاعَةِ","hari kiamat"],["فَلَا","Jadi (jangan)"],["تَمْتَرُنَّ","(bersifat) ragu-ragu"],["بِهَا","mengenainya"],["وَٱتَّبِعُونِ ۚ","dan ikutlah Aku"],["هَـٰذَا","Ini"],["صِرَٰطٌۭ","(ialah) Jalan"],["مُّسْتَقِيمٌۭ","Lurus"]]],"4387":["(Dan janganlah kalian sekali-kali dipalingkan) dapat dipalingkan dari agama Allah (oleh setan; sesungguhnya setan itu musuh yang nyata bagi kalian\") nyata permusuhannya.",[["وَلَا","Dan (jangan)"],["يَصُدَّنَّكُمُ","mengelak kamu"],["ٱلشَّيْطَـٰنُ ۖ","syaitan"],["إِنَّهُۥ","Sesungguhnya dia"],["لَكُمْ","(adalah) untuk kamu"],["عَدُوٌّۭ","seorang musuh"],["مُّبِينٌۭ","yang nyata"]]],"4388":["(Dan tatkala Isa datang dengan membawa keterangan-keterangan) mukjizat-mukjizat dan syariat-syariat (dia berkata, \"Sesungguhnya aku datang kepada kalian dengan membawa hikmah) kenabian dan syariat Injil (dan untuk menjelaskan kepada kalian sebagian dari apa yang kalian berselisih tentangnya) yakni tentang hukum-hukum Taurat, yaitu menyangkut masalah agama dan masalah-masalah lainnya, Nabi Isa menjelaskan kepada mereka perkara agama yang sebenarnya (maka bertakwalah kepada Allah dan taatlah kepadaku.\")",[["وَلَمَّا","Dan apabila"],["جَآءَ","datang"],["عِيسَىٰ","Isa"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["قَالَ","dia berkata"],["قَدْ","Sesungguhnya"],["جِئْتُكُم","Aku telah datang kepada kamu"],["بِٱلْحِكْمَةِ","dengan hikmah"],["وَلِأُبَيِّنَ","dan itu aku jelaskan"],["لَكُم","kepada kamu"],["بَعْضَ","beberapa"],["ٱلَّذِى","(daripada) yang"],["تَخْتَلِفُونَ","kamu berbeza"],["فِيهِ ۖ","di dalamnya"],["فَٱتَّقُوا۟","Jadi takut"],["ٱللَّهَ","Allah"],["وَأَطِيعُونِ","dan taat kepadaku"]]],"4389":["(Sesungguhnya Allah Dialah Rabbku dan Rabb kalian, maka sembahlah Dia, ini adalah jalan) tuntunan (yang lurus.)",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["رَبِّى","(ialah) Tuhanku"],["وَرَبُّكُمْ","dan Tuhanmu"],["فَٱعْبُدُوهُ ۚ","maka sembahlah Dia"],["هَـٰذَا","Ini"],["صِرَٰطٌۭ","(adalah) Jalan"],["مُّسْتَقِيمٌۭ","Lurus"]]],"4390":["(Maka berselisihlah golongan-golongan di antara mereka) tentang perkara Nabi Isa ini, apakah dia anak Allah atau Allah, atau tuhan yang ketiga (maka kecelakaan yang besarlah) lafal Al Wail menunjukkan kalimat azab (bagi orang-orang yang lalim) bagi orang-orang kafir, karena perkataan yang mereka ucapkan mengenai Nabi Isa (yaitu siksaan hari yang pedih) atau azab yang menyakitkan.",[["فَٱخْتَلَفَ","Tetapi berbeza"],["ٱلْأَحْزَابُ","puak-puak"],["مِنۢ","daripada"],["بَيْنِهِمْ ۖ","antara mereka"],["فَوَيْلٌۭ","jadi celaka"],["لِّلَّذِينَ","kepada mereka yang"],["ظَلَمُوا۟","dizalimi"],["مِنْ","daripada"],["عَذَابِ","azab"],["يَوْمٍ","hari"],["أَلِيمٍ","yang pedih"]]],"4391":["(Mereka tidak menunggu) orang-orang kafir Mekah tidak menunggu-nunggu (kecuali kedatangan hari kiamat kepada mereka) lafal An Ta-tiyahum menjadi Badal dari lafal As Sa'ah (dengan tiba-tiba) atau sekonyong-konyong (sedangkan mereka tidak menyadarinya) tidak menyadari kedatangannya sebelum itu.",[["هَلْ","Adakah"],["يَنظُرُونَ","mereka menunggu"],["إِلَّا","kecuali"],["ٱلسَّاعَةَ","(untuk) hari kiamat"],["أَن","bahawa"],["تَأْتِيَهُم","ia sepatutnya menimpa mereka"],["بَغْتَةًۭ","tiba-tiba"],["وَهُمْ","sedangkan mereka"],["لَا","jangan"],["يَشْعُرُونَ","mempersepsikan"]]],"4392":["(Teman-teman akrab) dalam hal maksiat sewaktu di dunia (pada hari itu) pada hari kiamat itu lafal Yaumaidzin berta'alluq kepada firman selanjutnya (sebagian dari mereka menjadi musuh bagi sebagian yang lain kecuali orang-orang yang bertakwa) terkecuali orang-orang yang saling kasih mengasihi di dalam ketaatan kepada Allah swt., mereka itulah yang sebenarnya berteman, kemudian dikatakan kepada mereka yang bertakwa itu,",[["ٱلْأَخِلَّآءُ","Kawan-kawan"],["يَوْمَئِذٍۭ","hari itu"],["بَعْضُهُمْ","sebahagian mereka"],["لِبَعْضٍ","kepada orang lain"],["عَدُوٌّ","(akan menjadi) musuh"],["إِلَّا","kecuali"],["ٱلْمُتَّقِينَ","orang yang soleh"]]],"4393":["(\"Hai hamba-hamba-Ku, tiada kekuatiran terhadap kalian pada hari ini dan tidak pula kalian bersedih hati.\")",[["يَـٰعِبَادِ","Wahai hamba-Ku"],["لَا","Tidak"],["خَوْفٌ","bertakwa"],["عَلَيْكُمُ","pada kamu"],["ٱلْيَوْمَ","Hari ini"],["وَلَآ","dan bukan"],["أَنتُمْ","kamu"],["تَحْزَنُونَ","akan bersedih"]]],"4394":["(Yaitu orang-orang yang beriman) lafal ayat ini menjadi Na'at atau sifat bagi lafal 'Ibaadi' pada ayat di atas (kepada ayat-ayat Kami) yakni Alquran (dan adalah mereka dahulu orang-orang yang berserah diri.)",[["ٱلَّذِينَ","Orang yang"],["ءَامَنُوا۟","beriman"],["بِـَٔايَـٰتِنَا","dalam Ayat-ayat Kami"],["وَكَانُوا۟","dan telah"],["مُسْلِمِينَ","tunduk"]]],"4395":["(Masuklah kalian ke dalam surga, kalian) lafal Antum berkedudukan menjadi Mubtada (dan pasangan-pasangan kalian) yakni istri-istri kalian (digembirakan) dibahagiakan dan dimuliakan, lafal Tuhbaruuna menjadi Khabar dari Mubtada.",[["ٱدْخُلُوا۟","Masuk"],["ٱلْجَنَّةَ","Syurga"],["أَنتُمْ","kamu"],["وَأَزْوَٰجُكُمْ","dan pasangan kamu"],["تُحْبَرُونَ","gembira"]]],"4396":["(Diedarkan kepada mereka piring-piring) yang besar-besar (dari emas, gelas-gelas) tempat untuk minum yang tidak ada pengikatnya hingga si peminum dapat meminum dari sebelah mana saja; lafal Akwaabun adalah bentuk jamak dari lafal Kuubun (dan di dalam surga itu terdapat segala apa yang diingini oleh hati) untuk dinikmati kelezatannya (dan sedap dipandang mata) artinya, sangat menyejukkan bila dipandang (dan kalian kekal di dalamnya.)",[["يُطَافُ","Akan diedarkan"],["عَلَيْهِم","bagi mereka"],["بِصِحَافٍۢ","pinggan"],["مِّن","daripada"],["ذَهَبٍۢ","emas"],["وَأَكْوَابٍۢ ۖ","dan cawan"],["وَفِيهَا","Dan di dalamnya"],["مَا","(ialah) apa"],["تَشْتَهِيهِ","keinginan"],["ٱلْأَنفُسُ","jiwa-jiwa"],["وَتَلَذُّ","dan nikmat"],["ٱلْأَعْيُنُ ۖ","mata"],["وَأَنتُمْ","dan kamu"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","akan kekal selama-lamanya"]]],"4397":["(Dan itulah surga yang diwariskan kepada kalian disebabkan amal-amal yang dahulu kalian kerjakan.)",[["وَتِلْكَ","Dan ini"],["ٱلْجَنَّةُ","(ialah) Syurga"],["ٱلَّتِىٓ","yang"],["أُورِثْتُمُوهَا","kamu dijadikan untuk mewarisi"],["بِمَا","bagi apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ","lakukan"]]],"4398":["(Di dalam surga itu ada buah-buahan yang banyak untuk kalian yang sebagiannya) sebagian daripadanya (kalian makan) dan setiap apa yang telah dimakan secara langsung mendapat penggantinya yang baru.",[["لَكُمْ","Untuk kamu"],["فِيهَا","di dalamnya"],["فَـٰكِهَةٌۭ","(adalah) buah-buahan"],["كَثِيرَةٌۭ","melimpah ruah"],["مِّنْهَا","daripadanya"],["تَأْكُلُونَ","kamu akan makan"]]],"4399":["(Sesungguhnya orang-orang yang berdosa kekal di dalam azab neraka Jahanam.)",[["إِنَّ","Sesungguhnya"],["ٱلْمُجْرِمِينَ","penjenayah"],["فِى","(akan) masuk"],["عَذَابِ","azab"],["جَهَنَّمَ","(dari) Neraka"],["خَـٰلِدُونَ","kekal selama-lamanya"]]],"4400":["(Tidak dihenti-hentikan) maksudnya, tidak diringankan (azab itu dari mereka sedangkan mereka di dalamnya berputus asa) yakni dalam keadaan diam berputus asa.",[["لَا","Tidak"],["يُفَتَّرُ","adakah ia akan reda"],["عَنْهُمْ","bagi mereka"],["وَهُمْ","dan mereka"],["فِيهِ","di dalamnya"],["مُبْلِسُونَ","(akan) putus asa"]]],"4401":["(Dan tidaklah Kami menganiaya mereka tetapi merekalah yang menganiaya diri mereka sendiri.)",[["وَمَا","Dan tidak"],["ظَلَمْنَـٰهُمْ","Kami menganiaya mereka"],["وَلَـٰكِن","tetapi"],["كَانُوا۟","mereka adalah"],["هُمُ","diri mereka"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"4402":["(Mereka berseru, \"Hai Malik!) dia adalah malaikat penjaga neraka (Biarlah Rabbmu membunuh kami saja\") maksudnya, mematikan kami. (Dia menjawab) seruan mereka setelah seribu tahun kemudian, (\"Kalian akan tetap tinggal\") di dalam azab yang abadi untuk selama-lamanya.",[["وَنَادَوْا۟","Dan mereka akan memanggil"],["يَـٰمَـٰلِكُ","Wahai Malik"],["لِيَقْضِ","Biarlah tamat"],["عَلَيْنَا","kepada kami"],["رَبُّكَ ۖ","Tuhanmu"],["قَالَ","Dia (akan) berkata"],["إِنَّكُم","Sesungguhnya kamu"],["مَّـٰكِثُونَ","(akan) kekal"]]],"4403":["Allah swt. berfirman: (Sesungguhnya Kami benar-benar telah membawa kepada kalian) hai penduduk Mekah (kebenaran) melalui lisan rasul (tetapi kebanyakan di antara kalian benci pada kebenaran itu.)",[["لَقَدْ","Sungguh"],["جِئْنَـٰكُم","Kami telah membawa kamu"],["بِٱلْحَقِّ","kebenaran"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَكُمْ","kebanyakan kamu"],["لِلْحَقِّ","kepada kebenaran"],["كَـٰرِهُونَ","(ada) enggan"]]],"4404":["(Bahkan mereka telah menetapkan) yaitu orang-orang kafir Mekah telah memutuskan (suatu tipu daya) kejahatan untuk mencelakakan Nabi Muhammad (maka sesungguhnya Kami menetapkan pula) keputusan Kami untuk membuat tipu muslihat guna membinasakan mereka.",[["أَمْ","Atau"],["أَبْرَمُوٓا۟","adakah mereka telah menentukan"],["أَمْرًۭا","satu urusan"],["فَإِنَّا","Kemudian sesungguhnya, Kami"],["مُبْرِمُونَ","(ada) ditentukan"]]],"4405":["(Apakah mereka mengira, bahwa Kami tidak mendengar rahasia dan bisikan-bisikan mereka) yakni apa-apa yang mereka rahasiakan dari orang lain dan apa-apa yang mereka perlihatkan dengan terang-terangan di antara sesama mereka sendiri. (Sebenarnya) Kami mendengar hal tersebut (dan utusan-utusan Kami) yakni malaikat-malaikat pencatat amal perbuatan (di sisi mereka) di sisi orang-orang kafir (selalu mencatat) hal tersebut.",[["أَمْ","Atau"],["يَحْسَبُونَ","(adakah) mereka fikir"],["أَنَّا","bahawa Kami"],["لَا","(boleh) tidak"],["نَسْمَعُ","dengar"],["سِرَّهُمْ","rahsia mereka"],["وَنَجْوَىٰهُم ۚ","dan peguam peribadi mereka"],["بَلَىٰ","Bahkan"],["وَرُسُلُنَا","dan Rasul-rasul Kami"],["لَدَيْهِمْ","bersama mereka"],["يَكْتُبُونَ","sedang merakam"]]],"4406":["(Katakanlah! Jika benar Tuhan Yang Maha Pemurah mempunyai anak) seumpamanya (maka akulah orang yang mula-mula menyembahnya) menyembah anak Tuhan itu, akan tetapi telah ditetapkan, bahwa tiada anak bagi-Nya, sehingga tiada pula penyembahan itu.",[["قُلْ","Katakanlah"],["إِن","Jika"],["كَانَ","telah"],["لِلرَّحْمَـٰنِ","Yang Maha Pemurah"],["وَلَدٌۭ","seorang anak lelaki"],["فَأَنَا۠","Kemudian, aku"],["أَوَّلُ","(akan menjadi) pertama"],["ٱلْعَـٰبِدِينَ","(dari) orang-orang yang beribadat"]]],"4407":["(Maha Suci Rabb Yang empunya langit dan bumi, Rabb Yang empunya Arasy) yakni Al-Kursi (dari apa yang mereka sifatkan) dari apa yang telah mereka katakan itu, berupa kedustaan terhadap-Nya, yaitu menisbatkan kepada-Nya mempunyai anak.",[["سُبْحَـٰنَ","Maha Suci"],["رَبِّ","(kepada) Tuhan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["رَبِّ","(yang) Tuhan"],["ٱلْعَرْشِ","(dari) Arasy"],["عَمَّا","atas apa"],["يَصِفُونَ","mereka menganggap"]]],"4408":["(Maka biarlah mereka tenggelam) dalam kesesatannya atau dalam kebatilannya (dan bermain-main) di dalam dunia mereka (sampai mereka menemui hari yang dijanjikan kepada mereka) yaitu azab yang dijanjikan kepada mereka pada hari kiamat nanti.",[["فَذَرْهُمْ","Jadi tinggalkan mereka"],["يَخُوضُوا۟","(untuk) bercakap-cakap dengan sia-sia"],["وَيَلْعَبُوا۟","dan bermain"],["حَتَّىٰ","sehingga"],["يُلَـٰقُوا۟","mereka berjumpa"],["يَوْمَهُمُ","Hari mereka"],["ٱلَّذِى","yang"],["يُوعَدُونَ","mereka dijanjikan"]]],"4409":["(Dan Dialah Tuhan yang disembah di langit) lafal Fis Samaa-i Ilaahun kedua huruf Hamzahnya dapat dibaca Tahqiq dan Tas-hil, yakni Tuhan yang disembah di langit (dan Tuhan yang disembah di bumi) kedua Zharaf yang ada dalam ayat ini berta'alluq kepada lafal sesudahnya (dan Dialah Yang Maha Bijaksana) di dalam mengatur makhluk-Nya (lagi Maha Mengetahui) kemaslahatan-kemaslahatan mereka.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["فِى","(berada) dalam"],["ٱلسَّمَآءِ","syurga itu"],["إِلَـٰهٌۭ","Tuhan"],["وَفِى","dan dalam"],["ٱلْأَرْضِ","bumi"],["إِلَـٰهٌۭ ۚ","Tuhan"],["وَهُوَ","Dan Dia"],["ٱلْحَكِيمُ","(ialah) Yang Maha Bijaksana"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"4410":["(Dan Maha Besar) Maha Agung (Tuhan Yang mempunyai kerajaan langit dan bumi; dan apa yang ada di antara keduanya; dan di sisi-Nyalah pengetahuan tentang hari kiamat) yakni kapan ia akan terjadi (dan hanya kepada-Nyalah kalian dikembalikan) lafal Turja'uuna dapat pula dibaca Yurja`uuna; berdasarkan qiraat kedua maka artinya: Dan hanya kepada-Nyalah mereka dikembalikan.",[["وَتَبَارَكَ","Dan diberkati (adalah)"],["ٱلَّذِى","yang Esa"],["لَهُۥ","kepada Siapa"],["مُلْكُ","(kepunyaan) kekuasaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَمَا","dan apa sahaja"],["بَيْنَهُمَا","(adalah) antara keduanya"],["وَعِندَهُۥ","dan dengan Dia"],["عِلْمُ","(ialah) pengetahuan"],["ٱلسَّاعَةِ","(dari) hari kiamat"],["وَإِلَيْهِ","dan kepada-Nya"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"4411":["(Dan tidaklah memiliki apa-apa yang mereka seru) yang mereka sembah, dimaksud adalah orang-orang kafir pelakunya (selain Dia) selain Allah (suatu syafaat pun) bagi seseorang (tetapi yang dapat memberi syafaat ialah orang yang mengakui yang hak) yakni orang yang telah mengatakan, \"Laa Ilaaha Illallaah\"/tiada Tuhan selain Allah (dan mereka mengetahui) apa yang mereka akui dengan kalbunya, yaitu yang telah diucapkan oleh lisannya. Yang dimaksud antara lain ialah Nabi Isa, Nabi Uzair dan malaikat-malaikat, sesungguhnya mereka dapat memberi syafaat kepada orang-orang yang beriman.",[["وَلَا","Dan tidak"],["يَمْلِكُ","mempunyai kuasa"],["ٱلَّذِينَ","mereka yang"],["يَدْعُونَ","mereka menyeru"],["مِن","selain Dia"],["دُونِهِ","selain Dia"],["ٱلشَّفَـٰعَةَ","(untuk) syafaat"],["إِلَّا","kecuali"],["مَن","yang"],["شَهِدَ","memberi keterangan"],["بِٱلْحَقِّ","kepada kebenaran"],["وَهُمْ","dan mereka"],["يَعْلَمُونَ","mengetahui"]]],"4412":["(Dan sungguh jika) huruf Lam di sini bermakna Qasam (kamu bertanya kepada mereka, \"Siapakah yang menciptakan mereka?\" Niscaya mereka menjawab, \"Allah\") lafal Layaquulunna dibuang daripadanya Nun alamat Rafa' dan Wawu Dhamir jamak, karena asalnya adalah Layaquuluunanna (maka bagaimanakah mereka dapat dipalingkan) sehingga mereka tidak mau menyembah Allah?",[["وَلَئِن","Dan jika"],["سَأَلْتَهُم","kamu bertanya kepada mereka"],["مَّنْ","yang"],["خَلَقَهُمْ","mencipta mereka"],["لَيَقُولُنَّ","mereka pasti akan berkata"],["ٱللَّهُ ۖ","Allah"],["فَأَنَّىٰ","Kemudian bagaimana"],["يُؤْفَكُونَ","adakah mereka tertipu"]]],"4413":["(Dan ucapannya) ucapan Nabi Muhammad; dinashabkannya lafal Qiilihi karena menjadi Mashdar yang dinashabkan oleh Fi'ilnya yang Muqaddar atau diperkirakan keberadaannya; yakni, dan berkatalah dia, (\"Ya Rabbku! Sesungguhnya mereka itu adalah kaum yang tidak beriman.\")",[["وَقِيلِهِۦ","Dan ucapannya"],["يَـٰرَبِّ","Wahai Tuhanku"],["إِنَّ","Sesungguhnya"],["هَـٰٓؤُلَآءِ","ini"],["قَوْمٌۭ","(adalah) suatu kaum"],["لَّا","(yang melakukannya) tidak"],["يُؤْمِنُونَ","beriman"]]],"4414":["Lalu Allah swt. berfirman: (Maka berpalinglah) artinya palingkanlah dirimu (dari mereka dan katakanlah, \"Salam\") selamat tinggal bagi kalian. Ayat ini diturunkan sebelum diperintah untuk memerangi mereka (Kelak mereka akan mengetahui) ayat ini mengandung ancaman buat mereka; dan dapat dibaca Ya'lamuuna atau Ta'lamuuna, kalau dibaca Ta'lamuuna artinya, kelak kalian akan mengetahui.",[["فَٱصْفَحْ","Jadi berpalinglah"],["عَنْهُمْ","daripada mereka"],["وَقُلْ","dan katakan"],["سَلَـٰمٌۭ ۚ","Damai"],["فَسَوْفَ","Tetapi tidak lama lagi"],["يَعْلَمُونَ","mereka akan tahu"]]],"4415":["(Ha Mim) hanya Allah sajalah yang mengetahui arti dan maksudnya.",[["حمٓ","Ha Mim"]]],"4416":["(Demi Alkitab) yaitu Alquran (yang menjelaskan) yang memenangkan perkara yang halal atas perkara yang haram.",[["وَٱلْكِتَـٰبِ","Oleh Kitab"],["ٱلْمُبِينِ","yang jelas"]]],"4417":["(Sesungguhnya Kami menurunkannya pada suatu malam yang diberkati) yaitu Lailatulkadar, atau malam pertengahan bulan Syakban. Pada malam tersebut diturunkanlah Alquran dari Umul Kitab atau Lohmahfuz yaitu dari langit yang ketujuh hingga ke langit dunia (sesungguhnya Kamilah yang memberi peringatan) yang memperingatkan manusia dengan Alquran.",[["إِنَّآ","Sesungguhnya Kami"],["أَنزَلْنَـٰهُ","mendedahkannya"],["فِى","dalam"],["لَيْلَةٍۢ","sebuah Malam"],["مُّبَـٰرَكَةٍ ۚ","diberkati"],["إِنَّا","Sesungguhnya Kami"],["كُنَّا","[Kami] adalah"],["مُنذِرِينَ","(pernah) amaran"]]],"4418":["(Pada malam itu) yakni pada malam Lailatulkadar, atau malam pertengahan bulan Syakban (dijelaskan) dirincikan (segala urusan yang penuh hikmah) segala urusan yang telah ditentukan, yaitu berupa rezeki dan ajal serta perkara-perkara lainnya, mulai dari malam itu sampai dengan malam yang sama untuk tahun berikutnya.",[["فِيهَا","Di dalamnya"],["يُفْرَقُ","dibuat tersendiri"],["كُلُّ","setiap"],["أَمْرٍ","urusan"],["حَكِيمٍ","bijak"]]],"4419":["(Yaitu urusan yang besar) rinciannya (dari sisi Kami. Sesungguhnya Kami adalah yang mengutus rasul-rasul) Nabi Muhammad dan rasul-rasul sebelumnya.",[["أَمْرًۭا","Sebuah perintah"],["مِّنْ","daripada"],["عِندِنَآ ۚ","Kami"],["إِنَّا","Sesungguhnya Kami"],["كُنَّا","[Kami] adalah"],["مُرْسِلِينَ","(pernah) menghantar"]]],"4420":["(Sebagai rahmat) maksudnya, karena belas kasihan kepada manusia diutuslah rasul-rasul kepada mereka (dari Rabbmu. Sesungguhnya Dialah Yang Maha Mendengar) perkataan-perkataan mereka (lagi Maha Mengetahui) perbuatan-perbuatan mereka.",[["رَحْمَةًۭ","Sebagai Rahmat"],["مِّن","daripada"],["رَّبِّكَ ۚ","Tuhanmu"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","[Dia]"],["ٱلسَّمِيعُ","(ialah) Yang Maha Mendengar"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"4421":["(Rabb yang memelihara langit dan bumi dan apa yang ada di antara keduanya) jika dibaca Rabbus Samaawaati berarti menjadi Khabar yang ketiga, jika dibaca Rabbis Samaawaati berarti menjadi Badal dari lafal Rabbika (jika kalian) hai penduduk Mekah (orang-orang yang meyakini) bahwasanya Dia adalah Rabb langit dan bumi, maka yakinilah bahwa Muhammad itu adalah rasul-Nya.",[["رَبِّ","Tuhan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَمَا","dan apa sahaja"],["بَيْنَهُمَآ ۖ","(adalah) antara keduanya"],["إِن","jika"],["كُنتُم","kamu"],["مُّوقِنِينَ","pasti"]]],"4422":["(Tidak ada tuhan melainkan Dia, Yang menghidupkan dan Yang mematikan Dialah Rabb kalian dan Rabb bapak-bapak kalian yang terdahulu).",[["لَآ","(Ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ","Dia"],["يُحْىِۦ","Dia memberi kehidupan"],["وَيُمِيتُ ۖ","dan menyebabkan kematian"],["رَبُّكُمْ","Tuhanmu"],["وَرَبُّ","dan (yang) Tuhan"],["ءَابَآئِكُمُ","(dari) bapa-bapa kamu"],["ٱلْأَوَّلِينَ","yang dahulu"]]],"4423":["(Tetapi mereka dalam keragu-raguan) tentang adanya hari berbangkit (adalah orang-orang yang bermain-main) dengan maksud mengejek kamu, hai Muhammad. Maka Nabi berdoa, \"Ya Allah! Bantulah aku untuk menghadapi mereka, timpakanlah kepada mereka paceklik selama tujuh tahun sebagaimana paceklik yang diminta oleh Nabi Yusuf.\"",[["بَلْ","Bahkan"],["هُمْ","mereka"],["فِى","(ada) dalam"],["شَكٍّۢ","keraguan"],["يَلْعَبُونَ","bermain"]]],"4424":["(Maka tunggulah hari ketika langit membawa kabut yang nyata) maka kala itu bumi menjadi tandus kelaparan serta paceklik makin menjadi-jadi, sehingga karena memuncaknya keadaan, akhirnya mereka melihat seolah-olah ada sesuatu yang berupa kabut di antara langit dan bumi.",[["فَٱرْتَقِبْ","Kemudian tonton"],["يَوْمَ","(untuk) Hari"],["تَأْتِى","(apabila) akan membawa"],["ٱلسَّمَآءُ","langit"],["بِدُخَانٍۢ","asap"],["مُّبِينٍۢ","nampak"]]],"4425":["(Yang meliputi manusia) lalu mereka berkata, (\"Inilah azab yang pedih.)",[["يَغْشَى","menyelubungi"],["ٱلنَّاسَ ۖ","manusia"],["هَـٰذَا","Ini"],["عَذَابٌ","(akan menjadi) azab"],["أَلِيمٌۭ","yang pedih"]]],"4426":["('Ya Rabb kami! Lenyapkanlah dari kami azab ini, Sesungguhnya kami akan beriman\") atau percaya kepada nabi-Mu.",[["رَّبَّنَا","Wahai Tuhan kami"],["ٱكْشِفْ","Alih keluar"],["عَنَّا","daripada kami"],["ٱلْعَذَابَ","azab"],["إِنَّا","sesungguhnya, kita"],["مُؤْمِنُونَ","(adalah) orang yang beriman"]]],"4427":["(\"Bagaimana mereka dapat menerima peringatan) maksudnya, iman tidak akan bermanfaat buat mereka bila azab diturunkan (padahal telah datang kepada mereka seorang rasul yang memberi penjelasan) artinya yang jelas risalahnya.",[["أَنَّىٰ","Bagaimana boleh"],["لَهُمُ","(ada) untuk mereka"],["ٱلذِّكْرَىٰ","peringatan itu"],["وَقَدْ","apabila sesungguhnya"],["جَآءَهُمْ","telah datang kepada mereka"],["رَسُولٌۭ","seorang Rasul"],["مُّبِينٌۭ","yang nyata"]]],"4428":["(Kemudian mereka berpaling darinya dan berkata, \"Dia adalah seorang yang menerima ajaran) maksudnya dia diajari Alquran oleh orang lain (lagi pula dia seorang yang gila.\")",[["ثُمَّ","Kemudian"],["تَوَلَّوْا۟","mereka berpaling"],["عَنْهُ","daripada dia"],["وَقَالُوا۟","dan berkata"],["مُعَلَّمٌۭ","Satu mengajar"],["مَّجْنُونٌ","seorang lelaki gila"]]],"4429":["(Sesungguhnya kalau Kami lenyapkan siksaan itu) kelaparan dan paceklik itu dari mereka selama beberapa waktu (dalam waktu yang tidak lama) lalu Allah melenyapkan azab itu dari mereka (sesungguhnya kalian akan kembali) kepada kekafiran, dan memang mereka kembali lagi kepada kekafirannya.",[["إِنَّا","Sesungguhnya Kami"],["كَاشِفُوا۟","(akan) mengeluarkan"],["ٱلْعَذَابِ","azab"],["قَلِيلًا ۚ","sedikit"],["إِنَّكُمْ","sesungguhnya, kamu"],["عَآئِدُونَ","(akan) kembali"]]],"4430":["Ingatlah (hari ketika Kami menghantam dengan hantaman yang keras) yaitu pada perang Badar. (Sesungguhnya Kami Pemberi balasan) kepada orang-orang yang kafir itu. Lafal Al-Bathsyu artinya menghantam dengan keras.",[["يَوْمَ","(The) Hari"],["نَبْطِشُ","Kami akan rampas"],["ٱلْبَطْشَةَ","(dengan) rampasan itu"],["ٱلْكُبْرَىٰٓ","yang terhebat"],["إِنَّا","sesungguhnya, Kami"],["مُنتَقِمُونَ","(akan) mengambil pembalasan"]]],"4431":["(Sesungguhnya telah Kami coba) Kami uji (sebelum mereka kaum Firaun) berikut Firaun sendiri (dan telah datang kepada mereka seorang rasul) yaitu Nabi Musa.s. (yang mulia) di sisi Allah swt.",[["۞ وَلَقَدْ","Dan sungguh"],["فَتَنَّا","Kami cuba"],["قَبْلَهُمْ","sebelum mereka"],["قَوْمَ","kaum"],["فِرْعَوْنَ","(daripada) Firaun"],["وَجَآءَهُمْ","dan datang kepada mereka"],["رَسُولٌۭ","seorang Rasul"],["كَرِيمٌ","mulia"]]],"4432":["(Dengan berkata, \"Hendaknya) atau hendaknyalah (kalian tunaikan kepadaku) apa yang aku seru kalian untuk melakukannya, yaitu beriman kepada Allah. Maksudnya, tampakkanlah iman kalian kepadaku, hai (hamba-hamba Allah. Sesungguhnya aku adalah utusan Allah yang dipercaya kepada kalian) dipercaya untuk menyampaikan apa yang aku diutus untuknya.",[["أَنْ","Itu"],["أَدُّوٓا۟","Hantarkan"],["إِلَىَّ","kepada aku"],["عِبَادَ","(para) hamba"],["ٱللَّهِ ۖ","(milik) Allah"],["إِنِّى","Memang aku"],["لَكُمْ","kepada kamu"],["رَسُولٌ","seorang Rasul"],["أَمِينٌۭ","boleh dipercayai"]]],"4433":["(Dan Janganlah kalian menyombongkan diri) berlaku takabur (terhadap Allah) yaitu tidak menaati-Nya. (Sesungguhnya aku datang kepada kalian dengan membawa bukti) tanda bukti (yang nyata\") yang menunjukkan kebenaran risalahku. Tetapi sebaliknya mereka mengancam akan merajamnya.",[["وَأَن","Dan bahawa"],["لَّا","jangan"],["تَعْلُوا۟","tinggikan diri"],["عَلَى","terhadap"],["ٱللَّهِ ۖ","Allah"],["إِنِّىٓ","Sesungguhnya aku"],["ءَاتِيكُم","[Aku] telah datang kepada kamu"],["بِسُلْطَـٰنٍۢ","dengan kuasa"],["مُّبِينٍۢ","yang nyata"]]],"4434":["Maka berdoalah Nabi Musa, (\"Dan sesungguhnya aku berlindung kepada Rabbku dan Rabb kalian, dari keinginan kalian merajamku) dengan batu.",[["وَإِنِّى","Dan sesungguhnya, aku"],["عُذْتُ","[Aku] mencari perlindungan"],["بِرَبِّى","dengan Tuhanku"],["وَرَبِّكُمْ","dan Tuhanmu"],["أَن","jangan-jangan"],["تَرْجُمُونِ","kamu rejam aku"]]],"4435":["(Dan jika kalian tidak beriman kepadaku) tidak percaya kepadaku (maka biarkanlah aku\") artinya, janganlah kalian menyakitiku, akan tetapi mereka tidak mau membiarkannya.",[["وَإِن","Dan jika"],["لَّمْ","tidak"],["تُؤْمِنُوا۟","kamu beriman"],["لِى","aku"],["فَٱعْتَزِلُونِ","kemudian tinggalkan aku sendiri"]]],"4436":["(Kemudian Musa berdoa kepada Rabbnya, \"Bahwasanya) (mereka ini adalah kaum yang berdosa\") orang-orang yang musyrik.",[["فَدَعَا","Jadi dia menelefon"],["رَبَّهُۥٓ","Tuhannya"],["أَنَّ","Itu"],["هَـٰٓؤُلَآءِ","ini"],["قَوْمٌۭ","(adalah) suatu kaum"],["مُّجْرِمُونَ","penjenayah"]]],"4437":["Maka Allah swt. berfirman, (\"Maka berjalanlah kamu) lafaz ini dapat dibaca Fa-asri atau Fasri (dengan membawa hamba-hamba-Ku) yaitu Bani Israel (pada malam hari, sesungguhnya kalian akan dikejar) oleh Firaun dan kaumnya.",[["فَأَسْرِ","Kemudian \"Berangkat"],["بِعِبَادِى","dengan hamba-hamba-Ku"],["لَيْلًا","(menjelang) malam"],["إِنَّكُم","Sesungguhnya kamu"],["مُّتَّبَعُونَ","(akan) diikuti"]]],"4438":["(Dan biarkanlah laut itu) apabila kamu dan pengikut-pengikutmu telah menempuhnya (terbelah) tenang dalam keadaan terbelah hingga orang-orang Koptik atau kaum Firaun memasukinya (sesungguhnya mereka adalah tentara yang akan ditenggelamkan\") maka tenanglah kamu jangan khawatir. Akhirnya mereka ditenggelamkan.",[["وَٱتْرُكِ","Dan pergi"],["ٱلْبَحْرَ","laut"],["رَهْوًا ۖ","sedang berehat"],["إِنَّهُمْ","Sesungguhnya mereka"],["جُندٌۭ","(adalah) tentera"],["مُّغْرَقُونَ","(akan) lemas"]]],"4439":["(Alangkah banyaknya taman yang mereka tinggalkan) yaitu kebun-kebun (dan mata air) yang mengalir.",[["كَمْ","berapa banyak"],["تَرَكُوا۟","(adakah) mereka pergi"],["مِن","daripada"],["جَنَّـٰتٍۢ","taman-taman"],["وَعُيُونٍۢ","dan mata air"]]],"4440":["(Dan kebun-kebun serta tempat-tempat yang indah-indah) atau tempat yang bagus.",[["وَزُرُوعٍۢ","Dan ladang jagung"],["وَمَقَامٍۢ","dan tempat"],["كَرِيمٍۢ","mulia"]]],"4441":["(Dan nikmat) kesenangan (yang dahulu mereka bergelimang di dalamnya) bersenang-senang di dalamnya.",[["وَنَعْمَةٍۢ","Dan perkara yang menyenangkan"],["كَانُوا۟","mereka dahulu"],["فِيهَا","di dalamnya"],["فَـٰكِهِينَ","bergembira"]]],"4442":["(Demikianlah) lafal Kadzaalika ini menjadi Khabar dari Mubtada; maksudnya, perkaranya demikianlah. (Dan Kami wariskan semua itu) yakni harta benda mereka (kepada kaum yang lain) yakni, kaum Bani Israel.",[["كَذَٰلِكَ ۖ","Demikianlah"],["وَأَوْرَثْنَـٰهَا","Dan Kami jadikan ia sebagai warisan."],["قَوْمًا","(untuk) suatu kaum"],["ءَاخَرِينَ","yang lain"]]],"4443":["(Maka langit dan bumi tidak menangisi mereka) berbeda dengan orang-orang yang beriman, jika mereka mati tanah tempat salat mereka menangisinya dan langit tempat naiknya amal mereka menangisinya pula (dan mereka pun tidak diberi tangguh) diakhirkan tobatnya.",[["فَمَا","Dan tidak"],["بَكَتْ","menangis"],["عَلَيْهِمُ","bagi mereka"],["ٱلسَّمَآءُ","syurga itu"],["وَٱلْأَرْضُ","dan bumi"],["وَمَا","dan bukan"],["كَانُوا۟","mereka adalah"],["مُنظَرِينَ","diberi tangguh"]]],"4444":["(Dan sesungguhnya telah Kami selamatkan Bani Israel dari siksa yang menghinakan) yakni dari pembunuhan Firaun terhadap anak-anak laki-laki mereka dan perbudakannya terhadap anak-anak perempuan mereka.",[["وَلَقَدْ","Dan sungguh"],["نَجَّيْنَا","Kami menyelamatkan"],["بَنِىٓ","(the) Bani Israel"],["إِسْرَٰٓءِيلَ","(the) Bani Israel"],["مِنَ","daripada"],["ٱلْعَذَابِ","azab"],["ٱلْمُهِينِ","yang memalukan"]]],"4445":["(Dari siksaan Firaun) menurut suatu pendapat menjadi Badal dari lafal Al'Adzaabi yang ada pada ayat sebelumnya dengan memperkirakan adanya Mudhaf sebelumnya, yaitu lafal 'Adzaabi, lengkapnya Min 'Adzaabi Firaun, artinya: dari siksaan Firaun. Tetapi menurut pendapat lain ia menjadi Hal atau kata keterangan keadaan dari lafal Al 'Adzaabi (sesungguhnya dia adalah orang yang sombong lagi salah seorang dari orang-orang yang melampaui batas.)",[["مِن","daripada"],["فِرْعَوْنَ ۚ","Firaun"],["إِنَّهُۥ","Sesungguhnya dia"],["كَانَ","adalah"],["عَالِيًۭا","sombong"],["مِّنَ","antara"],["ٱلْمُسْرِفِينَ","orang yang melampaui batas"]]],"4446":["(Dan sesungguhnya telah Kami pilih mereka) yaitu kaum Bani Israel (dengan pengetahuan) Kami yang mengetahui semua keadaan mereka (atas orang-orang yang pandai) di zamannya, yakni mereka dipilih menjadi orang-orang yang lebih pandai daripada orang-orang yang pandai di zamannya.",[["وَلَقَدِ","Dan sungguh"],["ٱخْتَرْنَـٰهُمْ","Kami memilih mereka"],["عَلَىٰ","oleh"],["عِلْمٍ","pengetahuan"],["عَلَى","atas"],["ٱلْعَـٰلَمِينَ","dunia"]]],"4447":["(Dan sesungguhnya Kami telah memberikan kepada mereka di antara tanda-tanda kekuasaan Kami sesuatu yang di dalamnya terdapat cobaan yang nyata) yang dimaksud adalah nikmat yang nyata, yaitu dapat dibelahnya laut, diturunkannya manna dan salwa serta mukjizat-mukjizat lainnya.",[["وَءَاتَيْنَـٰهُم","Dan Kami beri mereka"],["مِّنَ","daripada"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["مَا","bahawa"],["فِيهِ","di dalamnya"],["بَلَـٰٓؤٌۭا۟","(adalah) percubaan"],["مُّبِينٌ","yang nyata"]]],"4448":["(Sesungguhnya mereka itu) yakni orang-orang kafir Mekah (benar-benar berkata,)",[["إِنَّ","Sesungguhnya"],["هَـٰٓؤُلَآءِ","ini"],["لَيَقُولُونَ","pasti, kata mereka"]]],"4449":["(\"Tidak ada kematian) yang sesudahnya ada kehidupan lagi (selain kematian di dunia ini) sewaktu mereka masih dalam keadaan berupa air mani. (Dan kami sekali-kali tidak akan dibangkitkan) tidak akan dihidupkan kembali sesudah kematian yang pertama tadi.",[["إِنْ","Tidak"],["هِىَ","ia"],["إِلَّا","(adalah) tetapi"],["مَوْتَتُنَا","kematian kita"],["ٱلْأُولَىٰ","yang pertama"],["وَمَا","dan bukan"],["نَحْنُ","kita"],["بِمُنشَرِينَ","(akan) dibangkitkan semula"]]],"4450":["(Maka datangkanlah bapak-bapak kami) dalam keadaan hidup (jika kalian memang orang-orang yang benar\") bahwasanya kami akan dibangkitkan menjadi hidup kembali sesudah kami mati.",[["فَأْتُوا۟","Kemudian bawa"],["بِـَٔابَآئِنَآ","nenek moyang kita"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"4451":["Allah swt. berfirman, (\"Apakah mereka yang lebih baik ataukah kaum Tubba'\") Tubba' adalah seorang nabi atau seorang yang saleh (dan orang-orang yang sebelum mereka) umat-umat sebelum mereka (Kami telah membinasakan mereka) karena kekafiran mereka. Makna ayat, bahwasanya orang-orang musyrik itu tidaklah lebih kuat daripada mereka, dan ternyata mereka pun telah dibinasakan (karena sesungguhnya mereka adalah orang-orang yang berdosa.)",[["أَهُمْ","Adakah mereka"],["خَيْرٌ","lebih baik"],["أَمْ","atau"],["قَوْمُ","kaum"],["تُبَّعٍۢ","(daripada) Tubba"],["وَٱلَّذِينَ","dan mereka"],["مِن","sebelum mereka"],["قَبْلِهِمْ ۚ","sebelum mereka"],["أَهْلَكْنَـٰهُمْ ۖ","Kami memusnahkan mereka"],["إِنَّهُمْ","sesungguhnya, mereka"],["كَانُوا۟","adalah"],["مُجْرِمِينَ","penjenayah"]]],"4452":["(Dan Kami tidak menciptakan langit dan bumi dan apa yang ada di antara keduanya dengan bermain-main) dalam menciptakan hal tersebut; lafal Laa`ibiina menjadi Hal atau kata keterangan keadaan.",[["وَمَا","Dan tidak"],["خَلَقْنَا","Kami mencipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["وَمَا","dan apa sahaja"],["بَيْنَهُمَا","(adalah) di antara mereka"],["لَـٰعِبِينَ","(dalam) bermain"]]],"4453":["(Kami tidak menciptakan keduanya) dan apa yang ada di antara keduanya (melainkan dengan hak) dengan sebenarnya, daripadanya dapat disimpulkan tentang kekuasaan dan keesaan Kami, dan hal-hal lainnya (tetapi kebanyakan mereka) yaitu orang-orang kafir Mekah (tidak mengetahui.)",[["مَا","Tidak"],["خَلَقْنَـٰهُمَآ","Kami mencipta kedua-duanya"],["إِلَّا","tetapi"],["بِٱلْحَقِّ","dalam kebenaran"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"4454":["(Sesungguhnya hari keputusan itu) yakni hari kiamat adalah hari di mana Allah memutuskan perkara di antara hamba-hamba-Nya (adalah waktu yang dijanjikan bagi mereka semuanya) untuk menerima azab yang abadi.",[["إِنَّ","Sesungguhnya"],["يَوْمَ","(the) Hari Kiamat"],["ٱلْفَصْلِ","(the) Hari Kiamat"],["مِيقَـٰتُهُمْ","(adalah) tempoh yang ditetapkan untuk mereka"],["أَجْمَعِينَ","semua"]]],"4455":["(Yaitu hari yang seorang karib tidak dapat memberi manfaat kepada karibnya) baik karib karena hubungan kerabat atau karib karena hubungan persahabatan yang dekat. Ia tidak akan dapat membelanya (sedikit pun) dari azab itu (dan mereka tidak akan mendapat pertolongan) maksudnya tidak dapat dicegah dari azab itu. Lafal Yauma dalam ayat ini menjadi Badal dari lafal Yaumal Fashli pada ayat sebelumnya.",[["يَوْمَ","(The) Hari"],["لَا","tidak"],["يُغْنِى","akan mendapat manfaat"],["مَوْلًى","sesuatu perhubungan"],["عَن","bagi"],["مَّوْلًۭى","sesuatu perhubungan"],["شَيْـًۭٔا","sesuatu"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يُنصَرُونَ","akan dibantu"]]],"4456":["(Kecuali orang yang diberi rahmat oleh Allah) mereka adalah orang-orang mukmin, sebagian dari mereka dapat memberikan syafaat kepada sebagian lainnya dengan seizin Allah. (Sesungguhnya Dialah Yang Maha Perkasa) Maha Menang di dalam pembalasan-Nya terhadap orang-orang kafir (lagi Maha Penyayang) terhadap orang-orang mukmin.",[["إِلَّا","Kecuali"],["مَن","(pada) siapa"],["رَّحِمَ","Allah mempunyai rahmat"],["ٱللَّهُ ۚ","Allah mempunyai rahmat"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","[Dia]"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"4457":["(Sesungguhnya pohon zaqqum itu) zaqqum adalah pohon yang paling buruk dan sangat pahit rasanya yang tumbuh di daerah Tihamah, kelak Allah akan menumbuhkannya pula di dasar neraka Jahim.",[["إِنَّ","Sesungguhnya"],["شَجَرَتَ","(the) pokok"],["ٱلزَّقُّومِ","(dari) Zaqqum"]]],"4458":["(Makanan orang yang banyak dosa) seperti Abu Jahal dan teman-temannya.",[["طَعَامُ","(Akan menjadi) makanan"],["ٱلْأَثِيمِ","(dari) orang berdosa"]]],"4459":["(Ia bagaikan kotoran minyak) yakni hitam pekat bagaikan kotoran minyak; lafal ayat ini menjadi Khabar kedua (yang mendidih di dalam perut) jika dibaca Taghli berarti menjadi Khabar ketiga, jika dibaca Yaghli berarti menjadi Hal atau kata keterangan keadaan bagi lafal Al-Muhli.",[["كَٱلْمُهْلِ","Seperti minyak yang keruh"],["يَغْلِى","ia akan mendidih"],["فِى","dalam"],["ٱلْبُطُونِ","perut"]]],"4460":["(Seperti mendidihnya air yang amat panas) panasnya bagaikan air yang sangat panas.",[["كَغَلْىِ","Seperti mendidih"],["ٱلْحَمِيمِ","(dari) air yang mendidih"]]],"4461":["(Peganglah dia) dikatakan kepada malaikat Zabaniyah, \"Peganglah orang yang berdosa (kemudian seretlah dia) dapat dibaca Fa'tiluuhu atau Fa'tuluuhu artinya, seretlah dia dengan keras dan kasar (ke tengah-tengah jahim) ke tengah-tengah neraka.",[["خُذُوهُ","Tangkap dia"],["فَٱعْتِلُوهُ","dan seret dia"],["إِلَىٰ","ke dalam"],["سَوَآءِ","(the) tengah"],["ٱلْجَحِيمِ","(dari) api Neraka"]]],"4462":["(Kemudian tuangkanlah di atas kepalanya siksaan dari air yang amat panas) sehingga azab tiada henti-hentinya menimpa mereka dan tidak pernah berpisah darinya. Pengertian ayat ini lebih keras daripada apa yang diungkapkan dalam ayat lain, yaitu, \"Disiramkan air yang sedang mendidih ke atas kepala mereka...\" (Q.S. Al-Hajj, 19).",[["ثُمَّ","Kemudian"],["صُبُّوا۟","tuangkan"],["فَوْقَ","atas"],["رَأْسِهِۦ","kepalanya"],["مِنْ","daripada"],["عَذَابِ","azab"],["ٱلْحَمِيمِ","(dari) air yang mendidih itu"]]],"4463":["Kemudian dikatakan kepadanya, \"(Rasakanlah) azab ini (sesungguhnya kamu orang yang perkasa lagi mulia\") menurut dugaan dan perkataanmu yang telah menyatakan, bahwa tiada seorang pun di antara penghuni kedua bukit itu, yakni kota Mekah, orang yang lebih perkasa dan lebih mulia daripada dirinya.",[["ذُقْ","rasa"],["إِنَّكَ","Sesungguhnya kamu"],["أَنتَ","[kamu] (adalah)"],["ٱلْعَزِيزُ","yang perkasa"],["ٱلْكَرِيمُ","yang mulia"]]],"4464":["Dan dikatakan kepada mereka, \"(Sesungguhnya ini) azab yang kalian rasakan ini (yang dahulu selalu kalian meragukannya\") yaitu meragukan keberadaannya.",[["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["مَا","(ialah) apa"],["كُنتُم","kamu pernah"],["بِهِۦ","[mengenainya]"],["تَمْتَرُونَ","keraguan"]]],"4465":["(Sesungguhnya orang-orang yang bertakwa berada di dalam tempat) atau kedudukan (yang aman) dari semua hal-hal yang menakutkan.",[["إِنَّ","Sesungguhnya"],["ٱلْمُتَّقِينَ","orang yang soleh"],["فِى","(akan) masuk"],["مَقَامٍ","sebuah tempat"],["أَمِينٍۢ","selamat"]]],"4466":["(Yaitu di dalam taman-taman) kebun-kebun (dan mata air-mata air.)",[["فِى","Dalam"],["جَنَّـٰتٍۢ","taman-taman"],["وَعُيُونٍۢ","dan mata air"]]],"4467":["(Mereka memakai sutera yang halus dan sutera yang tebal) (seraya berhadap-hadapan) lafal Mutaqaabiliina adalah Hal atau kata keterangan keadaan, yakni, sebagian dari mereka tidak dapat melihat tengkuk sebagian yang lain, karena dipan-dipan tempat mereka duduk berbentuk bundar.",[["يَلْبَسُونَ","Memakai pakaian"],["مِن","daripada"],["سُندُسٍۢ","sutera halus"],["وَإِسْتَبْرَقٍۢ","dan sutera berat"],["مُّتَقَـٰبِلِينَ","berdepan antara satu sama lain"]]],"4468":["(Demikianlah) sebelum lafal ini diperkirakan adanya lafal Al-Amru, yakni perkaranya demikianlah. (Dan Kami kawinkan mereka) dijodohkan atau mereka dibuat senang (dengan bidadari-bidadari) dengan wanita yang putih kulitnya dan jeli matanya serta sangat cantik rupanya.",[["كَذَٰلِكَ","Demikianlah"],["وَزَوَّجْنَـٰهُم","Dan Kami akan mengahwini mereka"],["بِحُورٍ","(kepada) sahabat yang bermata indah"],["عِينٍۢ","(kepada) sahabat yang bermata indah"]]],"4469":["(Mereka meminta) meminta kepada para pelayan surga (di dalamnya) di dalam surga, supaya para pelayan itu mendatangkan buat mereka (segala macam buah-buahan) surga (dengan aman) dari kehabisan dan dari kemudaratannya, serta aman dari segala kekhawatiran. Lafal Aaminiina berkedudukan menjadi Hal atau kata keterangan keadaan.",[["يَدْعُونَ","Mereka akan memanggil"],["فِيهَا","di dalamnya"],["بِكُلِّ","untuk setiap (jenis)"],["فَـٰكِهَةٍ","(daripada) buah-buahan"],["ءَامِنِينَ","selamat"]]],"4470":["(Mereka tidak akan merasakan mati di dalamnya kecuali mati yang pertama) yaitu kematian sewaktu di dunia. Sebagian ahli tafsir ada yang mengatakan bahwa lafal Illaa di sini bermakna Ba'da, yakni sesudah. (Dan Allah memelihara mereka dari azab neraka.)",[["لَا","Tidak"],["يَذُوقُونَ","mereka akan rasa"],["فِيهَا","di dalamnya"],["ٱلْمَوْتَ","kematian itu"],["إِلَّا","kecuali"],["ٱلْمَوْتَةَ","kematian itu"],["ٱلْأُولَىٰ ۖ","yang pertama"],["وَوَقَىٰهُمْ","Dan Dia akan melindungi mereka"],["عَذَابَ","(dari) hukuman"],["ٱلْجَحِيمِ","(dari) api Neraka"]]],"4471":["(Sebagai karunia) lafal Fadhlan adalah Mashdar yang bermakna Tafadhdhulan, yakni pemberian karunia; dinashabkan oleh lafal Tafadhdhala yang diperkirakan keberadaannya sebelumnya (dari Rabbmu Yang demikian itu adalah keberuntungan yang besar.)",[["فَضْلًۭا","Sebuah Bounty"],["مِّن","daripada"],["رَّبِّكَ ۚ","Tuhanmu"],["ذَٰلِكَ","Itu"],["هُوَ","ia"],["ٱلْفَوْزُ","(akan menjadi) kejayaan"],["ٱلْعَظِيمُ","yang hebat"]]],"4472":["(Sesungguhnya Kami mudahkan ia) Kami mudahkan Alquran itu (dengan bahasamu) dengan bahasa Arab supaya orang-orang Arab dapat memahaminya darimu (supaya mereka mendapat pelajaran) supaya mereka dapat mengambilnya sebagai nasihat, karena itu lalu mereka beriman kepadamu; tetapi ternyata mereka tidak juga mau beriman.",[["فَإِنَّمَا","Sesungguhnya"],["يَسَّرْنَـٰهُ","Kami telah memudahkannya"],["بِلِسَانِكَ","dalam lidah kamu"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَتَذَكَّرُونَ","ambil iktibar"]]],"4473":["(Maka tunggulah) nantikanlah kebinasaan mereka (sesungguhnya mereka itu menunggu pula) kebinasaanmu. Ayat ini diturunkan sebelum ada perintah untuk berjihad melawan mereka.",[["فَٱرْتَقِبْ","Jadi tontonlah"],["إِنَّهُم","sesungguhnya, mereka"],["مُّرْتَقِبُونَ","(juga) menonton"]]],"4474":["(Ha Mim) hanya Allah sajalah yang mengetahui arti dan maksudnya.",[["حمٓ","Ha Mim"]]],"4475":["(Diturunkannya Kitab ini) yakni Alquran; lafal ayat ini berkedudukan menjadi Mubtada (dari Allah) menjadi Khabar dari Mubtada (Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya.",[["تَنزِيلُ","(The) wahyu"],["ٱلْكِتَـٰبِ","Kitab"],["مِنَ","(adalah) daripada"],["ٱللَّهِ","Allah"],["ٱلْعَزِيزِ","Yang Maha Perkasa"],["ٱلْحَكِيمِ","Yang Maha Bijaksana"]]],"4476":["(Sesungguhnya pada langit dan bumi) pada penciptaan keduanya (benar-benar terdapat tanda-tanda) yang menunjukkan kepada kekuasaan dan keesaan Allah swt. (bagi orang-orang yang beriman.)",[["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّلْمُؤْمِنِينَ","untuk orang yang beriman"]]],"4477":["(Dan pada penciptaan kalian) penciptaan masing-masing di antara kalian, yaitu mulai dari air mani, lalu berupa darah kental, kemudian segumpal daging, lalu menjadi manusia (dan) penciptaan (apa yang bertebaran) di muka bumi (berupa makhluk-makhluk yang melata) arti kata Ad-Daabbah adalah makhluk hidup yang melata di permukaan bumi, yaitu berupa manusia dan lain-lainnya (terdapat tanda-tanda kekuasaan Allah dan keesaan-Nya bagi kaum yang meyakini) adanya hari berbangkit.",[["وَفِى","Dan dalam"],["خَلْقِكُمْ","ciptaan kamu"],["وَمَا","dan apa"],["يَبُثُّ","Dia bersurai"],["مِن","daripada"],["دَآبَّةٍ","(the) makhluk yang bergerak"],["ءَايَـٰتٌۭ","(adalah) Tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يُوقِنُونَ","yang pasti"]]],"4478":["(Dan) pada (pergantian malam dan siang) yaitu datang dan perginya kedua waktu itu (dan rezeki yang diturunkan Allah dari langit) berupa hujan, dikatakan rezeki karena hujan itu merupakan penyebab rezeki (lalu dihidupkan-Nya dengan air hujan itu bumi sesudah matinya, dan pada pertukaran angin) atau pergantiannya, terkadang bertiup ke arah selatan, terkadang bertiup ke arah utara, terkadang datang membawa udara dingin, dan terkadang datang membawa udara panas (terdapat tanda-tanda pula bagi kaum yang berakal) yaitu tanda-tanda yang menunjukkan kekuasaan dan keesaan Allah, karenanya mereka beriman.",[["وَٱخْتِلَـٰفِ","Dan (dalam) silih berganti"],["ٱلَّيْلِ","(dari) malam"],["وَٱلنَّهَارِ","dan hari"],["وَمَآ","dan apa"],["أَنزَلَ","Allah turunkan"],["ٱللَّهُ","Allah turunkan"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مِن","daripada"],["رِّزْقٍۢ","(peruntukan)."],["فَأَحْيَا","dan memberi kehidupan"],["بِهِ","dengan itu"],["ٱلْأَرْضَ","(ke) bumi"],["بَعْدَ","selepas"],["مَوْتِهَا","kematiannya"],["وَتَصْرِيفِ","dan (dalam) mengarah"],["ٱلرِّيَـٰحِ","(the) angin"],["ءَايَـٰتٌۭ","(adalah) Tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَعْقِلُونَ","siapa alasan"]]],"4479":["(Itulah) yakni tanda-tanda yang telah disebutkan itu (ayat-ayat Allah) maksudnya, hujah-hujah-Nya yang menunjukkan kepada keesaan-Nya (yang Kami membacakannya) yang Kami ceritakan (kepadamu dengan sebenarnya) lafal Bil haqqi ber-ta'aluq kepada lafal Natluuhaa (maka dengan perkataan mana lagi sesudah Allah) sesudah firman-Nya, yang dimaksud adalah Alquran (dan keterangan-keterangan-Nya) atau hujah-hujah-Nya (mereka beriman) orang-orang kafir Mekah itu mereka tidak beriman. Menurut suatu qiraat lafal Yu'minuuna dibaca Tu'minuuna.",[["تِلْكَ","Ini"],["ءَايَـٰتُ","(adalah) Ayat-ayat"],["ٱللَّهِ","(milik) Allah"],["نَتْلُوهَا","Kami membacanya"],["عَلَيْكَ","kepada kamu"],["بِٱلْحَقِّ ۖ","dalam kebenaran"],["فَبِأَىِّ","Kemudian dalam apa"],["حَدِيثٍۭ","kenyataan"],["بَعْدَ","selepas"],["ٱللَّهِ","Allah"],["وَءَايَـٰتِهِۦ","dan ayat-ayatNya"],["يُؤْمِنُونَ","adakah mereka akan beriman"]]],"4480":["(Kecelakaan yang besarlah) lafal Al-Wail menunjukkan kalimat azab (bagi tiap-tiap orang yang banyak berdusta) atau pendusta (lagi banyak berdosa) banyak dosanya.",[["وَيْلٌۭ","celaka"],["لِّكُلِّ","kepada setiap"],["أَفَّاكٍ","penipu"],["أَثِيمٍۢ","berdosa"]]],"4481":["(Dia mendengar ayat-ayat Allah) yakni Alquran (dibacakan kepadanya kemudian dia tetap) atas kekafirannya (menyombongkan diri) takabur tidak mau beriman (seakan-akan dia tidak mendengarnya. Maka beri kabar gembiralah dia dengan azab yang pedih) azab yang menyakitkan.",[["يَسْمَعُ","Siapa dengar"],["ءَايَـٰتِ","(the) Ayat"],["ٱللَّهِ","(milik) Allah"],["تُتْلَىٰ","dibacakan"],["عَلَيْهِ","kepadanya"],["ثُمَّ","kemudian"],["يُصِرُّ","berterusan"],["مُسْتَكْبِرًۭا","dengan angkuh"],["كَأَن","seolah-olah"],["لَّمْ","tidak"],["يَسْمَعْهَا ۖ","dia mendengar mereka"],["فَبَشِّرْهُ","Maka sampaikanlah berita kepadanya"],["بِعَذَابٍ","(dari) hukuman"],["أَلِيمٍۢ","yang pedih"]]],"4482":["(Dan apabila dia mengetahui tentang ayat-ayat Kami) yakni Alquran (barang sedikit, maka ayat-ayat itu dijadikannya olok-olok) yakni menjadi bahan ejekan mereka. (Merekalah) orang-orang yang banyak mendustakan ayat-ayat Kami itu (yang memperoleh azab yang menghinakan) artinya, siksaan yang mengandung kehinaan.",[["وَإِذَا","Dan apabila"],["عَلِمَ","dia tahu"],["مِنْ","daripada"],["ءَايَـٰتِنَا","Ayat Kami"],["شَيْـًٔا","sesuatu"],["ٱتَّخَذَهَا","dia mengambil mereka"],["هُزُوًا ۚ","(dalam) ejekan"],["أُو۟لَـٰٓئِكَ","Itu"],["لَهُمْ","bagi mereka"],["عَذَابٌۭ","(ialah) azab"],["مُّهِينٌۭ","memalukan"]]],"4483":["(Di hadapan mereka) di sini diartikan di hadapan mereka sekalipun lafalnya mengatakan Min Waraa-ihim yakni di belakang mereka, hal ini mengingat mereka masih hidup di dunia (neraka Jahanam dan tidak akan berguna bagi mereka apa yang telah mereka upayakan) berupa harta benda dan hasil-hasil kerja mereka (barang sedikit pun, dan tidak pula berguna apa yang mereka jadikan selain dari Allah) yang dimaksud adalah berhala-berhala (sebagai sesembahan-sesembahan. Dan bagi mereka azab yang besar.)",[["مِّن","Sebelum mereka"],["وَرَآئِهِمْ","Sebelum mereka"],["جَهَنَّمُ ۖ","(ialah) Neraka"],["وَلَا","dan bukan"],["يُغْنِى","akan mendapat manfaat"],["عَنْهُم","mereka"],["مَّا","apa"],["كَسَبُوا۟","mereka telah memperoleh"],["شَيْـًۭٔا","sesuatu"],["وَلَا","dan bukan"],["مَا","apa"],["ٱتَّخَذُوا۟","mereka telah mengambil"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["أَوْلِيَآءَ ۖ","(sebagai) pelindung"],["وَلَهُمْ","Dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["عَظِيمٌ","yang besar"]]],"4484":["(Ini) Alquran ini (adalah petunjuk) dari kesesatan. (Dan orang-orang yang kafir kepada ayat-ayat Rabbnya bagi mereka azab) yakni bagian (yaitu siksa) atau azab (yang sangat pedih) sangat menyakitkan.",[["هَـٰذَا","Ini"],["هُدًۭى ۖ","(adalah) bimbingan"],["وَٱلَّذِينَ","Dan orang yang"],["كَفَرُوا۟","kufur"],["بِـَٔايَـٰتِ","dalam (the) Ayat"],["رَبِّهِمْ","(dari) Tuhan mereka"],["لَهُمْ","bagi mereka"],["عَذَابٌۭ","(ialah) azab"],["مِّن","daripada"],["رِّجْزٍ","kekotoran"],["أَلِيمٌ","yang pedih"]]],"4485":["(Allahlah yang menundukkan lautan untuk kalian supaya bahtera-bahtera dapat berlayar) yaitu perahu-perahu (padanya dengan perintah-Nya) dengan seizin-Nya (dan supaya kalian dapat mencari) melalui berdagang (sebagian karunia-Nya dan mudah-mudahan kalian bersyukur.)",[["۞ ٱللَّهُ","Allah"],["ٱلَّذِى","(ialah) Yang"],["سَخَّرَ","tertakluk"],["لَكُمُ","kepada kamu"],["ٱلْبَحْرَ","laut"],["لِتَجْرِىَ","yang mungkin belayar"],["ٱلْفُلْكُ","kapal-kapal itu"],["فِيهِ","di dalamnya"],["بِأَمْرِهِۦ","dengan Perintah-Nya"],["وَلِتَبْتَغُوا۟","dan supaya kamu mencari"],["مِن","daripada"],["فَضْلِهِۦ","Bounty-Nya"],["وَلَعَلَّكُمْ","dan supaya kamu boleh"],["تَشْكُرُونَ","bersyukurlah"]]],"4486":["(Dan Dia menundukkan untuk kalian apa yang ada di langit) berupa matahari bulan bintang-bintang, air hujan dan lain-lainnya (dan apa yang ada di bumi) berupa binatang-binatang, pohon-pohonan, tumbuh-tumbuhan, sungai-sungai dan lain-lainnya. Maksudnya, Dia menciptakan kesemuanya itu untuk dimanfaatkan oleh kalian (semuanya) lafal Jamii'an ini berkedudukan menjadi Taukid, atau mengukuhkan makna lafal sebelumnya (dari-Nya) lafal Minhu ini menjadi Hal atau kata keterangan keadaan, maksudnya semuanya itu ditundukkan oleh-Nya. (Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda kekuasaan dan keesaan Allah bagi kaum yang berpikir) mengenainya, karena itu lalu mereka beriman.",[["وَسَخَّرَ","Dan Dia telah menundukkan"],["لَكُم","kepada kamu"],["مَّا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["جَمِيعًۭا","semua"],["مِّنْهُ ۚ","daripadaNya"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya adalah tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَتَفَكَّرُونَ","yang berfikir"]]],"4487":["(Katakanlah kepada orang-orang yang beriman hendaklah mereka memaafkan orang-orang yang tiada mengharapkan) mereka yang tidak takut (akan hari-hari Allah) yaitu hari-hari di waktu Allah menimpakan azab kepada mereka. Maksudnya, maafkanlah orang-orang kafir atas perlakuan mereka terhadap diri kalian yang menyakitkan itu. Ayat ini diturunkan sebelum ada perintah untuk berjihad melawan mereka (karena Dia akan membalas) Allah akan membalas; menurut suatu qiraat dibaca Linajziya, artinya: karena Kami akan membalas (sesuatu kaum terhadap apa yang telah mereka kerjakan) atas pemaafannya terhadap orang-orang kafir yang telah menyakiti mereka.",[["قُل","Katakanlah"],["لِّلَّذِينَ","kepada mereka yang"],["ءَامَنُوا۟","beriman"],["يَغْفِرُوا۟","(untuk) memaafkan"],["لِلَّذِينَ","orang yang"],["لَا","jangan"],["يَرْجُونَ","harapan"],["أَيَّامَ","(untuk) hari"],["ٱللَّهِ","(milik) Allah"],["لِيَجْزِىَ","supaya Dia membalasnya"],["قَوْمًۢا","suatu kaum"],["بِمَا","bagi apa"],["كَانُوا۟","mereka dahulu"],["يَكْسِبُونَ","peroleh"]]],"4488":["(Barang siapa yang mengerjakan amal yang saleh maka itu adalah untuk dirinya sendiri) (dan barang siapa mengerjakan kejahatan, maka itu akan menimpa dirinya sendiri) (kemudian kepada Rabb kalianlah kalian dikembalikan) kalian akan dikembalikan kemudian orang yang berbuat baik dan orang yang berbuat jahat akan menerima balasannya masing-masing.",[["مَنْ","Siapa pun"],["عَمِلَ","tidak"],["صَـٰلِحًۭا","satu amal soleh"],["فَلِنَفْسِهِۦ ۖ","maka ia adalah untuk jiwanya"],["وَمَنْ","dan sesiapa"],["أَسَآءَ","melakukan kejahatan"],["فَعَلَيْهَا ۖ","maka ia (bertentangan) dengannya"],["ثُمَّ","Kemudian"],["إِلَىٰ","kepada"],["رَبِّكُمْ","Tuhanmu"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"4489":["(Dan sesungguhnya telah Kami berikan kepada Bani Israel Alkitab) yakni Taurat (dan hukum) yakni kitab Taurat sebagai sumber hukum untuk memutuskan perkara di antara orang-orang Bani Israel (dan kenabian) kepada Musa dan Harun, di antara mereka (dan Kami berikan kepada mereka rezeki-rezeki yang baik) atau rezeki-rezeki yang halal, yaitu manna dan salwa (dan Kami lebihkan mereka atas bangsa-bangsa) atas orang-orang pandai di zamannya.",[["وَلَقَدْ","Dan sungguh"],["ءَاتَيْنَا","Kami memberi"],["بَنِىٓ","(the) Bani Israel"],["إِسْرَٰٓءِيلَ","(the) Bani Israel"],["ٱلْكِتَـٰبَ","Kitab"],["وَٱلْحُكْمَ","dan hikmahnya"],["وَٱلنُّبُوَّةَ","dan kenabian"],["وَرَزَقْنَـٰهُم","dan Kami beri mereka rezeki"],["مِّنَ","daripada"],["ٱلطَّيِّبَـٰتِ","perkara yang baik"],["وَفَضَّلْنَـٰهُمْ","dan Kami lebihkan mereka"],["عَلَى","atas"],["ٱلْعَـٰلَمِينَ","dunia"]]],"4490":["(Dan Kami berikan kepada mereka keterangan-keterangan yang nyata tentang urusan) agama, menyangkut masalah halal dan haram, serta berita tentang akan diutusnya Nabi Muhammad saw. (maka mereka tidak berselisih) tentang diutusnya Nabi Muhammad (melainkan sesudah datang kepada mereka pengetahuan karena permusuhan di antara mereka) karena permusuhan yang ada di antara mereka sebab mereka dengki kepada Nabi Muhammad. (Sesungguhnya Rabbmu akan memutuskan antara mereka pada hari kiamat terhadap apa yang mereka selalu berselisih padanya.)",[["وَءَاتَيْنَـٰهُم","Dan Kami beri mereka"],["بَيِّنَـٰتٍۢ","bukti yang jelas"],["مِّنَ","daripada"],["ٱلْأَمْرِ ۖ","perkara itu"],["فَمَا","Dan tidak"],["ٱخْتَلَفُوٓا۟","mereka berbeza pendapat"],["إِلَّا","kecuali"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["مَا","[apa]"],["جَآءَهُمُ","datang kepada mereka"],["ٱلْعِلْمُ","pengetahuan itu"],["بَغْيًۢا","(daripada) dengki"],["بَيْنَهُمْ ۚ","antara mereka sendiri"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["يَقْضِى","akan menilai"],["بَيْنَهُمْ","antara mereka"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["فِيمَا","tentang apa"],["كَانُوا۟","mereka dahulu"],["فِيهِ","di dalamnya"],["يَخْتَلِفُونَ","berbeza"]]],"4491":["(Kemudian Kami jadikan kamu) hai Muhammad (berada di atas suatu syariat) yakni peraturan (dari urusan itu) dari urusan agama (maka ikutilah syariat itu dan janganlah kamu ikuti hawa nafsu orang-orang yang tidak mengetahui) untuk menyembah kepada selain Allah.",[["ثُمَّ","Kemudian"],["جَعَلْنَـٰكَ","Kami meletakkan kamu"],["عَلَىٰ","pada"],["شَرِيعَةٍۢ","cara yang telah ditetapkan"],["مِّنَ","daripada"],["ٱلْأَمْرِ","perkara itu"],["فَٱتَّبِعْهَا","jadi ikutilah"],["وَلَا","dan jangan"],["تَتَّبِعْ","ikut"],["أَهْوَآءَ","(the) keinginan"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"4492":["(Sesungguhnya mereka sekali-kali tidak akan dapat memberikan manfaat) mereka tidak akan dapat menolak (atas kamu dari siksaan Allah) yakni azab-Nya (barang sedikit pun. Dan sesungguhnya orang-orang yang zalim itu) orang-orang kafir itu (sebagian mereka menjadi penolong bagi sebagian yang lain dan Allah adalah Pelindung orang-orang yang bertakwa.)",[["إِنَّهُمْ","Sesungguhnya mereka"],["لَن","tidak pernah"],["يُغْنُوا۟","akan mendapat manfaat"],["عَنكَ","kamu"],["مِنَ","terhadap"],["ٱللَّهِ","Allah"],["شَيْـًۭٔا ۚ","(dalam) apa-apa"],["وَإِنَّ","Dan sesungguhnya"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["بَعْضُهُمْ","sebahagian mereka"],["أَوْلِيَآءُ","(adalah) sekutu"],["بَعْضٍۢ ۖ","(dari) orang lain"],["وَٱللَّهُ","dan Allah"],["وَلِىُّ","(ialah) Pelindung"],["ٱلْمُتَّقِينَ","(dari) orang-orang yang soleh"]]],"4493":["(Inilah) Alquran ini (adalah pedoman bagi manusia) artinya, sebagai pedoman yang dijadikan sumber bagi mereka dalam masalah hukum-hukum dan hudud (petunjuk dan rahmat bagi kaum yang meyakini) adanya hari berbangkit.",[["هَـٰذَا","Ini"],["بَصَـٰٓئِرُ","(ialah) pencerahan"],["لِلنَّاسِ","untuk manusia"],["وَهُدًۭى","dan bimbingan"],["وَرَحْمَةٌۭ","dan belas kasihan"],["لِّقَوْمٍۢ","bagi kaum"],["يُوقِنُونَ","yang pasti"]]],"4494":["(Apakah) lafal Am di sini maknanya sama dengan Hamzah yang menunjukkan makna ingkar (berprasangka orang-orang yang mengerjakan) orang-orang yang melakukan (kejahatan) kekafiran dan kemaksiatan (bahwa Kami akan menjadikan mereka seperti orang-orang yang beriman dan mengerjakan amal yang saleh, yaitu sama) lafal Sawaa-an ini menjadi Khabar (antara kehidupan dan kematian mereka?) menjadi Mubtada dan Ma'thuf, sedangkan Jumlah kalimat ini menjadi Badal dari huruf Kaf yang ada pada lafal Kalladziina, dan kedua Dhamirnya kembali kepada orang-orang kafir. Makna ayat, apakah mereka berprasangka bahwasanya Kami menjadikan mereka di akhirat sama dengan orang-orang mukmin, yaitu mereka hidup dalam kesejahteraan yang sama dengan kehidupan mereka sewaktu di dunia. Karena mereka telah mengatakan kepada orang-orang mukmin: \"Sungguh jika kami dibangkitkan hidup kembali, niscaya kami akan diberi kebaikan seperti apa yang diberikan kepada kalian.\" Lalu Allah berfirman menyangkal dugaan mereka sesuai dengan pengertian ingkar yang terkandung di dalam permulaan ayat. (Amat buruklah apa yang mereka sangka itu) maksudnya, perkara yang sebenarnya tidaklah demikian, karena sesungguhnya mereka di akhirat berada di dalam azab, berbeda dengan keadaan kehidupan mereka sewaktu di dunia. Sedangkan orang-orang mukmin di akhirat, mereka mendapatkan pahala yang berlimpah disebabkan amal perbuatan mereka sewaktu di dunia, yaitu berupa amal salat, amal zakat, amal puasa dan amal-amal lainnya. Huruf Maa pada ayat ini adalah Mashdariyah, yakni, seburuk-buruknya keputusan adalah keputusan mereka itu.",[["أَمْ","buat"],["حَسِبَ","fikir"],["ٱلَّذِينَ","orang yang"],["ٱجْتَرَحُوا۟","komited"],["ٱلسَّيِّـَٔاتِ","perbuatan jahat"],["أَن","bahawa"],["نَّجْعَلَهُمْ","Kami akan membuat mereka"],["كَٱلَّذِينَ","seperti mereka yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan lakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["سَوَآءًۭ","sama rata"],["مَّحْيَاهُمْ","(dalam) kehidupan mereka"],["وَمَمَاتُهُمْ ۚ","dan kematian mereka"],["سَآءَ","Jahat adalah"],["مَا","apa"],["يَحْكُمُونَ","mereka menilai"]]],"4495":["(Dan Allah menciptakan langit dan) menciptakan (bumi dengan tujuan yang benar) lafal Bil haqqi ber-ta'alluq kepada lafal Khalaqa; penciptaan langit dan bumi itu dimaksud untuk menunjukkan kekuasaan dan keesaan-Nya (dan agar dibalasi tiap-tiap diri terhadap apa yang dikerjakannya) yaitu kemaksiatan dan ketaatan yang dilakukannya, maka tidaklah sama balasan yang diterima orang kafir dan orang mukmin (dan mereka tidak akan dirugikan.)",[["وَخَلَقَ","Dan Allah menciptakan"],["ٱللَّهُ","Dan Allah menciptakan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["بِٱلْحَقِّ","dalam kebenaran"],["وَلِتُجْزَىٰ","dan itu boleh dibalas"],["كُلُّ","setiap"],["نَفْسٍۭ","jiwa"],["بِمَا","bagi apa"],["كَسَبَتْ","ia telah memperolehi"],["وَهُمْ","dan mereka"],["لَا","tidak akan dizalimi"],["يُظْلَمُونَ","tidak akan dizalimi"]]],"4496":["(Apakah kamu pernah melihat) maksudnya ceritakanlah kepadaku (orang yang menjadikan hawa nafsunya sebagai tuhannya) maksudnya, yang disukai oleh hawa nafsunya, yaitu batu demi batu ia ganti dengan yang lebih baik sebagai sesembahannya (dan Allah membiarkan-Nya sesat berdasarkan ilmu-Nya) berdasarkan pengetahuan Allah swt. Dengan kata lain Dia telah mengetahui, bahwa orang itu termasuk orang yang disesatkan sebelum ia diciptakan (dan Allah telah mengunci mati pendengaran dan hatinya) maka, karena itu ia tidak dapat mendengar petunjuk dan tidak mau memikirkannya (dan meletakkan tutupan atas penglihatannya) mengambil kegelapan hingga ia tidak dapat melihat petunjuk. Pada ayat ini diperkirakan adanya Maf'ul kedua bagi lafal Ra-ayta, yaitu lafal ayat tadi, yang artinya; apakah ia mendapat petunjuk? (Maka siapakah yang akan memberinya petunjuk sesudah Allah) membiarkannya sesat? Maksudnya, tentu saja ia tidak dapat petunjuk. (Maka mengapa kalian tidak mengambil pelajaran?) atau mengapa kalian tidak mau mengambilnya sebagai pelajaran buat kalian. Lafal Tadzakkaruuna asalnya salah satu dari huruf Ta-nya diidgamkan kepada huruf Dzal.",[["أَفَرَءَيْتَ","Pernahkah kamu melihat"],["مَنِ","(dia) siapa"],["ٱتَّخَذَ","mengambil"],["إِلَـٰهَهُۥ","(sebagai) tuhannya"],["هَوَىٰهُ","keinginannya"],["وَأَضَلَّهُ","dan Allah membiarkannya sesat"],["ٱللَّهُ","dan Allah membiarkannya sesat"],["عَلَىٰ","secara sedar"],["عِلْمٍۢ","secara sedar"],["وَخَتَمَ","dan Dia memeteraikan"],["عَلَىٰ","ke atas"],["سَمْعِهِۦ","pendengarannya"],["وَقَلْبِهِۦ","dan hatinya"],["وَجَعَلَ","dan meletakkan"],["عَلَىٰ","atas"],["بَصَرِهِۦ","penglihatannya"],["غِشَـٰوَةًۭ","sebuah tudung"],["فَمَن","Kemudian siapa"],["يَهْدِيهِ","akan membimbingnya"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["ٱللَّهِ ۚ","Allah"],["أَفَلَا","Kemudian tidak akan"],["تَذَكَّرُونَ","kamu menerima teguran"]]],"4497":["(Dan mereka berkata) yaitu orang-orang yang ingkar akan adanya hari berbangkit, (\"Kehidupan ini) kehidupan yang sebenarnya (tiada lain hanyalah kehidupan kita) yang kita alami (di dunia saja, kita mati dan kita hidup) sebagian dari kita mati kemudian sebagian yang lain hidup karena mereka dilahirkan (dan tiada yang membinasakan kita selain masa\") atau berlalunya masa. Lalu Allah berfirman menyangkal perkataan mereka melalui firman-Nya: (dan mereka tidak mempunyai mengenai hal itu) mengenai perkataan mereka yang demikian tadi (pengetahuan sedikit pun, tiada lain) tidak lain (mereka hanyalah menduga-duga saja.)",[["وَقَالُوا۟","Dan mereka berkata"],["مَا","Tidak"],["هِىَ","ia"],["إِلَّا","(adalah) tetapi"],["حَيَاتُنَا","hidup kita"],["ٱلدُّنْيَا","dunia"],["نَمُوتُ","kita mati"],["وَنَحْيَا","dan kita hidup"],["وَمَا","dan bukan"],["يُهْلِكُنَآ","membinasakan kita"],["إِلَّا","kecuali"],["ٱلدَّهْرُ ۚ","masa"],["وَمَا","Dan tidak"],["لَهُم","bagi mereka"],["بِذَٰلِكَ","daripada itu"],["مِنْ","sebarang"],["عِلْمٍ ۖ","pengetahuan"],["إِنْ","tidak"],["هُمْ","mereka"],["إِلَّا","(buat) tetapi"],["يَظُنُّونَ","meneka"]]],"4498":["(Dan apabila dibacakan kepada mereka ayat-ayat Kami) dari Alquran yang menunjukkan akan kekuasaan Kami yang mampu membangkitkan makhluk menjadi hidup kembali (yang jelas) yang keadaannya jelas sekali (tidak ada bantahan mereka selain dari mengatakan, \"Datangkanlah nenek moyang kami) dalam keadaan hidup (jika kalian adalah orang-orang yang benar\") bahwasanya kami benar-benar akan dibangkitkan menjadi hidup kembali sesudah kami mati.",[["وَإِذَا","Dan apabila"],["تُتْلَىٰ","dibacakan"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتُنَا","Ayat Kami"],["بَيِّنَـٰتٍۢ","yang nyata"],["مَّا","tidak"],["كَانَ","ialah"],["حُجَّتَهُمْ","hujah mereka"],["إِلَّآ","kecuali"],["أَن","bahawa"],["قَالُوا۟","mereka berkata"],["ٱئْتُوا۟","bawa"],["بِـَٔابَآئِنَآ","nenek moyang kita"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"4499":["(Katakanlah, \"Allahlah yang menghidupkan kalian) sewaktu kalian masih dalam bentuk air mani (kemudian mematikan kalian, setelah itu mengumpulkan kalian) dalam keadaan hidup (pada hari kiamat yang tidak ada keraguan padanya) tidak diragukan lagi kedatangannya (akan tetapi kebanyakan manusia) yang dimaksud adalah mereka yang telah mengatakan apa yang telah disebutkan tadi (tidak mengetahui.\")",[["قُلِ","Katakanlah"],["ٱللَّهُ","Allah"],["يُحْيِيكُمْ","memberi kamu kehidupan"],["ثُمَّ","kemudian"],["يُمِيتُكُمْ","menyebabkan kamu mati"],["ثُمَّ","kemudian"],["يَجْمَعُكُمْ","Dia akan mengumpulkan kamu"],["إِلَىٰ","kepada"],["يَوْمِ","(the) Hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["لَا","tidak"],["رَيْبَ","keraguan"],["فِيهِ","mengenainya"],["وَلَـٰكِنَّ","Tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","(daripada) rakyat"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"4500":["(Dan hanya kepunyaan Allahlah kerajaan langit dan bumi. Dan pada hari terjadinya kiamat) kemudian dijelaskan maksud sebenarnya oleh firman berikutnya, yaitu: (akan rugilah pada hari itu orang-orang yang mengerjakan kebatilan) yakni orang-orang kafir. Maksudnya, kerugian mereka akan tampak jelas karena mereka dimasukkan ke dalam neraka.",[["وَلِلَّهِ","Dan untuk Allah"],["مُلْكُ","(ialah) kekuasaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["وَيَوْمَ","dan (hari) itu"],["تَقُومُ","ditegakkan"],["ٱلسَّاعَةُ","Jam itu"],["يَوْمَئِذٍۢ","hari itu"],["يَخْسَرُ","akan kalah"],["ٱلْمُبْطِلُونَ","para pemalsu"]]],"4501":["(Dan pada hari itu kamu lihat tiap-tiap umat) tiap-tiap pemeluk suatu agama (berlutut) mereka berdiri pada lututnya, atau mereka membentuk kumpulan. (Tiap-tiap umat dipanggil untuk melihat kitabnya) untuk melihat catatan amalnya, lalu dikatakan kepada mereka, (\"Pada hari ini kalian diberi balasan terhadap apa yang telah kalian kerjakan\") sebagai pembalasannya.",[["وَتَرَىٰ","Dan kamu akan melihat"],["كُلَّ","setiap"],["أُمَّةٍۢ","bangsa"],["جَاثِيَةًۭ ۚ","melutut"],["كُلُّ","Setiap"],["أُمَّةٍۢ","bangsa"],["تُدْعَىٰٓ","akan dipanggil"],["إِلَىٰ","kepada"],["كِتَـٰبِهَا","rekodnya"],["ٱلْيَوْمَ","Hari ini"],["تُجْزَوْنَ","kamu akan mendapat balasan"],["مَا","(untuk) apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ","lakukan"]]],"4502":["(Inilah kitab catatan Kami) yakni kitab catatan malaikat pencatat amal perbuatan manusia (yang menuturkan terhadap kalian dengan benar. Sesungguhnya Kami telah menyuruh mencatat) menulis dan mengarsipkan (apa yang telah kalian kerjakan.)",[["هَـٰذَا","Ini"],["كِتَـٰبُنَا","Rekod kami"],["يَنطِقُ","bercakap"],["عَلَيْكُم","tentang kamu"],["بِٱلْحَقِّ ۚ","dalam kebenaran"],["إِنَّا","Sesungguhnya Kami"],["كُنَّا","[Kami] dulu"],["نَسْتَنسِخُ","transkripsi"],["مَا","apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ","lakukan"]]],"4503":["(Adapun orang-orang yang beriman dan mengerjakan amal yang saleh maka Rabb mereka memasukkan mereka ke dalam rahmat-Nya) yakni surga-Nya. (Itulah keberuntungan yang nyata) nyata lagi jelas keuntungannya.",[["فَأَمَّا","Kemudian untuk"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan lakukan"],["ٱلصَّـٰلِحَـٰتِ","[yang] amal soleh"],["فَيُدْخِلُهُمْ","akan mengakui mereka"],["رَبُّهُمْ","Tuhan mereka"],["فِى","dalam (ke)"],["رَحْمَتِهِۦ ۚ","rahmatNya"],["ذَٰلِكَ","Itu"],["هُوَ","[ia]"],["ٱلْفَوْزُ","(ialah) kejayaan"],["ٱلْمُبِينُ","yang nyata"]]],"4504":["(Dan adapun orang-orang yang kafir) dikatakan kepada mereka: (\"Maka apakah belum ada ayat-ayat-Ku) yakni Alquran (yang dibacakan kepada kalian lalu kalian menyombongkan diri) bersifat takabur terhadapnya (dan kalian jadi kaum yang berbuat dosa?\") jadi orang-orang yang kafir.",[["وَأَمَّا","Tetapi untuk"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["أَفَلَمْ","Kemudian tidak"],["تَكُنْ","Kemudian tidak"],["ءَايَـٰتِى","Ayat-ayat Aku"],["تُتْلَىٰ","dibacakan"],["عَلَيْكُمْ","kepada kamu"],["فَٱسْتَكْبَرْتُمْ","tetapi kamu bangga"],["وَكُنتُمْ","dan kamu menjadi"],["قَوْمًۭا","suatu kaum"],["مُّجْرِمِينَ","penjenayah"]]],"4505":["(Dan apabila dikatakan) kepada kalian hai orang-orang kafir, (\"Sesungguhnya janji Allah itu) mengenai hari berbangkit (adalah benar dan hari kiamat itu) dapat dibaca Was Saa'atu atau Was Saa'ata (tidak ada keraguan) tidak ada keragu-raguan (padanya,\" niscaya kalian menjawab, \"Kami tidak tahu apakah hari kiamat itu, tidak lain) tiada lain (kami hanya menduga-duga saja) menurut Iman Mubarrad, bahwa asal dari lafal In Nazhunnu Illaa Zhannan adalah In Nahnu Illaa Nazhunnu Zhannan, yang artinya: kami sekali-kali tidak lain hanyalah menduga-duga saja (dan Kami sekali-kali tidak meyakini\") bahwa hari kiamat itu benar-benar akan datang.",[["وَإِذَا","Dan apabila"],["قِيلَ","ia dikatakan"],["إِنَّ","Sesungguhnya"],["وَعْدَ","(the) Janji"],["ٱللَّهِ","(milik) Allah"],["حَقٌّۭ","(adalah) benar"],["وَٱلسَّاعَةُ","dan hari kiamat"],["لَا","(ada) tidak"],["رَيْبَ","keraguan"],["فِيهَا","mengenainya"],["قُلْتُم","kamu kata"],["مَّا","Tidak"],["نَدْرِى","kita tahu"],["مَا","apa"],["ٱلسَّاعَةُ","Jam (ialah)"],["إِن","Tidak"],["نَّظُنُّ","kita fikir"],["إِلَّا","kecuali"],["ظَنًّۭا","satu andaian"],["وَمَا","dan bukan"],["نَحْنُ","kita"],["بِمُسْتَيْقِنِينَ","(adalah) yakin"]]],"4506":["(Dan nyatalah) jelaslah (bagi mereka) di akhirat nanti (keburukan-keburukan dari apa yang mereka kerjakan) sewaktu di dunia, yang dimaksud adalah pembalasannya (dan menimpalah) turunlah (kepada mereka apa yang mereka selalu memperolok-olokkannya) yaitu, azab yang dahulu mereka selalu memperolok-olokkannya.",[["وَبَدَا","Dan (akan) muncul"],["لَهُمْ","kepada mereka"],["سَيِّـَٔاتُ","(yang) jahat"],["مَا","apa"],["عَمِلُوا۟","mereka lakukan"],["وَحَاقَ","dan (akan) menyelubungi"],["بِهِم","mereka"],["مَّا","apa"],["كَانُوا۟","mereka gunakan"],["بِهِۦ","[padanya]"],["يَسْتَهْزِءُونَ","(untuk) mengejek"]]],"4507":["(Dan dikatakan kepada mereka, \"Pada hari ini Kami melupakan kalian) Kami membiarkan kalian berada di dalam neraka (sebagaimana kalian telah melupakan pertemuan dengan hari kalian ini) yaitu kalian tidak mau beramal sebagai bekal untuk menghadapinya (dan tempat tinggal kalian ialah neraka dan kalian sekali-kali tidak memperoleh penolong\") yang dapat mencegah diri kalian dari azab neraka.",[["وَقِيلَ","Dan ia akan dikatakan"],["ٱلْيَوْمَ","Hari ini"],["نَنسَىٰكُمْ","Kami lupakan kamu"],["كَمَا","seperti"],["نَسِيتُمْ","kamu lupa"],["لِقَآءَ","(the) mesyuarat"],["يَوْمِكُمْ","(pada) hari kamu ini"],["هَـٰذَا","(pada) hari kamu ini"],["وَمَأْوَىٰكُمُ","dan tempat tinggal kamu"],["ٱلنَّارُ","(ialah) Api"],["وَمَا","dan bukan"],["لَكُم","bagi kamu"],["مِّن","sebarang"],["نَّـٰصِرِينَ","pembantu"]]],"4508":["(Yang demikian itu, karena sesungguhnya kalian menjadikan ayat-ayat Allah) Alquran (sebagai olok-olokan dan kalian telah ditipu oleh kehidupan dunia) sehingga kalian berani mengatakan bahwa tidak ada hari berbangkit dan tidak ada hari hisab (maka pada hari ini mereka tidak dikeluarkan) dapat dibaca Yukhrajuuna dan Yakhrujuuna, kalau dibaca Yakhrujuuna artinya mereka tidak dapat keluar (daripadanya) dari neraka (dan tidak pula mereka diberi kesempatan untuk bertobat) tidak dituntut untuk membuat amal keridaan terhadap Rabbnya, yaitu berupa tobat dan ketaatan kepada-Nya, karena pada hari itu hal-hal tersebut sudah tidak bermanfaat lagi.",[["ذَٰلِكُم","Itu"],["بِأَنَّكُمُ","(adalah) kerana kamu"],["ٱتَّخَذْتُمْ","mengambil"],["ءَايَـٰتِ","(the) Ayat"],["ٱللَّهِ","(milik) Allah"],["هُزُوًۭا","(dalam) ejekan"],["وَغَرَّتْكُمُ","dan menipu kamu"],["ٱلْحَيَوٰةُ","kehidupan"],["ٱلدُّنْيَا ۚ","dunia"],["فَٱلْيَوْمَ","Jadi Hari ini"],["لَا","tidak"],["يُخْرَجُونَ","mereka akan dilahirkan"],["مِنْهَا","daripadanya"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يُسْتَعْتَبُونَ","akan diminta bertenang"]]],"4509":["(Maka bagi Allahlah segala puji) sanjungan yang baik atas ketepatan ancaman-Nya terhadap orang-orang yang mendustakan-Nya (Rabb langit dan bumi, Rabb semesta alam) Pencipta hal-hal yang telah disebutkan tadi. Pengertian kata Al-'Aalam adalah semua yang selain Allah, diungkapkan dalam bentuk jamak mengingat jenisnya yang bermacam-macam dan lafal Rabb adalah Badal.",[["فَلِلَّهِ","Kemudian untuk Allah"],["ٱلْحَمْدُ","(adalah) segala pujian"],["رَبِّ","(yang) Tuhan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَرَبِّ","dan (yang) Tuhan"],["ٱلْأَرْضِ","(dari) bumi"],["رَبِّ","(yang) tuan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"4510":["(Dan bagi-Nyalah keagungan) kebesaran (di langit dan bumi) lafal Fis Samaawaati Wal Ardhi ini berkedudukan menjadi Hal atau kata keterangan keadaan; yakni keagungan yang ada pada keduanya. (Dialah Yang Maha Perkasa lagi Maha Bijaksana) sebagaimana yang telah dijelaskan pada penafsiran-penafsiran sebelumnya.",[["وَلَهُ","Dan untuk Dia"],["ٱلْكِبْرِيَآءُ","(ialah) kebesaran"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["وَهُوَ","dan Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]]});